--
-- 1. LEGACY FINANCE CASE WITHOUT COMPONENT RECORDS (found by the final outcome check, Worker BM task 2 item 7).
--    With the four TEST settings ON, a Candidate holding an old finance case whose case has no open component records
--    failed to prepare: private.pay_workbench_recovery_selection_overlay_apply_v1 raised
--    PAY_WORKBENCH_RECOVERY_COMPONENT_AUTHORITY_MISSING at SOURCE_PUBLISH and none of that Candidate's pay was shown.
--    Now that repayment row alone is a visible Blocked row, reason code LEGACY_FINANCE_CASE_COMPONENTS_MISSING
--    ("Legacy finance case needs component records - Office review"): GBP0 deducted, no pay headroom consumed, the case
--    left untouched (no component record is invented: Policy X). Every other row and Candidate is unchanged. The
--    other fail-closed component checks (identity incomplete/duplicate, capacity, penny reconciliation) are unchanged.
--    Settings OFF: this overlay is not used (NOT_V3_SEMANTIC_SOURCE), so nothing changes there.
-- 2. DEBT ORDER (user rulings 25 Q6-A and 31): oldest debt first = the date and time the debt was created (a loan: its
--    payout); same date -> created first; identical microsecond -> finance case id. IDENTICAL to Stage 3 WP3
--    (stage3/wp3/gen_tierc_order.py, s3p_wp3_order_key.sql sha256 744253cec565aa606e47eff0cf6d5d597eb68b002c7b0d9c2a2e7425e179c1dd): the key functions and the builder and
--    overlay-window replacements are WP3's text verbatim. A34 adds the same key to the settings-OFF legacy branch
--    (both overloads of public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1, two windows each), which
--    WP3 does not change. The builder's amounts, caps, floors and family precedence are unchanged.
-- 3. TYPE-SPECIFIC CAPS ON THE V8 ROUTE (user ruling 30; A34 v2). The V3 overlay (the money the V8 Draft takes, settings
--    ON) now allocates through private.pay_workbench_recovery_type_capped_allocate_v1: one sequential pass in the
--    order above; a loan or manual debt keeps the minimum take-home floor (case override, else the Candidate's
--    min_take_home_wtd) and its minimum earnings threshold, exactly as public._pay_finance_protected_recovery_allocate;
--    an overpayment is capped by pay headroom only; an excluded repayment consumes nothing (A30, ruling 29). Without a
--    floor or threshold the result is identical to the previous running window. The overlay window replaced here is
--    therefore no longer WP3's text (WP3's key is still the only order used).
-- 4. V8 CONSTITUENT FREEZE (user ruling 29; A34 v2). public.pay_workbench_draft_certificate_constituent_ref_page_v8
--    re-read a certified repayment with the PHYSICAL section and physical key columns; a repayment the overlay
--    promoted from blocked_for_pay (Office exclusion, or oldest-first across debt types) has NULL physical key columns
--    and ended WORKBENCH_CERTIFICATE_TAMPERED although the certificate admitted it. The freeze now uses the
--    certificate's own section rule and its own key ladder; rows with physical keys match exactly as before.
--
-- Base md5 (pg_get_functiondef, trailing newline stripped): builder f4e398042c013d748f306b3f957a2bfc, overlay 0e97b2ac428bf033998ca21a9fbd3f35,
--   revalidate(uuid,uuid) 35cb26469a7914164ec161a9770dae8a, revalidate(uuid,uuid,jsonb) eb86fd4044495b231eb211fcf399e8ce, modal 5b0dad2df43ecec357a834239ebf8009.
-- New md5 (before SET jit): builder e80164dbc972a43d043600fec07e9aa2 (= WP3), overlay 901ada7679870433cb70883666ef0b9c (WP3 order only: 5accf80ad04a6e787509c13ec80a3cc6),
--   revalidate(uuid,uuid) 14f1a8ebd50f92d1aca4515848f61290, revalidate(uuid,uuid,jsonb) 99ce59d626e95692e5243244e865a44e, modal cc6557330c20efaeeab8c4186e9b03d4.
-- Every new and changed routine gets SET jit = off; ACLs follow A25 (private owner-only, public service_role-only).
-- No payment, provider, settlement, remittance, email or webhook function is called or changed. Policy X: pre-Draft
-- Workbench only; no post-Draft artefact, frozen batch reader or economic key derivation is touched.
-- =====================================================================================================================

BEGIN;

-- ---------------------------------------------------------------------------------------------------
-- 2a. Order key (Stage 3 WP3, verbatim)
-- ---------------------------------------------------------------------------------------------------
-- User ruling 31 (Q6-A defined): a debt's age is the moment it was CREATED -- when the overpayment (or manual debt) was
-- raised = public.pay_advances.created_at; when the loan was paid out = the payout's completion,
-- public.pay_bank_transfers.completed_at_utc (via pay_advances.payout_transfer_id), else public.pay_batches.completed_at_utc
-- (via pay_advances.payout_pay_batch_id), else -- no payout completion recorded -- public.pay_advances.created_at.  Oldest
-- first; two debts of the same date go by the earlier creation timestamp (the key is that timestamp in microseconds).
-- There is no reference-number tie-break (the field does not exist); only an identical microsecond timestamp falls back
-- to the finance case id, for determinism.
CREATE OR REPLACE FUNCTION private.s3p_recovery_age_key_v1(p_case_type text, p_created_at timestamptz, p_payout_completed_at timestamptz)
RETURNS bigint LANGUAGE sql IMMUTABLE SET search_path = '' SET jit = off AS $f$
  SELECT floor(extract(epoch FROM CASE WHEN upper(COALESCE(p_case_type, '')) = 'PAYMENT_ADVANCE'
                                       THEN COALESCE(p_payout_completed_at, p_created_at) ELSE p_created_at END) * 1000000)::bigint
$f$;
CREATE OR REPLACE FUNCTION private.s3p_recovery_order_key_v1(p_finance_case_id uuid)
RETURNS bigint LANGUAGE sql STABLE SET search_path = '' SET jit = off AS $f$
  SELECT private.s3p_recovery_age_key_v1(a.case_type::text, a.created_at, COALESCE(t.completed_at_utc, b.completed_at_utc))
  FROM public.pay_advances AS a
  LEFT JOIN public.pay_bank_transfers AS t ON t.id = a.payout_transfer_id
  LEFT JOIN public.pay_batches AS b ON b.id = a.payout_pay_batch_id
  WHERE a.id = p_finance_case_id
$f$;

-- ---------------------------------------------------------------------------------------------------
-- 3a. Type-specific recovery allocator (user ruling 30), used by the V3 overlay
-- ---------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION private.pay_workbench_recovery_type_capped_allocate_v1(p_candidate_id uuid, p_pay_date date, p_rows jsonb)
 RETURNS TABLE(row_id uuid, recoverable_amount_ex_vat numeric, protected_recovery boolean, cap_reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
 SET jit TO 'off'
AS $function$
-- A34 (Worker BT): the V3 Workbench recovery allocation (pre-Draft live truth, Policy X). Rows come from the overlay;
-- order is oldest debt first (private.s3p_recovery_order_key_v1, ties finance case id, row ordinal, row id). State:
-- remaining pay headroom per pay channel (the Office-selected ordinary pay) and one remaining take-home figure per
-- Candidate (pay already arranged this pay week + that headroom): the two quantities the canonical builder hands to
-- public._pay_finance_protected_recovery_allocate. Per row:
--   loan (PAYMENT_ADVANCE_REPAYMENT / LOAN_REPAYMENT) or manual debt (MANUAL_DEBT_RECOVERY): cap = least(headroom,
--     headroom - minimum earnings threshold, take-home - floor); floor = the case's take_home_floor_override, else the
--     Candidate's min_take_home_wtd (the allocator's p_default_take_home_floor);
--   overpayment (OVERPAYMENT_RECOVERY): cap = pay headroom only (user ruling 30);
--   recovered = least(nominal due, cap). An included row consumes what it recovers from both figures; an excluded or
--   ineligible row consumes nothing (A30). An excluded eligible row still reports what it would recover.
DECLARE
  v_default_floor numeric(12,2) := 0;
  v_paid_wtd numeric(12,2) := 0;
  v_take_home numeric(12,2) := 0;
  v_headroom jsonb := '{}'::jsonb;
  v_row record;
  v_rem numeric(12,2);
  v_threshold_cap numeric(12,2);
  v_floor numeric(12,2);
  v_take_home_cap numeric(12,2);
  v_cap numeric(12,2);
  v_rec numeric(12,2);
  v_protected boolean;
BEGIN
  IF p_candidate_id IS NULL OR p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_ALLOCATION_INPUT_INVALID' USING ERRCODE = '22023';
  END IF;
  IF pg_catalog.jsonb_array_length(p_rows) = 0 THEN
    RETURN;
  END IF;

  SELECT pg_catalog.round(GREATEST(COALESCE(candidate_row.min_take_home_wtd, 0), 0), 2)
  INTO v_default_floor
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id;
  v_default_floor := COALESCE(v_default_floor, 0);

  IF p_pay_date IS NOT NULL THEN
    v_paid_wtd := pg_catalog.round(GREATEST(COALESCE(public._pay_candidate_arranged_pay_wtd_before(
      p_candidate_id, public._pay_week_start_monday(p_pay_date), p_pay_date, NULL::timestamptz, NULL::uuid), 0), 0), 2);
  END IF;

  SELECT COALESCE(pg_catalog.jsonb_object_agg(channel_row.pay_channel, channel_row.headroom), '{}'::jsonb),
         v_paid_wtd + COALESCE(pg_catalog.sum(channel_row.headroom), 0)
  INTO v_headroom, v_take_home
  FROM (
    SELECT COALESCE(x.pay_channel, '') AS pay_channel,
           pg_catalog.round(GREATEST(pg_catalog.max(COALESCE(x.headroom_ex_vat, 0)), 0), 2) AS headroom
    FROM pg_catalog.jsonb_to_recordset(p_rows) AS x(pay_channel text, headroom_ex_vat numeric)
    GROUP BY COALESCE(x.pay_channel, '')
  ) AS channel_row;

  FOR v_row IN
    SELECT x.id, COALESCE(x.pay_channel, '') AS pay_channel, x.line_type,
           pg_catalog.round(GREATEST(COALESCE(x.nominal_due_amount_ex_vat, 0), 0), 2) AS nominal,
           COALESCE(x.eligible, false) AS eligible, COALESCE(x.excluded, false) AS excluded,
           case_row.minimum_earnings_threshold, case_row.take_home_floor_override
    FROM pg_catalog.jsonb_to_recordset(p_rows) AS x(id uuid, pay_channel text, finance_case_id text, line_type text,
         row_ordinal bigint, nominal_due_amount_ex_vat numeric, headroom_ex_vat numeric, eligible boolean, excluded boolean)
    LEFT JOIN public.pay_advances AS case_row
      ON case_row.id = CASE WHEN x.finance_case_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                            THEN x.finance_case_id::uuid END
    ORDER BY private.s3p_recovery_order_key_v1(CASE WHEN x.finance_case_id
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN x.finance_case_id::uuid END) NULLS LAST,
             x.finance_case_id, x.row_ordinal, x.id
  LOOP
    row_id := v_row.id;
    v_protected := v_row.line_type IN ('PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT', 'MANUAL_DEBT_RECOVERY');
    protected_recovery := v_protected;
    IF NOT v_row.eligible THEN
      recoverable_amount_ex_vat := 0;
      cap_reason := NULL;
      RETURN NEXT;
      CONTINUE;
    END IF;
    v_rem := COALESCE((v_headroom->>v_row.pay_channel)::numeric, 0);
    IF v_protected THEN
      v_threshold_cap := CASE WHEN v_row.minimum_earnings_threshold IS NULL THEN v_rem
        ELSE pg_catalog.round(GREATEST(v_rem - pg_catalog.round(GREATEST(v_row.minimum_earnings_threshold, 0), 2), 0), 2) END;
      -- NB GREATEST ignores NULL, so a NULL override must be tested explicitly (else it would become a GBP0 floor).
      v_floor := CASE WHEN v_row.take_home_floor_override IS NULL THEN v_default_floor
        ELSE pg_catalog.round(GREATEST(v_row.take_home_floor_override, 0), 2) END;
      v_take_home_cap := pg_catalog.round(GREATEST(v_take_home - v_floor, 0), 2);
      v_cap := LEAST(v_rem, v_threshold_cap, v_take_home_cap);
    ELSE
      v_threshold_cap := v_rem;
      v_take_home_cap := v_rem;
      v_cap := v_rem;
    END IF;
    v_rec := pg_catalog.round(LEAST(v_row.nominal, GREATEST(v_cap, 0)), 2);
    recoverable_amount_ex_vat := v_rec;
    cap_reason := CASE
      WHEN v_rec >= v_row.nominal THEN NULL
      WHEN v_protected AND v_take_home_cap < v_rem AND v_take_home_cap <= v_threshold_cap THEN 'TAKE_HOME_FLOOR'
      WHEN v_protected AND v_threshold_cap < v_rem THEN 'EARNINGS_THRESHOLD'
      ELSE 'PAY_HEADROOM'
    END;
    IF NOT v_row.excluded THEN
      v_headroom := v_headroom || pg_catalog.jsonb_build_object(v_row.pay_channel, pg_catalog.round(GREATEST(v_rem - v_rec, 0), 2));
      v_take_home := pg_catalog.round(GREATEST(v_take_home - v_rec, 0), 2);
    END IF;
    RETURN NEXT;
  END LOOP;
  RETURN;
END;
$function$;

-- ---------------------------------------------------------------------------------------------------
-- 1a/2b/3b. V3 selection overlay: legacy blocker + oldest-first, type-capped allocation
-- ---------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION private.pay_workbench_recovery_selection_overlay_apply_v1(p_session_id uuid, p_candidate_id uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_force_v3 boolean := false;
  v_reason text := 'SELECTION_CHANGED';
  v_unknown_option_count integer := 0;
  v_is_v3 boolean := false;
  v_recovery_row_count integer := 0;
  v_ready_recovery_count integer := 0;
  v_case_recovery_count integer := 0;
  v_blocked_recovery_count integer := 0;
  v_forced_deselected_count integer := 0;
  v_updated_count integer := 0;
  v_selected_positive_amount numeric := 0;
  v_ready_recovery_amount numeric := 0;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_row_count integer := 0;
  v_overlay_digest text := NULL::text;
  v_duplicate_recovery_identity_count integer := 0;
  v_session_ready boolean := false;
  v_draft_blocker_codes jsonb := '[]'::jsonb;
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_SCOPE_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF p_options_json IS NULL OR pg_catalog.jsonb_typeof(p_options_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_OPTIONS_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_unknown_option_count
  FROM pg_catalog.jsonb_object_keys(p_options_json) AS supplied_option(option_key)
  WHERE supplied_option.option_key NOT IN ('force_v3', 'reason', 'pay_channel_scope');

  IF v_unknown_option_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_OPTIONS_UNKNOWN'
      USING ERRCODE = '22023';
  END IF;

  -- BEGIN BANKING_PAY_MODAL_WRITE_CHANNEL_VALIDATION_V2
  IF COALESCE(p_options_json->>'pay_channel_scope','ALL') NOT IN ('ALL','PAYE','UMBRELLA') THEN
    RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';
  END IF;
  -- END BANKING_PAY_MODAL_WRITE_CHANNEL_VALIDATION_V2
  v_force_v3 := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_options_json->>'force_v3', 'false')))
    IN ('true', 't', '1', 'yes', 'y', 'on');
  v_reason := pg_catalog.upper(pg_catalog.btrim(COALESCE(NULLIF(p_options_json->>'reason', ''), 'SELECTION_CHANGED')));

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_session.status, ''))) <> 'OPEN'
     OR v_session.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT scope_row.*
  INTO v_scope
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001';
  END IF;

  v_is_v3 := v_force_v3 OR (
    v_scope.certified_preview_publication_attestation_json->>'attestation_version'
      = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
    AND v_scope.certified_preview_publication_attestation_json->>'contract_version' = '3'
    AND v_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
      = 'READY_TO_PAY_SEMANTIC_V2'
  );

  IF v_is_v3 IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_V3_SEMANTIC_SOURCE',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'updated_count', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_recovery_selection_overlay;
  CREATE TEMPORARY TABLE pg_temp._bpay_recovery_selection_overlay ON COMMIT DROP AS
  WITH selected_positive_by_channel AS (
    SELECT
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        positive_row.row_json->>'pay_channel',
        positive_row.row_json->>'candidate_pay_method',
        positive_row.row_json->>'current_pay_method',
        ''
      ))) AS pay_channel,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        CASE
          WHEN COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN GREATEST((positive_row.row_json->>'amount_ex_vat')::numeric, 0)
          ELSE 0::numeric
        END
      ), 0), 2) AS selected_positive_headroom_ex_vat
    FROM public.banking_pay_workbench_preview_rows AS positive_row
    WHERE positive_row.session_id = p_session_id
      AND positive_row.session_version = v_session.version
      AND positive_row.candidate_id = p_candidate_id
      AND positive_row.status = 'READY'
      AND positive_row.selected IS TRUE
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.selection_state, ''))) = 'SELECTED'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.row_json->>'line_type', ''))) = 'TIMESHEET_PAYMENT'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.row_json->>'presentation_role', ''))) = 'ALLOCATION_COMPONENT'
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'draftable', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'is_ready_for_draft', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'selection_allowed', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND (positive_row.row_json->>'amount_ex_vat')::numeric > 0
    GROUP BY pg_catalog.upper(pg_catalog.btrim(COALESCE(
      positive_row.row_json->>'pay_channel',
      positive_row.row_json->>'candidate_pay_method',
      positive_row.row_json->>'current_pay_method',
      ''
    )))
  ), recovery_base_raw AS (
    SELECT
      recovery_row.id,
      recovery_row.row_ordinal,
      recovery_row.section AS physical_section,
      recovery_row.row_key,
      recovery_row.selected AS current_selected,
      recovery_row.selection_state AS current_selection_state,
      COALESCE(recovery_row.row_json, '{}'::jsonb) AS base_row_json,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'selection_user_override',
        ''
      ))) = 'UNSELECTED' AS explicitly_user_unselected,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'pay_channel',
        recovery_row.row_json->>'candidate_pay_method',
        recovery_row.row_json->>'current_pay_method',
        ''
      ))) AS pay_channel,
      pg_catalog.round(COALESCE(
        CASE
          WHEN COALESCE(recovery_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(recovery_row.row_json->>'source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'source_due_amount_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(recovery_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'amount_ex_vat')::numeric)
          ELSE 0::numeric
        END
      ), 2) AS nominal_due_amount_ex_vat,
      CASE
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_components') = 'array'
          THEN recovery_row.row_json->'case_components'
        ELSE '[]'::jsonb
      END AS canonical_case_components,
      CASE
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_resolution_summary') = 'object'
          THEN recovery_row.row_json->'case_resolution_summary'
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_resolution_summary_json') = 'object'
          THEN recovery_row.row_json->'case_resolution_summary_json'
        ELSE '{}'::jsonb
      END AS case_resolution_summary_json,
      (
        pg_catalog.lower(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,case_needs_resolution}',
          recovery_row.row_json#>>'{case_resolution_summary_json,case_needs_resolution}',
          recovery_row.row_json->>'case_needs_resolution_now',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,taxable_channel_restructure,can_apply}',
          recovery_row.row_json#>>'{case_resolution_summary_json,taxable_channel_restructure,can_apply}',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,resolution_family}',
          recovery_row.row_json#>>'{case_resolution_summary_json,resolution_family}',
          recovery_row.row_json->>'resolution_family',
          ''
        ))) = 'TAXABLE_CHANNEL_RESTRUCTURE'
      ) AS actionable_restructure,
      COALESCE(
        recovery_row.row_json#>'{selection_recovery_headroom_v1,base_blocked_reason_codes}',
        (
          SELECT COALESCE(pg_catalog.jsonb_agg(reason.value ORDER BY reason.ordinality), '[]'::jsonb)
          FROM pg_catalog.jsonb_array_elements_text(
            CASE
              WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'blocked_reason_codes') = 'array'
                THEN recovery_row.row_json->'blocked_reason_codes'
              ELSE '[]'::jsonb
            END
          ) WITH ORDINALITY AS reason(value, ordinality)
          WHERE pg_catalog.upper(pg_catalog.btrim(reason.value)) <> 'NO_PAY_HEADROOM'
        ),
        '[]'::jsonb
      ) AS base_blocked_reason_codes,
      COALESCE(
        NULLIF(recovery_row.row_json#>>'{selection_recovery_headroom_v1,base_presentation_reason}', ''),
        CASE
          WHEN pg_catalog.upper(COALESCE(recovery_row.row_json->>'presentation_reason', '')) = 'NO_PAY_HEADROOM'
            THEN 'READY_TO_PAY'
          ELSE NULLIF(recovery_row.row_json->>'presentation_reason', '')
        END,
        'READY_TO_PAY'
      ) AS base_presentation_reason,
      (
        recovery_row.row_json->>'finance_case_id'
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'line_type', ''))) IN (
          'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY',
          'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT'
        )
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'post_draft_overlay_applied', 'false')))
          NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'case_needs_resolution_now', 'false')))
          NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(recovery_row.row_json#>>'{snooze_state,state}', 'NONE'))) = 'NONE'
        AND NOT EXISTS (
          SELECT 1
          FROM pg_catalog.jsonb_array_elements_text(
            COALESCE(
              recovery_row.row_json#>'{selection_recovery_headroom_v1,base_blocked_reason_codes}',
              CASE
                WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'blocked_reason_codes') = 'array'
                  THEN recovery_row.row_json->'blocked_reason_codes'
                ELSE '[]'::jsonb
              END
            )
          ) AS blocker(value)
          -- A34: the legacy component blocker is re-derived below on every run, never read back as sticky.
          WHERE pg_catalog.upper(pg_catalog.btrim(blocker.value)) NOT IN ('NO_PAY_HEADROOM', 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING')
        )
      ) AS static_recovery_eligible
    FROM public.banking_pay_workbench_preview_rows AS recovery_row
    WHERE recovery_row.session_id = p_session_id
      AND recovery_row.session_version = v_session.version
      AND recovery_row.candidate_id = p_candidate_id
      AND recovery_row.status = 'READY'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'line_type',
        recovery_row.row_json->>'case_type',
        ''
      ))) IN (
        'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY',
        'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT'
      )
  ), recovery_base AS (
    -- A34 (legacy finance case blocker, Worker BT): a repayment with money due whose finance case has NO open component
    -- records (the published row carries case_components = []) cannot be deducted under the certified V3 contract
    -- (every recovered penny must name its component; Policy X forbids inventing one). Before A34 this raised
    -- PAY_WORKBENCH_RECOVERY_COMPONENT_AUTHORITY_MISSING and the WHOLE Candidate failed to prepare. Now that row alone
    -- is a visible Blocked row with reason LEGACY_FINANCE_CASE_COMPONENTS_MISSING: it recovers GBP0 and consumes no pay headroom
    -- (as a snoozed or otherwise ineligible repayment does), so the Office sees it and every other row is unchanged.
    -- Derived afresh on every run from the row's own components: it clears itself once component records exist.
    SELECT
      raw.id,
      raw.row_ordinal,
      raw.physical_section,
      raw.row_key,
      raw.current_selected,
      raw.current_selection_state,
      raw.base_row_json,
      raw.explicitly_user_unselected,
      raw.pay_channel,
      raw.nominal_due_amount_ex_vat,
      raw.canonical_case_components,
      raw.case_resolution_summary_json,
      raw.actionable_restructure AND legacy.components_missing IS NOT TRUE AS actionable_restructure,
      COALESCE((
        SELECT pg_catalog.jsonb_agg(code.value ORDER BY code.ordinality)
        FROM pg_catalog.jsonb_array_elements(
          CASE WHEN pg_catalog.jsonb_typeof(raw.base_blocked_reason_codes) = 'array'
            THEN raw.base_blocked_reason_codes ELSE '[]'::jsonb END
        ) WITH ORDINALITY AS code(value, ordinality)
        WHERE pg_catalog.upper(pg_catalog.btrim(COALESCE(code.value #>> '{}', ''))) <> 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING'
      ), '[]'::jsonb)
        || CASE WHEN legacy.components_missing
             THEN pg_catalog.jsonb_build_array('LEGACY_FINANCE_CASE_COMPONENTS_MISSING') ELSE '[]'::jsonb END
        AS base_blocked_reason_codes,
      CASE
        WHEN legacy.components_missing THEN 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING'
        WHEN pg_catalog.upper(pg_catalog.btrim(COALESCE(raw.base_presentation_reason, ''))) = 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING'
          THEN 'READY_TO_PAY'
        ELSE raw.base_presentation_reason
      END AS base_presentation_reason,
      raw.static_recovery_eligible AND legacy.components_missing IS NOT TRUE AS static_recovery_eligible,
      legacy.components_missing AS legacy_components_missing
    FROM recovery_base_raw AS raw
    CROSS JOIN LATERAL (
      SELECT raw.nominal_due_amount_ex_vat > 0
         AND pg_catalog.jsonb_array_length(raw.canonical_case_components) = 0 AS components_missing
    ) AS legacy
  ), ranked_recovery AS (
    SELECT
      recovery_base.*,
      COALESCE(selected_headroom.selected_positive_headroom_ex_vat, 0)::numeric AS selected_positive_headroom_ex_vat
    FROM recovery_base
    LEFT JOIN selected_positive_by_channel AS selected_headroom
      ON selected_headroom.pay_channel = recovery_base.pay_channel
  ), recovery_allocation AS (
    -- A34 (user rulings 25/31 order, 29 exclusion and headroom, 30 type-specific protection; Worker BT): ONE sequential
    -- allocation, oldest debt first (the SAME key and tie-break as the canonical builder and Stage 3 WP3: creation date
    -- and time, a loan by its payout; ties finance case id, then row). Each repayment is capped by its OWN type's rule:
    -- a loan (PAYMENT_ADVANCE) or manual debt keeps the minimum take-home floor and its minimum earnings threshold,
    -- exactly as public._pay_finance_protected_recovery_allocate does; an overpayment is capped by pay headroom only.
    -- A repayment the Office excluded, or one that cannot be recovered now, consumes nothing (A30). Replaces the
    -- running-nominal window, which applied no floor at all.
    SELECT allocation.*
    FROM private.pay_workbench_recovery_type_capped_allocate_v1(
      p_candidate_id,
      v_session.pay_date,
      (
        SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'id', rr.id::text,
          'pay_channel', rr.pay_channel,
          'finance_case_id', rr.base_row_json->>'finance_case_id',
          'line_type', pg_catalog.upper(pg_catalog.btrim(COALESCE(rr.base_row_json->>'line_type', rr.base_row_json->>'case_type', ''))),
          'row_ordinal', rr.row_ordinal,
          'nominal_due_amount_ex_vat', rr.nominal_due_amount_ex_vat,
          'headroom_ex_vat', rr.selected_positive_headroom_ex_vat,
          'eligible', rr.static_recovery_eligible AND rr.actionable_restructure IS NOT TRUE
                      AND rr.pay_channel IN ('PAYE', 'UMBRELLA'),
          'excluded', rr.explicitly_user_unselected IS TRUE
        )), '[]'::jsonb)
        FROM ranked_recovery AS rr
      )
    ) AS allocation
  ), allocated_recovery AS (
    SELECT
      ranked_recovery.*,
      COALESCE(recovery_allocation.recoverable_amount_ex_vat, 0::numeric) AS recoverable_amount_ex_vat,
      recovery_allocation.cap_reason AS recovery_cap_reason
    FROM ranked_recovery
    LEFT JOIN recovery_allocation
      ON recovery_allocation.row_id = ranked_recovery.id
  ), recovery_component_base AS (
    SELECT
      allocated_recovery.id AS recovery_row_id,
      component.ordinality::integer AS component_ordinality,
      component.value AS component_json,
      CASE
        WHEN COALESCE(component.value->>'finance_component_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN true
        ELSE NULLIF(pg_catalog.btrim(COALESCE(component.value->>'source_family_key', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(
                component.value->>'component_key_type',
                component.value#>>'{component_key,key_type}',
                ''
              )), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(
                component.value->>'component_key_value',
                component.value#>>'{component_key,key_value}',
                ''
              )), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'bucket_code', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'source_basis_fingerprint', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'component_fingerprint', '')), '') IS NOT NULL
      END AS identity_complete,
      CASE
        WHEN COALESCE(component.value->>'finance_component_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN 'FINANCE:' || pg_catalog.lower(component.value->>'finance_component_id')
        ELSE 'STRUCT:' || pg_catalog.concat_ws(E'\x1f',
          pg_catalog.upper(pg_catalog.btrim(COALESCE(component.value->>'source_family_key', ''))),
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            component.value->>'component_key_type', component.value#>>'{component_key,key_type}', ''
          ))),
          pg_catalog.btrim(COALESCE(
            component.value->>'component_key_value', component.value#>>'{component_key,key_value}', ''
          )),
          pg_catalog.upper(pg_catalog.btrim(COALESCE(component.value->>'bucket_code', ''))),
          pg_catalog.btrim(COALESCE(component.value->>'source_basis_fingerprint', '')),
          pg_catalog.btrim(COALESCE(component.value->>'component_fingerprint', ''))
        )
      END AS component_identity,
      pg_catalog.round(COALESCE(
        CASE
          WHEN COALESCE(component.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'target_pay_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'authoritative_outstanding_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'authoritative_outstanding_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'source_pay_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'component_amount_ex_vat')::numeric)
          ELSE 0::numeric
        END
      ), 2) AS component_capacity_ex_vat,
      allocated_recovery.recoverable_amount_ex_vat
    FROM allocated_recovery
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
      allocated_recovery.canonical_case_components
    ) WITH ORDINALITY AS component(value, ordinality)
  ), recovery_component_ranked AS (
    SELECT
      recovery_component_base.*,
      pg_catalog.count(*) OVER (
        PARTITION BY recovery_component_base.recovery_row_id,
          recovery_component_base.component_identity
      )::integer AS component_identity_count,
      COALESCE(pg_catalog.sum(recovery_component_base.component_capacity_ex_vat) OVER (
        PARTITION BY recovery_component_base.recovery_row_id
        ORDER BY
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            recovery_component_base.component_json->>'component_key_type',
            recovery_component_base.component_json#>>'{component_key,key_type}',
            ''
          ))),
          pg_catalog.btrim(COALESCE(
            recovery_component_base.component_json->>'component_key_value',
            recovery_component_base.component_json#>>'{component_key,key_value}',
            ''
          )),
          pg_catalog.lower(COALESCE(recovery_component_base.component_json->>'finance_component_id', '')),
          COALESCE(recovery_component_base.component_json->>'component_fingerprint', ''),
          recovery_component_base.component_ordinality
        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
      ), 0)::numeric AS prior_component_capacity_ex_vat
    FROM recovery_component_base
  ), recovery_component_allocated AS (
    SELECT
      recovery_component_ranked.*,
      pg_catalog.round(LEAST(
        recovery_component_ranked.component_capacity_ex_vat,
        GREATEST(
          recovery_component_ranked.recoverable_amount_ex_vat
            - recovery_component_ranked.prior_component_capacity_ex_vat,
          0
        )
      ), 2) AS base_component_recoverable_ex_vat,
      pg_catalog.row_number() OVER (
        PARTITION BY recovery_component_ranked.recovery_row_id
        ORDER BY
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            recovery_component_ranked.component_json->>'component_key_type',
            recovery_component_ranked.component_json#>>'{component_key,key_type}',
            ''
          ))),
          pg_catalog.btrim(COALESCE(
            recovery_component_ranked.component_json->>'component_key_value',
            recovery_component_ranked.component_json#>>'{component_key,key_value}',
            ''
          )),
          pg_catalog.lower(COALESCE(recovery_component_ranked.component_json->>'finance_component_id', '')),
          COALESCE(recovery_component_ranked.component_json->>'component_fingerprint', ''),
          recovery_component_ranked.component_ordinality
      )::integer AS allocation_order
    FROM recovery_component_ranked
  ), recovery_component_residual AS (
    SELECT
      recovery_component_allocated.*,
      pg_catalog.round(
        recovery_component_allocated.recoverable_amount_ex_vat
          - pg_catalog.sum(recovery_component_allocated.base_component_recoverable_ex_vat)
              OVER (PARTITION BY recovery_component_allocated.recovery_row_id),
        2
      ) AS penny_residual_ex_vat,
      pg_catalog.max(recovery_component_allocated.allocation_order) FILTER (
        WHERE recovery_component_allocated.component_capacity_ex_vat
              - recovery_component_allocated.base_component_recoverable_ex_vat > 0
      ) OVER (PARTITION BY recovery_component_allocated.recovery_row_id)
        AS residual_target_order
    FROM recovery_component_allocated
  ), recovery_component_final AS (
    SELECT
      recovery_component_residual.*,
      pg_catalog.round(
        recovery_component_residual.base_component_recoverable_ex_vat
          + CASE
              WHEN recovery_component_residual.penny_residual_ex_vat <> 0
               AND recovery_component_residual.allocation_order
                    = recovery_component_residual.residual_target_order
               AND recovery_component_residual.component_capacity_ex_vat
                     - recovery_component_residual.base_component_recoverable_ex_vat
                    >= recovery_component_residual.penny_residual_ex_vat
                THEN recovery_component_residual.penny_residual_ex_vat
              ELSE 0::numeric
            END,
        2
      ) AS component_recoverable_ex_vat
    FROM recovery_component_residual
  ), recovery_component_rollup AS (
    SELECT
      recovery_component_final.recovery_row_id,
      pg_catalog.jsonb_agg(
        recovery_component_final.component_json
        || pg_catalog.jsonb_build_object(
          'preview_due_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'allocated_source_due_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'ready_preview_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'preview_component_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'component_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'recoverable_this_pay_run_ex_vat', recovery_component_final.component_recoverable_ex_vat
        )
        ORDER BY recovery_component_final.component_ordinality
      ) AS allocated_case_components,
      pg_catalog.count(*) FILTER (
        WHERE recovery_component_final.identity_complete IS NOT TRUE
      )::integer AS incomplete_identity_count,
      pg_catalog.count(*) FILTER (
        WHERE recovery_component_final.component_identity_count > 1
      )::integer AS duplicate_identity_count,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        recovery_component_final.component_capacity_ex_vat
      ), 0), 2) AS component_capacity_ex_vat,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        recovery_component_final.component_recoverable_ex_vat
      ), 0), 2) AS component_recoverable_ex_vat
    FROM recovery_component_final
    GROUP BY recovery_component_final.recovery_row_id
  )
  SELECT
    allocated_recovery.*,
    COALESCE(recovery_component_rollup.allocated_case_components, '[]'::jsonb)
      AS allocated_case_components,
    COALESCE(recovery_component_rollup.incomplete_identity_count, 0)::integer
      AS incomplete_component_identity_count,
    COALESCE(recovery_component_rollup.duplicate_identity_count, 0)::integer
      AS duplicate_component_identity_count,
    COALESCE(recovery_component_rollup.component_capacity_ex_vat, 0)::numeric
      AS component_capacity_ex_vat,
    COALESCE(recovery_component_rollup.component_recoverable_ex_vat, 0)::numeric
      AS component_recoverable_ex_vat,
    CASE
      WHEN allocated_recovery.actionable_restructure
        THEN 'cases_resolutions'
      WHEN allocated_recovery.static_recovery_eligible
       AND allocated_recovery.recoverable_amount_ex_vat > 0
        THEN 'canonical_preview_lines'
      ELSE 'blocked_for_pay'
    END AS effective_section,
    pg_catalog.md5(pg_catalog.jsonb_build_object(
      'contract_version', 1,
      'candidate_id', p_candidate_id::text,
      'pay_channel', allocated_recovery.pay_channel,
      'row_key', allocated_recovery.row_key,
      'selected_positive_headroom_ex_vat', allocated_recovery.selected_positive_headroom_ex_vat,
      'nominal_due_amount_ex_vat', allocated_recovery.nominal_due_amount_ex_vat,
      'recoverable_amount_ex_vat', allocated_recovery.recoverable_amount_ex_vat,
      'effective_section', CASE
        WHEN allocated_recovery.actionable_restructure
          THEN 'cases_resolutions'
        WHEN allocated_recovery.static_recovery_eligible
         AND allocated_recovery.recoverable_amount_ex_vat > 0
          THEN 'canonical_preview_lines'
        ELSE 'blocked_for_pay'
      END
    )::text) AS row_overlay_digest
  FROM allocated_recovery
  LEFT JOIN recovery_component_rollup
    ON recovery_component_rollup.recovery_row_id = allocated_recovery.id;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.incomplete_component_identity_count > 0
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_IDENTITY_INCOMPLETE'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.duplicate_component_identity_count > 0
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_IDENTITY_DUPLICATE'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.nominal_due_amount_ex_vat > 0
      AND pg_catalog.jsonb_array_length(overlay_row.allocated_case_components) = 0
      -- A34: a legacy row without component records is a Blocked row (above), recovering GBP0, not a failure.
      AND overlay_row.legacy_components_missing IS NOT TRUE
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_AUTHORITY_MISSING'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.recoverable_amount_ex_vat > overlay_row.component_capacity_ex_vat
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_CAPACITY_INSUFFICIENT'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.component_recoverable_ex_vat
      IS DISTINCT FROM overlay_row.recoverable_amount_ex_vat
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_PENNY_RECONCILIATION_FAILED'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_duplicate_recovery_identity_count
  FROM (
    SELECT
      COALESCE(NULLIF(overlay_row.base_row_json->>'finance_case_id', ''), overlay_row.row_key) AS recovery_identity,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(overlay_row.base_row_json->>'line_type', ''))) AS recovery_family
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    GROUP BY
      COALESCE(NULLIF(overlay_row.base_row_json->>'finance_case_id', ''), overlay_row.row_key),
      pg_catalog.upper(pg_catalog.btrim(COALESCE(overlay_row.base_row_json->>'line_type', '')))
    HAVING pg_catalog.count(*) > 1
  ) AS duplicate_identity;

  IF v_duplicate_recovery_identity_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_DUPLICATE_IDENTITY'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'canonical_preview_lines')::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'cases_resolutions')::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'blocked_for_pay')::integer,
         (
           SELECT pg_catalog.round(COALESCE(pg_catalog.sum(channel_headroom.selected_positive_headroom_ex_vat), 0), 2)
           FROM (
             SELECT overlay_channel.pay_channel,
                    pg_catalog.max(overlay_channel.selected_positive_headroom_ex_vat) AS selected_positive_headroom_ex_vat
             FROM pg_temp._bpay_recovery_selection_overlay AS overlay_channel
             GROUP BY overlay_channel.pay_channel
           ) AS channel_headroom
         ),
         pg_catalog.round(COALESCE(pg_catalog.sum(overlay_row.recoverable_amount_ex_vat), 0), 2),
         pg_catalog.md5(COALESCE(pg_catalog.string_agg(
           overlay_row.row_key || E'\x1f' || overlay_row.row_overlay_digest,
           E'\x1e' ORDER BY overlay_row.row_ordinal, overlay_row.id
         ), ''))
  INTO v_recovery_row_count,
       v_ready_recovery_count,
       v_case_recovery_count,
       v_blocked_recovery_count,
       v_selected_positive_amount,
       v_ready_recovery_amount,
       v_overlay_digest
  FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row;

  WITH updated_rows AS (
    UPDATE public.banking_pay_workbench_preview_rows AS recovery_row
    SET selected = CASE
          WHEN overlay_row.effective_section = 'canonical_preview_lines'
            THEN overlay_row.explicitly_user_unselected IS NOT TRUE
          ELSE false
        END,
        selection_state = CASE
          WHEN overlay_row.effective_section = 'canonical_preview_lines'
            THEN CASE
              WHEN overlay_row.explicitly_user_unselected IS TRUE THEN 'UNSELECTED'
              ELSE 'SELECTED'
            END
          ELSE 'NOT_SELECTABLE'
        END,
        row_json = pg_catalog.jsonb_strip_nulls(
          overlay_row.base_row_json
          || pg_catalog.jsonb_build_object(
            'case_components', overlay_row.allocated_case_components,
            'amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'preview_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'amount_display', -overlay_row.recoverable_amount_ex_vat,
            'section_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'section_amount_display', -overlay_row.recoverable_amount_ex_vat,
            'target_pay_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'ready_preview_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'preview_component_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'nominal_due_amount_ex_vat', overlay_row.nominal_due_amount_ex_vat,
            'recoverable_this_pay_run_ex_vat', overlay_row.recoverable_amount_ex_vat,
            'semantic_ordinary_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
            'retained_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
            'semantic_recovery_headroom_capped',
              overlay_row.recoverable_amount_ex_vat < overlay_row.nominal_due_amount_ex_vat,
            'effective_section', overlay_row.effective_section,
            'physical_section', overlay_row.physical_section,
            'readiness_state', CASE overlay_row.effective_section
              WHEN 'canonical_preview_lines' THEN 'READY_TO_PAY'
              WHEN 'cases_resolutions' THEN 'RESOLUTION_REQUIRED'
              ELSE 'BLOCKED_FOR_PAY'
            END,
            'presentation_section', CASE overlay_row.effective_section
              WHEN 'canonical_preview_lines' THEN 'READY_TO_PAY'
              WHEN 'cases_resolutions' THEN 'CASES_RESOLUTIONS'
              ELSE 'BLOCKED_FOR_PAY'
            END,
            'presentation_reason', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.base_presentation_reason
              WHEN overlay_row.effective_section = 'cases_resolutions'
                THEN 'CASE_NEEDS_RESOLUTION'
              WHEN overlay_row.static_recovery_eligible THEN 'NO_PAY_HEADROOM'
              ELSE overlay_row.base_presentation_reason
            END,
            'draftable', overlay_row.effective_section = 'canonical_preview_lines',
            'is_ready_for_draft', overlay_row.effective_section = 'canonical_preview_lines',
            'selection_allowed', overlay_row.effective_section = 'canonical_preview_lines',
            'is_excluded_from_allocation', overlay_row.effective_section <> 'canonical_preview_lines',
            'selected', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.explicitly_user_unselected IS NOT TRUE
              ELSE false
            END,
            'selection_state', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
               AND overlay_row.explicitly_user_unselected IS NOT TRUE
                THEN 'SELECTED'
              WHEN overlay_row.effective_section = 'canonical_preview_lines' THEN 'UNSELECTED'
              ELSE 'NOT_SELECTABLE'
            END,
            'selection_origin', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
               AND overlay_row.explicitly_user_unselected IS TRUE
                THEN 'USER_EXPLICIT_DESELECT'
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN 'SERVER_DEFAULT_NEWLY_ELIGIBLE'
              ELSE COALESCE(overlay_row.base_row_json->>'selection_origin', 'SERVER_HEADROOM_BLOCKED')
            END,
            'blocked_reason_codes', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.base_blocked_reason_codes
              WHEN overlay_row.static_recovery_eligible
                THEN overlay_row.base_blocked_reason_codes || pg_catalog.jsonb_build_array('NO_PAY_HEADROOM')
              ELSE overlay_row.base_blocked_reason_codes
            END,
            'case_is_blocked', overlay_row.effective_section <> 'canonical_preview_lines',
            'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
              'contract_version', 1,
              'component_allocation_contract_version', 1,
              'candidate_id', p_candidate_id::text,
              'pay_channel', overlay_row.pay_channel,
              'physical_section', overlay_row.physical_section,
              'prior_physical_section', overlay_row.physical_section,
              'effective_section', overlay_row.effective_section,
              'selected_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
              'nominal_due_amount_ex_vat', overlay_row.nominal_due_amount_ex_vat,
              'recoverable_amount_ex_vat', overlay_row.recoverable_amount_ex_vat,
              'base_blocked_reason_codes', overlay_row.base_blocked_reason_codes,
              'base_presentation_reason', overlay_row.base_presentation_reason,
              'static_recovery_eligible', overlay_row.static_recovery_eligible,
              'actionable_restructure', overlay_row.actionable_restructure,
              -- A34: present (true) only on a legacy row; jsonb_strip_nulls removes it everywhere else.
              'legacy_components_missing', CASE WHEN overlay_row.legacy_components_missing THEN true END,
              -- A34: which rule capped this repayment (TAKE_HOME_FLOOR / EARNINGS_THRESHOLD / PAY_HEADROOM); absent if none.
              'recovery_cap_reason', overlay_row.recovery_cap_reason,
              'component_capacity_ex_vat', overlay_row.component_capacity_ex_vat,
              'component_recoverable_ex_vat', overlay_row.component_recoverable_ex_vat,
              'overlay_digest', overlay_row.row_overlay_digest,
              'reason', v_reason,
              'updated_at_utc', v_now::text,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            ),
            'case_resolution_summary', CASE
              WHEN pg_catalog.jsonb_typeof(overlay_row.case_resolution_summary_json) = 'object'
                THEN overlay_row.case_resolution_summary_json
                  || pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
              ELSE pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
            END,
            'case_resolution_summary_json', CASE
              WHEN pg_catalog.jsonb_typeof(overlay_row.case_resolution_summary_json) = 'object'
                THEN overlay_row.case_resolution_summary_json
                  || pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
              ELSE pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
            END
          )
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'row_json') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'row_json', (overlay_row.base_row_json->'row_json')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'case') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'case', (overlay_row.base_row_json->'case')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'raw_case') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'raw_case', (overlay_row.base_row_json->'raw_case')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
        ),
        updated_at_utc = v_now
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE recovery_row.id = overlay_row.id
      -- BEGIN BANKING_PAY_MODAL_WRITE_CHANNEL_FILTER_V2
      AND (COALESCE(p_options_json->>'pay_channel_scope','ALL')='ALL'
        OR overlay_row.pay_channel=p_options_json->>'pay_channel_scope')
      -- END BANKING_PAY_MODAL_WRITE_CHANNEL_FILTER_V2
    RETURNING recovery_row.id,
              overlay_row.effective_section,
              overlay_row.current_selected,
              recovery_row.selected
  )
  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(*) FILTER (
           WHERE updated_rows.current_selected IS TRUE
             AND updated_rows.selected IS FALSE
         )::integer
  INTO v_updated_count, v_forced_deselected_count
  FROM updated_rows;

  SELECT COALESCE(
           pg_catalog.jsonb_agg(selected_row.id::text ORDER BY selected_row.row_ordinal, selected_row.id),
           '[]'::jsonb
         ),
         pg_catalog.count(*)::integer
  INTO v_selected_preview_row_ids,
       v_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS selected_row
  WHERE selected_row.session_id = p_session_id
    AND selected_row.session_version = v_session.version
    AND selected_row.status = 'READY'
    AND selected_row.selected IS TRUE
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

  v_session_ready := pg_catalog.lower(pg_catalog.btrim(COALESCE(
    v_session.progress_json->>'ready',
    v_session.progress_json->>'session_ready',
    v_session.progress_json->>'ready_flag',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  SELECT COALESCE(
           pg_catalog.jsonb_agg(pg_catalog.to_jsonb(blocker.value) ORDER BY blocker.ordinality),
           '[]'::jsonb
         )
  INTO v_draft_blocker_codes
  FROM pg_catalog.jsonb_array_elements_text(
    CASE
      WHEN pg_catalog.jsonb_typeof(v_session.progress_json->'draft_blocker_codes') = 'array'
        THEN v_session.progress_json->'draft_blocker_codes'
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS blocker(value, ordinality)
  WHERE pg_catalog.upper(pg_catalog.btrim(blocker.value)) <> 'NO_SELECTED_ROWS';

  IF v_session_ready AND COALESCE(v_selected_row_count, 0) = 0 THEN
    v_draft_blocker_codes := COALESCE(v_draft_blocker_codes, '[]'::jsonb)
      || pg_catalog.jsonb_build_array('NO_SELECTED_ROWS');
  END IF;

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET selected_row_count = COALESCE(v_selected_row_count, 0),
      server_selected_preview_row_ids = CASE
        WHEN COALESCE(session_update.server_selected_preview_row_ids_provided, false)
          THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
        ELSE session_update.server_selected_preview_row_ids
      END,
      progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
            'contract_version', 1,
            'candidate_id', p_candidate_id::text,
            'selected_positive_headroom_ex_vat', v_selected_positive_amount,
            'ready_recovery_count', v_ready_recovery_count,
            'case_recovery_count', v_case_recovery_count,
            'blocked_recovery_count', v_blocked_recovery_count,
            'recoverable_amount_ex_vat', v_ready_recovery_amount,
            'overlay_digest', v_overlay_digest,
            'reason', v_reason,
            'updated_at_utc', v_now::text
          ),
          'selected_row_count', COALESCE(v_selected_row_count, 0),
          'selected_eligible_ready_row_count', COALESCE(v_selected_row_count, 0),
          'selected_rows_available', COALESCE(v_selected_row_count, 0) > 0,
          'ready_for_draft', v_session_ready AND COALESCE(v_selected_row_count, 0) > 0,
          'can_create_draft', v_session_ready AND COALESCE(v_selected_row_count, 0) > 0,
          'draft_blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb),
          'blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb)
        ),
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET certified_preview_publication_attestation_json = CASE
        WHEN v_scope.certified_preview_publication_attestation_json->>'attestation_version'
             = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
          THEN COALESCE(scope_update.certified_preview_publication_attestation_json, '{}'::jsonb)
            || pg_catalog.jsonb_build_object(
              'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
                'contract_version', 1,
                'selected_positive_headroom_ex_vat', v_selected_positive_amount,
                'ready_recovery_count', v_ready_recovery_count,
                'case_recovery_count', v_case_recovery_count,
                'blocked_recovery_count', v_blocked_recovery_count,
                'recoverable_amount_ex_vat', v_ready_recovery_amount,
                'overlay_digest', v_overlay_digest,
                'reason', v_reason,
                'updated_at_utc', v_now::text
              )
            )
        ELSE scope_update.certified_preview_publication_attestation_json
      END,
      updated_at_utc = v_now
  WHERE scope_update.id = v_scope.id;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SELECTION_DEPENDENT_RECOVERY_HEADROOM_APPLIED',
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'recovery_row_count', v_recovery_row_count,
    'ready_recovery_count', v_ready_recovery_count,
    'case_recovery_count', v_case_recovery_count,
    'blocked_recovery_count', v_blocked_recovery_count,
    'forced_deselected_count', v_forced_deselected_count,
    'updated_count', v_updated_count,
    'selected_positive_headroom_ex_vat', v_selected_positive_amount,
    'recoverable_amount_ex_vat', v_ready_recovery_amount,
    'overlay_digest', v_overlay_digest,
    'physical_sections_changed', false,
    'source_rows_changed', false,
    'post_draft_artifacts_touched', false,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

-- ---------------------------------------------------------------------------------------------------
-- 2c. Canonical builder: WP3 order (verbatim)
-- ---------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_finance_case_baseline(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- A28 reconciliation slicing (final slice only; bound to the current Workbench build token)
  v_a28_slice jsonb := CASE WHEN COALESCE(current_setting('cloudtms.pay_workbench_reconcile_slice_v1', true), '') ~ '^\s*\{'
    THEN current_setting('cloudtms.pay_workbench_reconcile_slice_v1', true)::jsonb ELSE NULL::jsonb END;
  v_a28_slice_applies boolean := false;
  v_a28_slice_candidate_id uuid := NULL::uuid;
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_workbench_resolution_session_id uuid := null::uuid;
  v_workbench_resolution_session_id_text text := null::text;
begin
  PERFORM public._imp_debug_audit(
    v_actor_user_id,
    'PAY_PREVIEW_FINANCE_CASE_BASELINE_START',
    jsonb_build_object(
      'candidate_id', p_candidate_id,
      'context_pay_date', p_context_json->>'pay_date',
      'context_pay_week_start', p_context_json->>'pay_week_start'
    ),
    'pay_preview_finance',
    COALESCE(p_candidate_id::text, 'NO_CANDIDATE_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  v_workbench_resolution_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_resolution_session_id',
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,resolution_session_id}',
    v_context_json#>>'{workbench,session_id}',
    ''
  )), '');

  IF v_workbench_resolution_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_resolution_session_id := v_workbench_resolution_session_id_text::uuid;

    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS resolution_session
    WHERE resolution_session.id = v_workbench_resolution_session_id
      AND UPPER(BTRIM(COALESCE(resolution_session.status, ''))) = 'OPEN'
      AND resolution_session.discarded_at_utc IS NULL
      AND (
        v_candidate_id = ANY(COALESCE(resolution_session.scope_candidate_ids, ARRAY[]::uuid[]))
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_session_scope AS resolution_scope
          WHERE resolution_scope.session_id = resolution_session.id
            AND resolution_scope.candidate_id = v_candidate_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_preview_rows AS resolution_preview_row
          WHERE resolution_preview_row.session_id = resolution_session.id
            AND resolution_preview_row.candidate_id = v_candidate_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS resolution_line_work
          WHERE resolution_line_work.session_id = resolution_session.id
            AND resolution_line_work.candidate_id = v_candidate_id
        )
      );

    IF NOT FOUND THEN
      v_workbench_resolution_session_id := NULL::uuid;
    END IF;
  ELSE
    v_workbench_resolution_session_id := NULL::uuid;
  END IF;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.cand_payee') is null then
    perform public.pay_preview_candidate_build_payee_baseline(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.finance_case_repaid_wtd, pg_temp.finance_case_recovery_rows_base, pg_temp.manual_debt_recovery_rows, pg_temp.manual_debt_recovery_allocations, pg_temp.manual_debt_recovery_totals, pg_temp.overpayment_recovery_rows, pg_temp.overpayment_recovery_allocations, pg_temp.overpayment_recovery_totals, pg_temp.payment_advance_recovery_rows, pg_temp.payment_advance_recovery_allocations, pg_temp.finance_case_protected_allocations, pg_temp.finance_case_payee_readiness, pg_temp.finance_case_component_rows, pg_temp.finance_case_component_review_rows, pg_temp.finance_case_component_review_rows_effective, pg_temp.finance_case_due_source_amounts, pg_temp.finance_case_component_due_source_base, pg_temp.finance_case_component_due_source_shares, pg_temp.finance_case_component_due_source_allocations, pg_temp.finance_case_component_due_preview_base, pg_temp.finance_case_component_due_preview_allocations, pg_temp.finance_case_taxable_manual_debt_resolution, pg_temp.finance_case_bucket_resolution_overlay, pg_temp.finance_case_nonbucket_resolution_overlay, pg_temp.finance_case_nonbucket_resolution_overlay_alloc, pg_temp.finance_case_taxable_channel_restructure_resolution, pg_temp.finance_case_resolution_owner_state, pg_temp.finance_case_resolution_rollup;

  create temporary table finance_case_repaid_wtd on commit drop as
        select
          nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid as finance_case_id,
          round(sum(abs(coalesce(pbi.amount_ex_vat,0))),2) as repaid_wtd_ex
        from public.pay_batch_items pbi
        join public.pay_batch_candidates pbc
          on pbc.id = pbi.pay_batch_candidate_id
        join public.pay_batches pb
          on pb.id = pbc.pay_batch_id
        left join public.pay_bank_transfers pbt
          on pbt.id = pbi.pay_bank_transfer_id
        where coalesce(pbi.is_voided, false) = false
          and pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
          and pbi.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')
          and pbi.repayment_week_start = v_week_start
          and upper(coalesce(pb.status::text,'')) <> 'CANCELLED'
          and not exists (
            select 1
            from public.pay_payment_correction_items pci_repaid_wtd
            where pci_repaid_wtd.pay_batch_item_id = pbi.id
              and pci_repaid_wtd.status = 'APPLIED'
              and pci_repaid_wtd.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
          )
          and (
            upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
            or pbc.settled_at_utc is not null
            or upper(btrim(coalesce(pbt.status, ''))) = 'COMPLETED'
            or pbt.completed_at_utc is not null
            or exists (
              select 1
              from public.pay_advance_reservations par_repaid_wtd
              where par_repaid_wtd.pay_batch_item_id = pbi.id
                and (
                  upper(btrim(coalesce(par_repaid_wtd.status, ''))) = 'SETTLED'
                  or par_repaid_wtd.settled_at_utc is not null
                )
            )
          )
        group by nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid

  ;


  /* Policy X: recovery headroom is pre-draft live truth, but it must use the
     same central economic-outstanding authority that preview materialisation
     uses.  Raw timesheet deltas whose settled baseline is already exhausted
     must not create funds from which a recovery can be taken. */
  drop table if exists pg_temp.candidate_authoritative_recovery_headroom;

  create temporary table candidate_authoritative_recovery_headroom on commit drop as
        with recovery_timesheet_scope as (
          select
            cr.candidate_id,
            coalesce(
              array_agg(distinct tcr.timesheet_id order by tcr.timesheet_id)
                filter (where tcr.timesheet_id is not null),
              array[]::uuid[]
            ) as timesheet_ids
          from candidate_rollup cr
          left join timesheet_case_rollup_payable tcr
            on tcr.candidate_id = cr.candidate_id
           and coalesce(tcr.is_blocked, false) = false
          group by cr.candidate_id
        )
        select
          rts.candidate_id,
          round(
            coalesce(
              sum(greatest(coalesce(oc.outstanding_ex_vat, 0), 0)),
              0
            ),
            2
          )::numeric(12,2) as authoritative_recovery_headroom_ex
        from recovery_timesheet_scope rts
        left join lateral public._pay_outstanding_components(
          rts.timesheet_ids,
          null::uuid
        ) oc on true
        group by rts.candidate_id

  ;


  -- A28: honour the slice hand-over only inside the exact authoritative Workbench build that set it.
  v_a28_slice_applies := v_a28_slice IS NOT NULL
    AND COALESCE((v_a28_slice->>'final')::boolean, false)
    AND COALESCE(v_a28_slice->>'build_token', '') <> ''
    AND v_a28_slice->>'build_token' = COALESCE(current_setting('cloudtms.pay_workbench_overpayment_sync_token', true), '');
  IF v_a28_slice_applies THEN
    v_a28_slice_candidate_id := (v_a28_slice->>'candidate_id')::uuid;
  END IF;
  IF v_a28_slice_applies THEN
    -- The final slice's own payable Timesheets plus the carried, additive headroom of the earlier slices equals
    -- the headroom an unsliced reconciliation of the whole Candidate computes.
    UPDATE pg_temp.candidate_authoritative_recovery_headroom
    SET authoritative_recovery_headroom_ex = ROUND(authoritative_recovery_headroom_ex
      + COALESCE((v_a28_slice->>'prior_recovery_headroom_ex')::numeric, 0), 2)::numeric(12,2)
    WHERE candidate_id = v_a28_slice_candidate_id;
  END IF;

create temporary table finance_case_recovery_rows_base on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          vfcr.taxability,
          upper(coalesce(cr.cand_pay_method,'')) as candidate_pay_method,
          round(greatest(coalesce(carh.authoritative_recovery_headroom_ex,0),0),2)::numeric(12,2) as run_earnings_headroom_ex,
          round(
            greatest(
              coalesce(pwb.paid_wtd_before,0)
              + greatest(coalesce(carh.authoritative_recovery_headroom_ex,0),0),
              0
            ),
            2
          )::numeric(12,2) as run_take_home_before,
          round(greatest(coalesce(c.min_take_home_wtd,0),0),2)::numeric(12,2) as default_take_home_floor,
          vfcr.payout_status,
          vfcr.created_at,
          case
            when vfcr.minimum_earnings_threshold is null then null::numeric(12,2)
            else round(greatest(vfcr.minimum_earnings_threshold,0),2)::numeric(12,2)
          end as minimum_earnings_threshold,
          case
            when vfcr.take_home_floor_override is null then null::numeric(12,2)
            else round(greatest(vfcr.take_home_floor_override,0),2)::numeric(12,2)
          end as take_home_floor_override,
          round(
            greatest(
              case
                when vfcr.case_type = 'PAYMENT_ADVANCE'
                 and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID'
                then least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                     - coalesce(fcrw.repaid_wtd_ex,0)
                     - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
                then least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                     - coalesce(fcrw.repaid_wtd_ex,0)
                     - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                when vfcr.case_type = 'OVERPAYMENT'
                then greatest(coalesce(vfcr.outstanding_amount,0) - coalesce(vfcr.active_reserved_amount,0), 0)
                else 0::numeric
              end,
              0::numeric
            ),
            2
          )::numeric(12,2) as nominal_due_amount
        from finance_case_baseline_scope vfcr
        join candidate_rollup cr
          on cr.candidate_id = vfcr.candidate_id
        join candidate_authoritative_recovery_headroom carh
          on carh.candidate_id = vfcr.candidate_id
        join public.candidates c
          on c.id = vfcr.candidate_id
        left join paid_wtd_before pwb
          on pwb.candidate_id = vfcr.candidate_id
        left join finance_case_repaid_wtd fcrw
          on fcrw.finance_case_id = vfcr.finance_case_id
        where vfcr.case_type in ('PAYMENT_ADVANCE','MANUAL_DEBT_ADJUSTMENT','OVERPAYMENT')
          and (
            (vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID')
            or vfcr.case_type in ('MANUAL_DEBT_ADJUSTMENT','OVERPAYMENT')
          )

  ;

  create temporary table manual_debt_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          fcrrb.default_take_home_floor,
          row_number() over (
            partition by fcrrb.candidate_id
            order by private.s3p_recovery_order_key_v1(fcrrb.finance_case_id), fcrrb.finance_case_id /* S3-WP3 Q6-A ruling 31: creation order, loans by payout (was created_at, id) */
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT'
          and fcrrb.nominal_due_amount > 0

  ;

  create temporary table manual_debt_recovery_allocations on commit drop as
        select
          mdra.candidate_id,
          mdra_alloc.finance_case_id,
          round(coalesce(mdra_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            mdrr.candidate_id,
            max(mdrr.run_earnings_headroom_ex) as run_earnings_headroom_ex,
            max(mdrr.run_take_home_before) as run_take_home_before,
            max(mdrr.default_take_home_floor) as default_take_home_floor,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', mdrr.sort_order,
                'finance_case_id', mdrr.finance_case_id::text,
                'case_type', mdrr.case_type::text,
                'payout_status', case when mdrr.payout_status is null then null else mdrr.payout_status::text end,
                'nominal_due_amount', mdrr.nominal_due_amount,
                'minimum_earnings_threshold', mdrr.minimum_earnings_threshold,
                'take_home_floor_override', mdrr.take_home_floor_override
              )
              order by mdrr.sort_order, mdrr.finance_case_id
            ) as recovery_rows_json
          from manual_debt_recovery_rows mdrr
          group by mdrr.candidate_id
        ) mdra
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => mdra.recovery_rows_json,
          p_run_earnings_headroom => mdra.run_earnings_headroom_ex,
          p_run_take_home_headroom => mdra.run_take_home_before,
          p_default_take_home_floor => mdra.default_take_home_floor
        ) mdra_alloc

  ;

  create temporary table manual_debt_recovery_totals on commit drop as
        select
          mdra.candidate_id,
          round(sum(mdra.protected_recoverable_amount),2)::numeric(12,2) as protected_recoverable_total
        from manual_debt_recovery_allocations mdra
        group by mdra.candidate_id

  ;

  create temporary table overpayment_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.candidate_pay_method,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          fcrrb.default_take_home_floor,
          row_number() over (
            partition by fcrrb.candidate_id
            order by private.s3p_recovery_order_key_v1(fcrrb.finance_case_id), fcrrb.finance_case_id /* S3-WP3 Q6-A ruling 31: creation order, loans by payout (was created_at, id) */
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'OVERPAYMENT'
          and fcrrb.nominal_due_amount > 0

  ;

  create temporary table overpayment_recovery_allocations on commit drop as
        select
          opra.candidate_id,
          opra_alloc.finance_case_id,
          round(coalesce(opra_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            oprr.candidate_id,
            max(
              case
                when oprr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      oprr.run_earnings_headroom_ex - coalesce(mdrt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else oprr.run_earnings_headroom_ex
              end
            ) as run_earnings_headroom_ex,
            max(
              case
                when oprr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      oprr.run_take_home_before - coalesce(mdrt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else oprr.run_take_home_before
              end
            ) as run_take_home_before,
            max(oprr.default_take_home_floor) as default_take_home_floor,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', oprr.sort_order,
                'finance_case_id', oprr.finance_case_id::text,
                'case_type', 'MANUAL_DEBT_ADJUSTMENT',
                'payout_status', null,
                'nominal_due_amount', oprr.nominal_due_amount,
                'minimum_earnings_threshold', oprr.minimum_earnings_threshold,
                'take_home_floor_override', oprr.take_home_floor_override
              )
              order by oprr.sort_order, oprr.finance_case_id
            ) as recovery_rows_json
          from overpayment_recovery_rows oprr
          left join manual_debt_recovery_totals mdrt
            on mdrt.candidate_id = oprr.candidate_id
          group by oprr.candidate_id
        ) opra
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => opra.recovery_rows_json,
          p_run_earnings_headroom => opra.run_earnings_headroom_ex,
          p_run_take_home_headroom => opra.run_take_home_before,
          p_default_take_home_floor => opra.default_take_home_floor
        ) opra_alloc

  ;

  create temporary table overpayment_recovery_totals on commit drop as
        select
          opra.candidate_id,
          round(sum(opra.protected_recoverable_amount),2)::numeric(12,2) as protected_recoverable_total
        from overpayment_recovery_allocations opra
        group by opra.candidate_id

  ;

  create temporary table payment_advance_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.candidate_pay_method,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          row_number() over (
            partition by fcrrb.candidate_id
            order by private.s3p_recovery_order_key_v1(fcrrb.finance_case_id), fcrrb.finance_case_id /* S3-WP3 Q6-A ruling 31: creation order, loans by payout (was created_at, id) */
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'PAYMENT_ADVANCE'
          and upper(coalesce(fcrrb.payout_status::text,'')) = 'PAID'
          and fcrrb.nominal_due_amount > 0

  ;

  create temporary table payment_advance_recovery_allocations on commit drop as
        select
          para.candidate_id,
          para_alloc.finance_case_id,
          round(coalesce(para_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            parr.candidate_id,
            max(
              case
                when parr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      parr.run_earnings_headroom_ex - coalesce(mdrt.protected_recoverable_total,0) - coalesce(oprt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else parr.run_earnings_headroom_ex
              end
            ) as run_earnings_headroom_ex,
            max(
              case
                when parr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      parr.run_take_home_before - coalesce(mdrt.protected_recoverable_total,0) - coalesce(oprt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else parr.run_take_home_before
              end
            ) as run_take_home_before,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', parr.sort_order,
                'finance_case_id', parr.finance_case_id::text,
                'case_type', parr.case_type::text,
                'payout_status', case when parr.payout_status is null then null else parr.payout_status::text end,
                'nominal_due_amount', parr.nominal_due_amount,
                'minimum_earnings_threshold', parr.minimum_earnings_threshold,
                'take_home_floor_override', parr.take_home_floor_override
              )
              order by parr.sort_order, parr.finance_case_id
            ) as recovery_rows_json
          from payment_advance_recovery_rows parr
          left join manual_debt_recovery_totals mdrt
            on mdrt.candidate_id = parr.candidate_id
          left join overpayment_recovery_totals oprt
            on oprt.candidate_id = parr.candidate_id
          group by parr.candidate_id
        ) para
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => para.recovery_rows_json,
          p_run_earnings_headroom => para.run_earnings_headroom_ex,
          p_run_take_home_headroom => para.run_take_home_before,
          p_default_take_home_floor => null::numeric
        ) para_alloc

  ;

  create temporary table finance_case_protected_allocations on commit drop as
        select
          mdra.finance_case_id,
          mdra.protected_recoverable_amount
        from manual_debt_recovery_allocations mdra

        union all

        select
          opra.finance_case_id,
          opra.protected_recoverable_amount
        from overpayment_recovery_allocations opra

        union all

        select
          para.finance_case_id,
          para.protected_recoverable_amount
        from payment_advance_recovery_allocations para

  ;

  create temporary table finance_case_payee_readiness on commit drop as
        select
          f0.finance_case_id,
          f0.payee_entity_kind,
          f0.payee_entity_id,
          f0.bank_details_hash,
          f0.beneficiary_name,
          f0.sort_code,
          f0.account_number,
          case
            when f0.account_number is null or btrim(coalesce(f0.account_number,'')) = '' then null
            else lpad(right(f0.account_number, 4), greatest(length(f0.account_number), 4), '*')
          end as masked_bank_account,
          coalesce(bnc.status, 'UNVERIFIED') as name_check_status,
          (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash) as name_check_has_override,
          (bpm.payee_id is not null) as payee_map_present,
          (
            f0.payee_entity_id is null
            or f0.bank_details_hash is null
            or btrim(coalesce(f0.bank_details_hash,'')) = ''
            or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
            or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
            or nullif(btrim(coalesce(f0.account_number,'')), '') is null
          ) as is_missing_bank_details,
          (
            v_need_name_check = true
            and not (
              f0.payee_entity_id is null
              or f0.bank_details_hash is null
              or btrim(coalesce(f0.bank_details_hash,'')) = ''
              or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
              or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
              or nullif(btrim(coalesce(f0.account_number,'')), '') is null
            )
            and coalesce(bnc.status, 'UNVERIFIED') <> 'PASS'
            and not (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash)
          ) as is_name_check_blocked,
          (
            v_requires_payee_map = true
            and not (
              f0.payee_entity_id is null
              or f0.bank_details_hash is null
              or btrim(coalesce(f0.bank_details_hash,'')) = ''
              or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
              or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
              or nullif(btrim(coalesce(f0.account_number,'')), '') is null
            )
            and bpm.payee_id is null
          ) as is_payee_map_blocked,
          (
            (case
              when (
                f0.payee_entity_id is null
                or f0.bank_details_hash is null
                or btrim(coalesce(f0.bank_details_hash,'')) = ''
                or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                or nullif(btrim(coalesce(f0.account_number,'')), '') is null
              )
              then jsonb_build_array('BLOCKED_BANK_DETAILS')
              else '[]'::jsonb
            end)
            ||
            (case
              when (
                v_need_name_check = true
                and not (
                  f0.payee_entity_id is null
                  or f0.bank_details_hash is null
                  or btrim(coalesce(f0.bank_details_hash,'')) = ''
                  or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                  or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                  or nullif(btrim(coalesce(f0.account_number,'')), '') is null
                )
                and coalesce(bnc.status, 'UNVERIFIED') <> 'PASS'
                and not (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash)
              )
              then jsonb_build_array('BLOCKED_NAME_CHECK')
              else '[]'::jsonb
            end)
            ||
            (case
              when (
                v_requires_payee_map = true
                and not (
                  f0.payee_entity_id is null
                  or f0.bank_details_hash is null
                  or btrim(coalesce(f0.bank_details_hash,'')) = ''
                  or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                  or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                  or nullif(btrim(coalesce(f0.account_number,'')), '') is null
                )
                and bpm.payee_id is null
              )
              then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes
        from (
          select
            vfcr.finance_case_id,
            case
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then 'UMBRELLA'
              else 'CANDIDATE'
            end as payee_entity_kind,
            case
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then c.umbrella_id
              else vfcr.candidate_id
            end as payee_entity_id,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.bank_details_hash
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.bank_details_hash
              else c.bank_details_hash
            end as bank_details_hash,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.beneficiary_name
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.name
              else coalesce(c.account_holder, c.display_name)
            end as beneficiary_name,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.sort_code
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.sort_code
              else c.sort_code
            end as sort_code,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.account_number
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.account_number
              else c.account_number
            end as account_number
          from finance_case_baseline_scope vfcr
          join public.candidates c
            on c.id = vfcr.candidate_id
          left join public.umbrellas u
            on u.id = c.umbrella_id
          left join public.pay_finance_case_oneoff_payout_bank_details obd
            on obd.finance_case_id = vfcr.finance_case_id
          where vfcr.finance_case_id is not null
        ) f0
        left join public.bank_name_checks bnc
          on bnc.rail_provider = v_rail_provider_default
         and bnc.rail_env = v_rail_env_default
         and bnc.entity_kind = f0.payee_entity_kind
         and bnc.entity_id = f0.payee_entity_id
         and bnc.bank_details_hash is not distinct from f0.bank_details_hash
        left join public.bank_payee_map bpm
          on bpm.rail_provider = v_rail_provider_default
         and bpm.rail_env = v_rail_env_default
         and bpm.entity_kind = f0.payee_entity_kind
         and bpm.entity_id = f0.payee_entity_id
         and bpm.bank_details_hash is not distinct from f0.bank_details_hash

  ;

  create temporary table finance_case_component_rows on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          vfcr.taxability,
          pfc.id as finance_component_id,
          pfc.source_family_key,
          pfc.component_key_type,
          pfc.component_key_value,
          pfc.classification,
          upper(coalesce(pfc.source_pay_method, '')) as source_pay_method,
          upper(coalesce(cp.cand_pay_method, '')) as current_target_pay_method,
          cp.umb_vat_chargeable,
          pfc.source_basis_json,
          round(coalesce(pfc.source_amount, 0), 2) as source_amount,
          round(coalesce(pfc.remaining_source_amount, 0), 2) as remaining_source_amount,
          pfc.saved_target_pay_method,
          pfc.saved_resolution_mode,
          pfc.saved_resolution_payload_json,
          pfc.saved_resolution_result_json,
          pfc.resolution_fingerprint,
          pfc.is_resolution_stale,
          pfc.stale_reason,
          public.pay_finance_component_fingerprint(
            pfc.source_family_key,
            pfc.component_key_type,
            pfc.component_key_value,
            pfc.classification,
            upper(coalesce(pfc.source_pay_method, '')),
            upper(coalesce(cp.cand_pay_method, '')),
            coalesce(pfc.source_basis_json, '{}'::jsonb),
            round(coalesce(pfc.source_amount, 0), 2),
            case
              when coalesce(pfc.saved_resolution_payload_json->>'relevant_erni_pct', pfc.saved_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
                then coalesce(pfc.saved_resolution_payload_json->>'relevant_erni_pct', pfc.saved_resolution_result_json->>'relevant_erni_pct')::numeric
              else v_erni_pct
            end,
            coalesce(pfc.saved_resolution_payload_json, pfc.saved_resolution_result_json, '{}'::jsonb)
          ) as current_component_fingerprint
        from finance_case_baseline_scope vfcr
        join cand_payee cp
          on cp.candidate_id = vfcr.candidate_id
        join public.pay_finance_case_components pfc
          on pfc.finance_case_id = vfcr.finance_case_id
         and pfc.closed_at_utc is null
         and coalesce(pfc.remaining_source_amount, 0) > 0

  ;


  WITH policy_x_finance_component_rows AS (
    SELECT
      component_row.ctid AS row_ctid,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value
    FROM finance_case_component_rows AS component_row
    LEFT JOIN LATERAL public._pay_policy_x_resolve_pre_draft_economic_key(
      p_timesheet_id => CASE
        WHEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END,
      p_live_source_json => COALESCE(component_row.source_basis_json, '{}'::jsonb)
        || jsonb_build_object(
          'finance_case_id', component_row.finance_case_id::text,
          'finance_component_id', CASE WHEN component_row.finance_component_id IS NULL THEN NULL ELSE component_row.finance_component_id::text END,
          'source_family_key', component_row.source_family_key,
          'component_key_type', component_row.component_key_type,
          'component_key_value', component_row.component_key_value,
          'classification', CASE WHEN component_row.classification IS NULL THEN NULL ELSE component_row.classification::text END,
          'item_type', CASE
            WHEN component_row.component_key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
            WHEN component_row.component_key_type = 'EXPENSE_CODE'
             AND UPPER(BTRIM(COALESCE(component_row.component_key_value, ''))) = 'MILEAGE' THEN 'MILEAGE_DELTA'
            WHEN component_row.component_key_type = 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
            WHEN component_row.component_key_type = 'ADDITIONAL_CODE' THEN 'EXPENSE_DELTA'
            WHEN component_row.component_key_type = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
            ELSE 'ADJUSTMENT_DELTA'
          END
        ),
      p_item_type => CASE
        WHEN component_row.component_key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN component_row.component_key_type = 'EXPENSE_CODE'
         AND UPPER(BTRIM(COALESCE(component_row.component_key_value, ''))) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        WHEN component_row.component_key_type = 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
        WHEN component_row.component_key_type = 'ADDITIONAL_CODE' THEN 'EXPENSE_DELTA'
        WHEN component_row.component_key_type = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
        ELSE 'ADJUSTMENT_DELTA'
      END,
      p_key_type_hint => NULL::text,
      p_key_value_hint => NULL::text,
      p_work_date => CASE
        WHEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'work_date', component_row.source_basis_json->>'date', '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
          THEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'work_date', component_row.source_basis_json->>'date', '')), '')::date
        ELSE NULL::date
      END
    ) AS policy_key ON true
  )
  UPDATE finance_case_component_rows AS component_row
  SET component_key_type = policy_x_finance_component_rows.resolved_key_type,
      component_key_value = policy_x_finance_component_rows.resolved_key_value,
      current_component_fingerprint = public.pay_finance_component_fingerprint(
        component_row.source_family_key,
        policy_x_finance_component_rows.resolved_key_type,
        policy_x_finance_component_rows.resolved_key_value,
        component_row.classification,
        component_row.source_pay_method,
        component_row.current_target_pay_method,
        COALESCE(component_row.source_basis_json, '{}'::jsonb),
        round(COALESCE(component_row.source_amount, 0), 2),
        CASE
          WHEN COALESCE(component_row.saved_resolution_payload_json->>'relevant_erni_pct', component_row.saved_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
            THEN COALESCE(component_row.saved_resolution_payload_json->>'relevant_erni_pct', component_row.saved_resolution_result_json->>'relevant_erni_pct')::numeric
          ELSE v_erni_pct
        END,
        COALESCE(component_row.saved_resolution_payload_json, component_row.saved_resolution_result_json, '{}'::jsonb)
      )
  FROM policy_x_finance_component_rows
  WHERE component_row.ctid = policy_x_finance_component_rows.row_ctid
    AND policy_x_finance_component_rows.resolved_key_type IS NOT NULL
    AND policy_x_finance_component_rows.resolved_key_value IS NOT NULL;

  create temporary table finance_case_component_review_rows on commit drop as
        select
          fccr.finance_case_id,
          fccr.candidate_id,
          fccr.case_type,
          fccr.taxability,
          fccr.finance_component_id,
          fccr.source_family_key,
          fccr.component_key_type,
          fccr.component_key_value,
          fccr.classification,
          fccr.source_pay_method,
          fccr.current_target_pay_method,
          fccr.umb_vat_chargeable,
          fccr.source_basis_json,
          fccr.source_amount,
          fccr.remaining_source_amount,
          nullif(fccr.source_basis_json->>'source_units','')::numeric as source_units,
          nullif(fccr.source_basis_json->>'source_rate','')::numeric as source_rate,
          nullif(fccr.source_basis_json->>'source_charge_rate','')::numeric as source_charge_rate,
          coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) as source_charge_ex_vat,
          fccr.saved_target_pay_method,
          fccr.saved_resolution_mode,
          fccr.saved_resolution_payload_json,
          fccr.saved_resolution_result_json,
          fccr.resolution_fingerprint,
          fccr.is_resolution_stale,
          fccr.stale_reason,
          fccr.current_component_fingerprint,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
          ) as has_suggested_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint) then 'REUSABLE_SAVED_RESOLUTION'
            when fccr.saved_resolution_mode is not null then 'STALE_SAVED_RESOLUTION'
            else 'FRESH_SUGGESTION'
          end as suggestion_provenance,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
            and fccr.saved_resolution_mode is null
          ) as is_fresh_suggested_resolution,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.saved_resolution_mode is not null
            and coalesce(fccr.is_resolution_stale,false) = false
            and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,''))
            and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
          ) as is_reusable_saved_resolution,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.saved_resolution_mode is not null
            and (
              coalesce(fccr.is_resolution_stale,false) = true
              or upper(coalesce(fccr.saved_target_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              or (fccr.resolution_fingerprint is not null and fccr.resolution_fingerprint is distinct from fccr.current_component_fingerprint)
            )
          ) as is_stale_saved_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
              then fccr.saved_resolution_payload_json
            else jsonb_strip_nulls(jsonb_build_object(
              'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
              'target_pay_method', fccr.current_target_pay_method,
              'applied_basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'relevant_erni_pct', round(v_erni_pct,6),
              'vat_rate_pct', round(v_vat_rate_pct,6),
              'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
              'target_units', case when nullif(fccr.source_basis_json->>'source_units','') is not null then round(nullif(fccr.source_basis_json->>'source_units','')::numeric,6) else null end,
              'suggested_target_rate', case when nullif(fccr.source_basis_json->>'source_units','') is not null and nullif(fccr.source_basis_json->>'source_units','')::numeric <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / (nullif(fccr.source_basis_json->>'source_units','')::numeric), 2) else null end,
              'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
            ))
          end as suggested_resolution_payload_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
              then fccr.saved_resolution_result_json
            else jsonb_strip_nulls(jsonb_build_object(
              'target_pay_method', fccr.current_target_pay_method,
              'target_amount_ex_vat', round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),
              'target_amount_vat', round(coalesce((fcsr.target_amounts_json->>'vat')::numeric,0),2),
              'target_amount_inc_vat', round(coalesce((fcsr.target_amounts_json->>'inc')::numeric,0),2),
              'basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'applied_basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'relevant_erni_pct', round(v_erni_pct,6),
              'vat_rate_pct', round(v_vat_rate_pct,6),
              'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
              'target_units', case when nullif(fccr.source_basis_json->>'source_units','') is not null then round(nullif(fccr.source_basis_json->>'source_units','')::numeric,6) else null end,
              'replacement_rate', case when nullif(fccr.source_basis_json->>'source_units','') is not null and nullif(fccr.source_basis_json->>'source_units','')::numeric <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / (nullif(fccr.source_basis_json->>'source_units','')::numeric), 2) else null end,
              'target_amount_ex_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_amount_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'vat')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_amount_inc_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'inc')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_units_per_source_ex_vat', case when nullif(fccr.source_basis_json->>'source_units','') is not null and coalesce(fccr.source_amount,0) <> 0 then round((nullif(fccr.source_basis_json->>'source_units','')::numeric) / fccr.source_amount, 10) else null end,
              'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
              'source_pay_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'source_charge_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric),2) end,
              'source_margin_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) - fccr.source_amount,2) end,
              'target_pay_ex_vat', round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),
              'target_charge_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric),2) end,
              'target_margin_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null or fcsr.target_amounts_json is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) - round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),2) end,
              'margin_delta_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null or fcsr.target_amounts_json is null then null else round(fccr.source_amount - round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),2) end
            ))
          end as suggested_resolution_result_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint) then 'This component already has a reusable saved resolution for the current target pay method.'
            when fccr.saved_resolution_mode is not null then 'A stale saved resolution exists for this component. The suggested rates below reflect the current target pay method.'
            when fccr.source_pay_method <> fccr.current_target_pay_method then 'This suggestion converts the taxable component to a target-side equivalent while leaving fixed reimbursements unchanged.'
            else 'This suggestion preserves equivalent basis using the current target pay method.'
          end as suggestion_explanation_text
        from finance_case_component_rows fccr
        left join lateral (
          select
            case
              when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
              when fccr.source_pay_method = 'PAYE' and fccr.current_target_pay_method = 'UMBRELLA' then public._pay_convert_paye_to_umbrella(fccr.source_amount, v_erni_pct, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              when fccr.source_pay_method = 'UMBRELLA' and fccr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', public._pay_convert_umbrella_to_paye_ex(fccr.source_amount, v_erni_pct), 'vat', 0, 'inc', public._pay_convert_umbrella_to_paye_ex(fccr.source_amount, v_erni_pct))
              when fccr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', round(coalesce(fccr.source_amount,0),2), 'vat', 0, 'inc', round(coalesce(fccr.source_amount,0),2))
              when fccr.current_target_pay_method = 'UMBRELLA' then public._pay_umbrella_vat_calc(fccr.source_amount, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              else null::jsonb
            end as target_amounts_json
        ) fcsr on true

  ;

  create temporary table finance_case_component_review_rows_effective on commit drop as
        select
          fccr.finance_case_id,
          fccr.candidate_id,
          fccr.case_type,
          fccr.taxability,
          fccr.finance_component_id,
          fccr.source_family_key,
          fccr.component_key_type,
          fccr.component_key_value,
          fccr.classification,
          fccr.source_pay_method,
          fccr.current_target_pay_method,
          fccr.umb_vat_chargeable,
          fccr.source_basis_json,
          fccr.source_amount,
          fccr.remaining_source_amount,
          fccr.source_units,
          fccr.source_rate,
          fccr.source_charge_rate,
          fccr.source_charge_ex_vat,
          fccr.saved_target_pay_method,
          fccr.saved_resolution_mode,
          fccr.saved_resolution_payload_json,
          fccr.saved_resolution_result_json,
          fccr.resolution_fingerprint,
          fccr.is_resolution_stale,
          fccr.stale_reason,
          fccr.current_component_fingerprint,
          fctx.is_actionable_bucket_resolution as is_actionable_resolution_row,
          fctx.is_fixed_taxable_conversion as is_fixed_no_action_taxable_row,
          null::text as approved_resolution_mode,
          null::numeric as approved_target_rate,
          null::text as approved_nonbucket_resolution_mode,
          null::numeric as approved_nonbucket_target_amount_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then false
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then false
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then not (coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false)
            when fctx.is_actionable_bucket_resolution = true and coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then false
            when fctx.is_actionable_bucket_resolution = true then true
            else false
          end as requires_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then true
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then true
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then (coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false)
            when fctx.is_actionable_bucket_resolution = true and coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then true
            when fctx.is_actionable_bucket_resolution = true then false
            else true
          end as case_resolution_satisfied_now_component,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
          ) as has_suggested_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then 'NO_SUGGESTION_AVAILABLE'
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then 'REUSABLE_SAVED_RESOLUTION'
            when coalesce(fccr.is_stale_saved_resolution,false) = true then 'STALE_SAVED_RESOLUTION'
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'FRESH_SUGGESTION'
            when fctx.is_actionable_bucket_resolution = true then 'FRESH_SUGGESTION'
            else 'NO_ACTION_FIXED_CONVERSION'
          end as suggestion_provenance,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
            and coalesce(fccr.is_reusable_saved_resolution,false) = false
            and coalesce(fccr.is_stale_saved_resolution,false) = false
            and (
              fctx.is_actionable_bucket_resolution = true
              or fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
            )
          ) as is_fresh_suggested_resolution,
          coalesce(fccr.is_reusable_saved_resolution,false) as is_reusable_saved_resolution,
          coalesce(fccr.is_stale_saved_resolution,false) as is_stale_saved_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then fccr.saved_resolution_payload_json
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', fccr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'suggested_target_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            when fctx.is_actionable_bucket_resolution = true or fctx.is_fixed_taxable_conversion = true or upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,'')) then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', fccr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'suggested_target_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            else fccr.suggested_resolution_payload_json
          end as suggested_resolution_payload_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then fccr.saved_resolution_result_json
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', fccr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_amount_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric, 0),2),
                'target_amount_inc_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2),
                'basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'replacement_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'target_amount_ex_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric,0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_units_per_source_ex_vat', case when fccr.source_units is not null and round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(fccr.source_units / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'source_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'target_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end,
                'margin_delta_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.basis_source_amount_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end
              )
            )
            when fctx.is_actionable_bucket_resolution = true or fctx.is_fixed_taxable_conversion = true or upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,'')) then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', fccr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_amount_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric, 0),2),
                'target_amount_inc_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2),
                'basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'replacement_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'target_amount_ex_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric,0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_units_per_source_ex_vat', case when fccr.source_units is not null and round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(fccr.source_units / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'source_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'target_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end,
                'margin_delta_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.basis_source_amount_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end
              )
            )
            else fccr.suggested_resolution_result_json
          end as suggested_resolution_result_json,
          round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) as source_pay_ex_vat,
          case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end as source_charge_component_ex_vat,
          case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end as source_margin_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
            else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
          end as target_pay_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null then round(fbasis.source_charge_basis_ex_vat,2)
            else null::numeric
          end as target_charge_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null
              then round(
                fbasis.source_charge_basis_ex_vat - case
                  when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
                  when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
                  else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
                end,
                2
              )
            else null::numeric
          end as target_margin_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null
              then round(
                fbasis.basis_source_amount_ex_vat - case
                  when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
                  when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
                  else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
                end,
                2
              )
            else null::numeric
          end as margin_delta_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then 'No suggested rates are required because this taxable component already aligns with the current target pay method.'
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then 'This component already has a reusable saved resolution for the current target pay method.'
            when coalesce(fccr.is_stale_saved_resolution,false) = true then 'A stale saved resolution exists for this component. The suggested rates below reflect the current target pay method.'
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'This non-bucket finance case resolves as one suggested/editable gross total. The total remaining source amount is converted onto the current target pay method.'
            when fctx.is_fixed_taxable_conversion = true then 'This taxable row does not expose a per-unit rate edit. It remains visible as a fixed no-action row and is converted deterministically onto the current target pay method.'
            else 'This suggestion converts the taxable component to a target-side equivalent while keeping units fixed, charge fixed, and margin constant except for unavoidable penny balancing.'
          end as suggestion_explanation_text
        from finance_case_component_review_rows fccr
        left join lateral (
          select
            (
              fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and fccr.source_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method <> ''
              and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              and fccr.source_units is not null
              and coalesce(fccr.source_units,0) <> 0
              and fccr.source_rate is not null
              and fccr.source_charge_rate is not null
              and fccr.component_key_type <> 'ADJUSTMENT_CODE'
    and fccr.case_type <> 'MANUAL_DEBT_ADJUSTMENT'
            ) as is_actionable_bucket_resolution,
            (
              fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and fccr.source_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method <> ''
              and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              and not (
                fccr.source_units is not null
                and coalesce(fccr.source_units,0) <> 0
                and fccr.source_rate is not null
                and fccr.source_charge_rate is not null
                and fccr.component_key_type <> 'ADJUSTMENT_CODE'
                and fccr.case_type <> 'MANUAL_DEBT_ADJUSTMENT'
              )
            ) as is_fixed_taxable_conversion
        ) fctx on true
        left join lateral (
          select
            round(coalesce(fccr.remaining_source_amount, fccr.source_amount, 0), 2) as basis_source_amount_ex_vat,
            case
              when fccr.source_charge_ex_vat is null then null::numeric
              when round(coalesce(fccr.source_amount,0),2) = 0 then round(coalesce(fccr.source_charge_ex_vat,0),2)
              else round(round(coalesce(fccr.source_charge_ex_vat,0),2) * (round(coalesce(fccr.remaining_source_amount, fccr.source_amount, 0),2) / nullif(round(coalesce(fccr.source_amount,0),2),0)), 2)
            end as source_charge_basis_ex_vat
        ) fbasis on true
        left join lateral (
          select
            case
              when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
              when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
              when fccr.source_pay_method = 'PAYE' and fccr.current_target_pay_method = 'UMBRELLA' then round((public._pay_convert_paye_to_umbrella(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_erni_pct, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              when fccr.source_pay_method = 'UMBRELLA' and fccr.current_target_pay_method = 'PAYE' then round(public._pay_convert_umbrella_to_paye_ex(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_erni_pct),2)
              when fccr.current_target_pay_method = 'UMBRELLA' then round((public._pay_umbrella_vat_calc(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              else round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            end as target_ex_before_rate
        ) fbase_pre on true
        left join lateral (
          select
            case
              when fctx.is_actionable_bucket_resolution = true and fccr.source_units is not null and fccr.source_units <> 0
                then round(fbase_pre.target_ex_before_rate / fccr.source_units, 2)
              else null::numeric
            end as suggested_target_rate,
            case
              when fctx.is_actionable_bucket_resolution = true and fccr.source_units is not null and fccr.source_units <> 0
                then round(round(fbase_pre.target_ex_before_rate / fccr.source_units, 2) * fccr.source_units, 2)
              else round(fbase_pre.target_ex_before_rate, 2)
            end as suggested_target_pay_ex_vat
        ) fbase on true
        left join lateral (
          select
            case
              when fbase.suggested_target_pay_ex_vat is null then null::jsonb
              when upper(coalesce(fccr.current_target_pay_method,'')) = 'UMBRELLA' then public._pay_umbrella_vat_calc(round(coalesce(fbase.suggested_target_pay_ex_vat,0),2), v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              else jsonb_build_object('ex', round(coalesce(fbase.suggested_target_pay_ex_vat,0),2), 'vat', 0, 'inc', round(coalesce(fbase.suggested_target_pay_ex_vat,0),2))
            end as suggested_target_amounts_json
        ) fbase_amounts on true
        left join lateral (
          select
            case
              when coalesce(fccr.is_reusable_saved_resolution,false) = true
               and coalesce(fccr.is_stale_saved_resolution,false) = false
               and coalesce(fccr.saved_resolution_result_json->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
              then round((fccr.saved_resolution_result_json->>'target_amount_ex_vat')::numeric, 2)
              else null::numeric
            end as reusable_saved_target_pay_ex_vat
        ) fsaved on true

  ;


  IF v_workbench_resolution_session_id IS NOT NULL THEN
    CREATE TEMPORARY TABLE finance_case_bucket_resolution_overlay ON COMMIT DROP AS
    WITH stored_resolution_components AS (
      SELECT
        stored_resolution.id AS resolution_id,
        stored_resolution.case_key,
        stored_resolution.timesheet_id,
        stored_resolution.source_basis_fingerprint,
        stored_resolution.source_family_key,
        stored_resolution.bucket_code,
        stored_resolution.component_key_type,
        stored_resolution.component_key_value,
        stored_resolution.payload_json,
        stored_resolution.updated_at_utc,
        bucket_element.ordinality::integer AS bucket_ordinal,
        bucket_element.value AS bucket_json
      FROM public.banking_pay_workbench_session_case_resolutions AS stored_resolution
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(stored_resolution.payload_json->'bucket_resolutions') = 'array'
            THEN stored_resolution.payload_json->'bucket_resolutions'
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS bucket_element(value, ordinality)
      WHERE stored_resolution.session_id = v_workbench_resolution_session_id
        AND stored_resolution.candidate_id = v_candidate_id
        AND UPPER(BTRIM(COALESCE(stored_resolution.resolution_family, ''))) = 'BUCKETED'
        AND jsonb_typeof(bucket_element.value) = 'object'
    )
    SELECT DISTINCT ON (
      resolved_component.finance_case_id,
      resolved_component.source_basis_fingerprint,
      resolved_component.source_family_key,
      COALESCE(resolved_component.bucket_code, ''),
      resolved_component.component_key_type,
      resolved_component.component_key_value
    )
      resolved_component.resolution_id,
      resolved_component.finance_case_id,
      resolved_component.case_key,
      resolved_component.timesheet_id,
      resolved_component.source_basis_fingerprint,
      resolved_component.source_family_key,
      resolved_component.bucket_code,
      resolved_component.component_key_type,
      resolved_component.component_key_value,
      resolved_component.payload_json,
      resolved_component.bucket_json,
      resolved_component.classification,
      resolved_component.source_pay_method,
      resolved_component.target_pay_method,
      resolved_component.source_units,
      resolved_component.source_rate,
      resolved_component.source_charge_rate,
      resolved_component.resolution_mode,
      resolved_component.target_rate
    FROM (
      SELECT
        stored_component.resolution_id,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(stored_component.payload_json->>'finance_case_id', stored_component.bucket_json->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(stored_component.payload_json->>'finance_case_id', stored_component.bucket_json->>'finance_case_id', '')), '')::uuid
          WHEN NULLIF(BTRIM(COALESCE(stored_component.case_key, '')), '') ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN substring(NULLIF(BTRIM(COALESCE(stored_component.case_key, '')), '') from 9)::uuid
          ELSE NULL::uuid
        END AS finance_case_id,
        stored_component.case_key,
        stored_component.timesheet_id,
        COALESCE(
          NULLIF(BTRIM(COALESCE(stored_component.source_basis_fingerprint, '')), ''),
          NULLIF(BTRIM(COALESCE(stored_component.bucket_json->>'source_basis_fingerprint', '')), ''),
          CASE
            WHEN jsonb_typeof(stored_component.bucket_json->'source_basis_json') = 'object'
              THEN md5((stored_component.bucket_json->'source_basis_json')::text)
            ELSE NULL::text
          END
        ) AS source_basis_fingerprint,
        NULLIF(BTRIM(COALESCE(stored_component.source_family_key, stored_component.bucket_json->>'source_family_key', '')), '') AS source_family_key,
        NULLIF(UPPER(BTRIM(COALESCE(stored_component.bucket_code, stored_component.bucket_json->>'bucket_code', ''))), '') AS bucket_code,
        NULLIF(UPPER(BTRIM(COALESCE(stored_component.component_key_type, stored_component.bucket_json->>'component_key_type', ''))), '') AS component_key_type,
        NULLIF(BTRIM(COALESCE(stored_component.component_key_value, stored_component.bucket_json->>'component_key_value', '')), '') AS component_key_value,
        stored_component.payload_json,
        stored_component.bucket_json,
        UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'classification', ''))) AS classification,
        UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'source_pay_method', ''))) AS source_pay_method,
        UPPER(BTRIM(COALESCE(
          stored_component.bucket_json->>'target_pay_method',
          stored_component.bucket_json->>'current_target_pay_method',
          stored_component.payload_json->>'target_pay_method',
          stored_component.payload_json->>'current_target_pay_method',
          ''
        ))) AS target_pay_method,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'source_units', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round((stored_component.bucket_json->>'source_units')::numeric, 6)
          ELSE NULL::numeric
        END AS source_units,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'source_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round((stored_component.bucket_json->>'source_rate')::numeric, 6)
          ELSE NULL::numeric
        END AS source_rate,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'source_charge_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round((stored_component.bucket_json->>'source_charge_rate')::numeric, 6)
          ELSE NULL::numeric
        END AS source_charge_rate,
        UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'resolution_mode', stored_component.payload_json->>'resolution_mode', ''))) AS resolution_mode,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'target_rate', stored_component.payload_json->>'target_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round(COALESCE(stored_component.bucket_json->>'target_rate', stored_component.payload_json->>'target_rate')::numeric, 2)
          ELSE NULL::numeric
        END AS target_rate,
        stored_component.updated_at_utc,
        stored_component.bucket_ordinal
      FROM stored_resolution_components AS stored_component
    ) AS resolved_component
    WHERE resolved_component.finance_case_id IS NOT NULL
      AND resolved_component.source_basis_fingerprint IS NOT NULL
      AND resolved_component.source_family_key IS NOT NULL
      AND resolved_component.component_key_type IS NOT NULL
      AND resolved_component.component_key_value IS NOT NULL
      AND resolved_component.resolution_mode IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_REPLACEMENT_RATE')
      AND resolved_component.target_rate IS NOT NULL
      AND resolved_component.target_rate >= 0
    ORDER BY
      resolved_component.finance_case_id,
      resolved_component.source_basis_fingerprint,
      resolved_component.source_family_key,
      COALESCE(resolved_component.bucket_code, ''),
      resolved_component.component_key_type,
      resolved_component.component_key_value,
      resolved_component.updated_at_utc DESC,
      resolved_component.resolution_id DESC,
      resolved_component.bucket_ordinal DESC;

    UPDATE finance_case_component_review_rows_effective AS effective_component
    SET approved_resolution_mode = resolution_overlay.resolution_mode,
        approved_target_rate = resolution_overlay.target_rate,
        saved_target_pay_method = COALESCE(NULLIF(resolution_overlay.target_pay_method, ''), effective_component.current_target_pay_method),
        saved_resolution_mode = resolution_overlay.resolution_mode::public.pay_finance_component_resolution_mode_enum,
        saved_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'BUCKETED',
            'resolution_mode', resolution_overlay.resolution_mode,
            'target_pay_method', COALESCE(NULLIF(resolution_overlay.target_pay_method, ''), effective_component.current_target_pay_method),
            'target_units', round(effective_component.source_units, 6),
            'target_rate', round(resolution_overlay.target_rate, 2)
          )
        ),
        saved_resolution_result_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.bucket_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_units', round(effective_component.source_units, 6),
            'target_rate', round(resolution_overlay.target_rate, 2),
            'target_amount_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_pay_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
              ELSE round(
                (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
                - effective_component.source_margin_ex_vat,
                2
              )
            END
          )
        ),
        resolution_fingerprint = effective_component.current_component_fingerprint,
        is_resolution_stale = false,
        stale_reason = NULL,
        requires_resolution = false,
        case_resolution_satisfied_now_component = true,
        suggestion_provenance = 'PREVIEW_CASE_RESOLUTION',
        is_fresh_suggested_resolution = false,
        is_reusable_saved_resolution = true,
        is_stale_saved_resolution = false,
        suggested_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'BUCKETED',
            'resolution_mode', resolution_overlay.resolution_mode,
            'target_pay_method', COALESCE(NULLIF(resolution_overlay.target_pay_method, ''), effective_component.current_target_pay_method),
            'target_units', round(effective_component.source_units, 6),
            'target_rate', round(resolution_overlay.target_rate, 2)
          )
        ),
        suggested_resolution_result_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.bucket_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_units', round(effective_component.source_units, 6),
            'replacement_rate', round(resolution_overlay.target_rate, 2),
            'target_rate', round(resolution_overlay.target_rate, 2),
            'target_amount_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_pay_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
              ELSE round(
                (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
                - effective_component.source_margin_ex_vat,
                2
              )
            END
          )
        ),
        target_pay_ex_vat = round(effective_component.source_units * resolution_overlay.target_rate, 2),
        target_charge_ex_vat = effective_component.source_charge_component_ex_vat,
        target_margin_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
          ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
        END,
        margin_delta_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
          ELSE round(
            (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
            - effective_component.source_margin_ex_vat,
            2
          )
        END,
        suggestion_explanation_text = 'This component uses the current Workbench Case Resolution selected for this finance case.'
    FROM finance_case_bucket_resolution_overlay AS resolution_overlay
    WHERE effective_component.candidate_id = v_candidate_id
      AND effective_component.finance_case_id = resolution_overlay.finance_case_id
      AND resolution_overlay.case_key = ('finance:' || effective_component.finance_case_id::text)
      AND effective_component.source_family_key = resolution_overlay.source_family_key
      AND md5(COALESCE(effective_component.source_basis_json::text, '{}'::text)) = resolution_overlay.source_basis_fingerprint
      AND COALESCE(NULLIF(UPPER(BTRIM(COALESCE(effective_component.source_basis_json->>'bucket_code', ''))), ''), '') = COALESCE(resolution_overlay.bucket_code, '')
      AND effective_component.component_key_type = resolution_overlay.component_key_type
      AND effective_component.component_key_value = resolution_overlay.component_key_value
      AND round(effective_component.source_units, 6) = resolution_overlay.source_units
      AND round(effective_component.source_rate, 6) = resolution_overlay.source_rate
      AND round(effective_component.source_charge_rate, 6) = resolution_overlay.source_charge_rate
      AND (resolution_overlay.classification = '' OR UPPER(effective_component.classification::text) = resolution_overlay.classification)
      AND (resolution_overlay.source_pay_method = '' OR UPPER(BTRIM(COALESCE(effective_component.source_pay_method, ''))) = resolution_overlay.source_pay_method)
      AND (resolution_overlay.target_pay_method = '' OR UPPER(BTRIM(COALESCE(effective_component.current_target_pay_method, ''))) = resolution_overlay.target_pay_method)
      AND effective_component.is_actionable_resolution_row = true;

    CREATE TEMPORARY TABLE finance_case_nonbucket_resolution_overlay ON COMMIT DROP AS
    SELECT DISTINCT ON (resolved_nonbucket.finance_case_id)
      resolved_nonbucket.resolution_id,
      resolved_nonbucket.finance_case_id,
      resolved_nonbucket.case_key,
      resolved_nonbucket.payload_json,
      resolved_nonbucket.resolution_mode,
      resolved_nonbucket.target_amount_ex_vat
    FROM (
      SELECT
        stored_resolution.id AS resolution_id,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(stored_resolution.payload_json->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(stored_resolution.payload_json->>'finance_case_id', '')), '')::uuid
          WHEN NULLIF(BTRIM(COALESCE(stored_resolution.case_key, '')), '') ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN substring(NULLIF(BTRIM(COALESCE(stored_resolution.case_key, '')), '') from 9)::uuid
          ELSE NULL::uuid
        END AS finance_case_id,
        stored_resolution.case_key,
        stored_resolution.payload_json,
        UPPER(BTRIM(COALESCE(stored_resolution.payload_json->>'resolution_mode', ''))) AS resolution_mode,
        CASE
          WHEN COALESCE(stored_resolution.payload_json->>'target_amount_ex_vat', stored_resolution.payload_json->>'target_amount', stored_resolution.payload_json->>'amount_ex_vat', stored_resolution.payload_json->>'amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round(COALESCE(stored_resolution.payload_json->>'target_amount_ex_vat', stored_resolution.payload_json->>'target_amount', stored_resolution.payload_json->>'amount_ex_vat', stored_resolution.payload_json->>'amount')::numeric, 2)
          ELSE NULL::numeric
        END AS target_amount_ex_vat,
        stored_resolution.updated_at_utc
      FROM public.banking_pay_workbench_session_case_resolutions AS stored_resolution
      WHERE stored_resolution.session_id = v_workbench_resolution_session_id
        AND stored_resolution.candidate_id = v_candidate_id
        AND UPPER(BTRIM(COALESCE(stored_resolution.resolution_family, ''))) = 'NON_BUCKET'
    ) AS resolved_nonbucket
    WHERE resolved_nonbucket.finance_case_id IS NOT NULL
      AND resolved_nonbucket.resolution_mode IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_AMOUNT')
      AND resolved_nonbucket.target_amount_ex_vat IS NOT NULL
      AND resolved_nonbucket.target_amount_ex_vat >= 0
    ORDER BY
      resolved_nonbucket.finance_case_id,
      resolved_nonbucket.updated_at_utc DESC,
      resolved_nonbucket.resolution_id DESC;

    CREATE TEMPORARY TABLE finance_case_nonbucket_resolution_overlay_alloc ON COMMIT DROP AS
    WITH target_components AS (
      SELECT
        effective_component.ctid AS row_ctid,
        effective_component.finance_case_id,
        effective_component.finance_component_id,
        resolution_overlay.resolution_id,
        resolution_overlay.payload_json,
        resolution_overlay.resolution_mode,
        resolution_overlay.target_amount_ex_vat,
        round(coalesce(effective_component.remaining_source_amount, 0), 2) AS remaining_source_amount,
        round(sum(coalesce(effective_component.remaining_source_amount, 0)) OVER (PARTITION BY effective_component.finance_case_id), 2) AS total_remaining_source_amount,
        row_number() OVER (PARTITION BY effective_component.finance_case_id ORDER BY effective_component.finance_component_id) AS component_ord,
        count(*) OVER (PARTITION BY effective_component.finance_case_id) AS component_count
      FROM finance_case_component_review_rows_effective AS effective_component
      JOIN finance_case_nonbucket_resolution_overlay AS resolution_overlay
        ON resolution_overlay.finance_case_id = effective_component.finance_case_id
       AND resolution_overlay.case_key = ('finance:' || effective_component.finance_case_id::text)
      WHERE effective_component.candidate_id = v_candidate_id
        AND effective_component.case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
        AND effective_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        AND round(coalesce(effective_component.remaining_source_amount, 0), 2) > 0
    ), preliminary_components AS (
      SELECT
        target_components.*,
        round(
          CASE
            WHEN coalesce(target_components.target_amount_ex_vat, 0) = 0 THEN 0::numeric
            WHEN coalesce(target_components.total_remaining_source_amount, 0) = 0 THEN 0::numeric
            WHEN target_components.component_count = 1 THEN target_components.target_amount_ex_vat
            WHEN target_components.component_ord < target_components.component_count THEN target_components.target_amount_ex_vat * target_components.remaining_source_amount / nullif(target_components.total_remaining_source_amount, 0)
            ELSE 0::numeric
          END,
          2
        ) AS preliminary_target_amount_ex_vat
      FROM target_components
    )
    SELECT
      preliminary_components.row_ctid,
      preliminary_components.finance_case_id,
      preliminary_components.finance_component_id,
      preliminary_components.resolution_id,
      preliminary_components.payload_json,
      preliminary_components.resolution_mode,
      round(
        CASE
          WHEN preliminary_components.component_count = 1 THEN preliminary_components.target_amount_ex_vat
          WHEN preliminary_components.component_ord < preliminary_components.component_count THEN preliminary_components.preliminary_target_amount_ex_vat
          ELSE preliminary_components.target_amount_ex_vat - coalesce(
            sum(preliminary_components.preliminary_target_amount_ex_vat) OVER (
              PARTITION BY preliminary_components.finance_case_id
              ORDER BY preliminary_components.component_ord
              ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
            ),
            0
          )
        END,
        2
      ) AS allocated_target_amount_ex_vat
    FROM preliminary_components;

    UPDATE finance_case_component_review_rows_effective AS effective_component
    SET approved_nonbucket_resolution_mode = nonbucket_overlay.resolution_mode,
        approved_nonbucket_target_amount_ex_vat = nonbucket_overlay.allocated_target_amount_ex_vat,
        saved_target_pay_method = effective_component.current_target_pay_method,
        saved_resolution_mode = nonbucket_overlay.resolution_mode::public.pay_finance_component_resolution_mode_enum,
        saved_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'NON_BUCKET',
            'resolution_mode', nonbucket_overlay.resolution_mode,
            'target_pay_method', effective_component.current_target_pay_method,
            'applied_basis_source_amount_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2)
          )
        ),
        saved_resolution_result_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_pay_method', effective_component.current_target_pay_method,
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'target_pay_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'source_pay_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'source_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2) - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END
          )
        ),
        resolution_fingerprint = effective_component.current_component_fingerprint,
        is_resolution_stale = false,
        stale_reason = NULL,
        requires_resolution = false,
        case_resolution_satisfied_now_component = true,
        suggestion_provenance = 'PREVIEW_CASE_RESOLUTION',
        is_fresh_suggested_resolution = false,
        is_reusable_saved_resolution = true,
        is_stale_saved_resolution = false,
        suggested_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'NON_BUCKET',
            'resolution_mode', nonbucket_overlay.resolution_mode,
            'target_pay_method', effective_component.current_target_pay_method,
            'applied_basis_source_amount_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2)
          )
        ),
        suggested_resolution_result_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_pay_method', effective_component.current_target_pay_method,
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'target_pay_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'source_pay_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'source_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2) - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END
          )
        ),
        target_pay_ex_vat = round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
        target_charge_ex_vat = effective_component.source_charge_component_ex_vat,
        target_margin_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
          ELSE round(effective_component.source_charge_component_ex_vat - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
        END,
        margin_delta_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
          ELSE round(round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2) - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
        END,
        suggestion_explanation_text = 'This finance case uses the current Workbench non-bucket Case Resolution selected for this session.'
    FROM finance_case_nonbucket_resolution_overlay_alloc AS nonbucket_overlay
    WHERE effective_component.ctid = nonbucket_overlay.row_ctid;
  END IF;

  create temporary table finance_case_due_source_amounts on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          round(
            greatest(
              case
                when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then coalesce(
                  fcpa.protected_recoverable_amount,
                  least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                  - coalesce(fcrw.repaid_wtd_ex,0)
                  - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                )
                when vfcr.case_type = 'PAYMENT_ADVANCE' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else coalesce(vfcr.original_amount,0) - coalesce(vfcr.active_reserved_amount,0)
                end
                when vfcr.case_type = 'UNDERPAYMENT' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else greatest(coalesce(vfcr.outstanding_amount, vfcr.original_amount, 0) - coalesce(vfcr.active_reserved_amount,0), 0)
                end
                when vfcr.case_type = 'OVERPAYMENT' then coalesce(
                  fcpa.protected_recoverable_amount,
                  greatest(coalesce(vfcr.outstanding_amount,0) - coalesce(vfcr.active_reserved_amount,0), 0)
                )
                when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then coalesce(
                  fcpa.protected_recoverable_amount,
                  least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                  - coalesce(fcrw.repaid_wtd_ex,0)
                  - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                )
                when vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else coalesce(vfcr.original_amount,0) - coalesce(vfcr.active_reserved_amount,0)
                end
                else 0::numeric
              end,
              0::numeric
            ),
            2
          ) as due_source_amount_ex_vat
        from finance_case_baseline_scope vfcr
        left join finance_case_repaid_wtd fcrw
          on fcrw.finance_case_id = vfcr.finance_case_id
        left join finance_case_protected_allocations fcpa
          on fcpa.finance_case_id = vfcr.finance_case_id
        where vfcr.finance_case_id is not null

  ;

  create temporary table finance_case_component_due_source_base on commit drop as
        select
          fce.finance_case_id,
          fce.candidate_id,
          fce.case_type,
          fce.taxability,
          fce.finance_component_id,
          round(coalesce(fce.remaining_source_amount,0),2) as remaining_source_amount,
          round(coalesce(fcds.due_source_amount_ex_vat,0),2) as due_source_amount_ex_vat,
          round(sum(coalesce(fce.remaining_source_amount,0)) over (partition by fce.finance_case_id),2) as total_remaining_source_amount,
          row_number() over (partition by fce.finance_case_id order by fce.finance_component_id) as component_ord,
          count(*) over (partition by fce.finance_case_id) as component_count
        from finance_case_component_review_rows_effective fce
        join finance_case_due_source_amounts fcds
          on fcds.finance_case_id = fce.finance_case_id

  ;

  create temporary table finance_case_component_due_source_shares on commit drop as
        select
          fcdsb.*,
          round(
            case
              when coalesce(fcdsb.due_source_amount_ex_vat,0) = 0 then 0::numeric
              when coalesce(fcdsb.total_remaining_source_amount,0) = 0 then 0::numeric
              when fcdsb.component_count = 1 then fcdsb.due_source_amount_ex_vat
              when fcdsb.component_ord < fcdsb.component_count then (fcdsb.due_source_amount_ex_vat * fcdsb.remaining_source_amount / nullif(fcdsb.total_remaining_source_amount,0))
              else 0::numeric
            end,
            2
          ) as preliminary_source_due_amount_ex_vat
        from finance_case_component_due_source_base fcdsb

  ;

  create temporary table finance_case_component_due_source_allocations on commit drop as
        select
          fcdss.finance_case_id,
          fcdss.finance_component_id,
          round(
            case
              when fcdss.component_count = 1 then fcdss.due_source_amount_ex_vat
              when fcdss.component_ord < fcdss.component_count then fcdss.preliminary_source_due_amount_ex_vat
              else fcdss.due_source_amount_ex_vat - coalesce(sum(fcdss.preliminary_source_due_amount_ex_vat) over (partition by fcdss.finance_case_id order by fcdss.component_ord rows between unbounded preceding and 1 preceding), 0)
            end,
            2
          ) as allocated_source_due_amount_ex_vat
        from finance_case_component_due_source_shares fcdss

  ;

  create temporary table finance_case_component_due_preview_base on commit drop as
        select
          fce.finance_case_id,
          fce.finance_component_id,
          fcda.allocated_source_due_amount_ex_vat,
          row_number() over (partition by fce.finance_case_id order by fce.finance_component_id) as component_ord,
          count(*) over (partition by fce.finance_case_id) as component_count,
          round(
            case
              when coalesce(fcda.allocated_source_due_amount_ex_vat,0) = 0 then 0::numeric
              when fce.case_type = 'MANUAL_DEBT_ADJUSTMENT' and coalesce(fce.approved_nonbucket_target_amount_ex_vat,0) <> 0 and round(coalesce(fce.remaining_source_amount,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              when fce.case_type = 'OVERPAYMENT' and round(coalesce(fce.remaining_source_amount,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              when round(coalesce(fce.remaining_source_amount,0),2) <> 0 and round(coalesce(fce.target_pay_ex_vat,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              else fcda.allocated_source_due_amount_ex_vat
            end,
            2
          ) as preliminary_preview_due_amount_ex_vat
        from finance_case_component_review_rows_effective fce
        join finance_case_component_due_source_allocations fcda
          on fcda.finance_case_id = fce.finance_case_id
         and fcda.finance_component_id = fce.finance_component_id

  ;

  create temporary table finance_case_component_due_preview_allocations on commit drop as
        select
          fcdpb.finance_case_id,
          fcdpb.finance_component_id,
          round(fcdpb.preliminary_preview_due_amount_ex_vat, 2) as allocated_preview_due_amount_ex_vat
        from finance_case_component_due_preview_base fcdpb

  ;

  create temporary table finance_case_taxable_channel_restructure_resolution on commit drop as
        with component_base as (
          select
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.candidate_id,
            vfcr.client_id,
            vfcr.next_due_week_start,
            vfcr.weekly_due,
            vfcr.weeks_total,
            vfcr.outstanding_amount,
            vfcr.schedule_json,
            cp.cand_pay_method as target_pay_method,
            fccr.finance_component_id,
            fccr.source_family_key,
            fccr.component_key_type,
            fccr.component_key_value,
            fccr.classification,
            fccr.source_pay_method,
            fccr.current_target_pay_method,
            fccr.umb_vat_chargeable,
            fccr.source_basis_json,
            fccr.source_amount,
            fccr.remaining_source_amount,
            fccr.source_units,
            fccr.source_rate,
            fccr.source_charge_rate,
            fccr.source_charge_ex_vat,
            fccr.saved_target_pay_method,
            fccr.saved_resolution_mode,
            fccr.saved_resolution_payload_json,
            fccr.saved_resolution_result_json,
            fccr.resolution_fingerprint,
            fccr.current_component_fingerprint,
            fccr.is_stale_saved_resolution,
            fccr.is_reusable_saved_resolution,
            fccr.stale_reason,
            (
              fccr.finance_component_id is not null
              and fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and upper(coalesce(fccr.source_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.current_target_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.source_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
              and round(coalesce(fccr.remaining_source_amount,0),2) > 0
            ) as has_taxable_channel_mismatch,
            (
              fccr.finance_component_id is not null
              and fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and upper(coalesce(fccr.source_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.current_target_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.source_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
              and round(coalesce(fccr.remaining_source_amount,0),2) > 0
              and (
                coalesce(fccr.is_stale_saved_resolution,false) = true
                or nullif(btrim(coalesce(fccr.saved_target_pay_method,'')), '') is null
                or upper(coalesce(fccr.saved_target_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
                or (
                  fccr.resolution_fingerprint is not null
                  and fccr.current_component_fingerprint is not null
                  and fccr.resolution_fingerprint is distinct from fccr.current_component_fingerprint
                )
              )
            ) as requires_component_restructure
          from finance_case_baseline_scope vfcr
          join cand_payee cp
            on cp.candidate_id = vfcr.candidate_id
          join finance_case_component_review_rows_effective fccr
            on fccr.finance_case_id = vfcr.finance_case_id
          where vfcr.case_type in (
            'OVERPAYMENT'::public.pay_finance_case_type_enum,
            'UNDERPAYMENT'::public.pay_finance_case_type_enum,
            'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
            'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
          )
            and fccr.finance_component_id is not null
            and round(coalesce(fccr.remaining_source_amount,0),2) > 0
        ),
        component_projected as (
          select
            cb.*,
            round(
              case
                when cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                 and cb.source_pay_method = 'UMBRELLA'
                 and cb.current_target_pay_method = 'PAYE'
                  then public._pay_convert_umbrella_to_paye_ex(round(coalesce(cb.remaining_source_amount,0),2), v_erni_pct)
                when cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                 and cb.source_pay_method = 'PAYE'
                 and cb.current_target_pay_method = 'UMBRELLA'
                  then coalesce((public._pay_convert_paye_to_umbrella(round(coalesce(cb.remaining_source_amount,0),2), v_erni_pct, v_vat_rate_pct, coalesce(cb.umb_vat_chargeable,false))->>'ex')::numeric, 0)
                else round(coalesce(cb.remaining_source_amount,0),2)
              end,
              2
            ) as target_remaining_ex
          from component_base cb
        ),
        component_projected_vat as (
          select
            cpj.*,
            round(
              case
                when cpj.current_target_pay_method = 'UMBRELLA'
                  then coalesce((public._pay_umbrella_vat_calc(round(coalesce(cpj.target_remaining_ex,0),2), v_vat_rate_pct, coalesce(cpj.umb_vat_chargeable,false))->>'vat')::numeric, 0)
                else 0
              end,
              2
            ) as target_remaining_vat,
            round(
              coalesce(cpj.target_remaining_ex,0)
              + case
                  when cpj.current_target_pay_method = 'UMBRELLA'
                    then coalesce((public._pay_umbrella_vat_calc(round(coalesce(cpj.target_remaining_ex,0),2), v_vat_rate_pct, coalesce(cpj.umb_vat_chargeable,false))->>'vat')::numeric, 0)
                  else 0
                end,
              2
            ) as target_remaining_inc
          from component_projected cpj
        ),
        case_shape as (
          select
            cpv.finance_case_id,
            (array_agg(cpv.case_type))[1] as case_type,
            (array_remove(array_agg(cpv.candidate_id), null::uuid))[1] as candidate_id,
            (array_remove(array_agg(cpv.client_id), null::uuid))[1] as client_id,
            max(cpv.next_due_week_start) as next_due_week_start,
            max(cpv.weekly_due) as weekly_due,
            max(cpv.weeks_total) as weeks_total,
            max(cpv.outstanding_amount) as outstanding_amount,
            coalesce((jsonb_agg(cpv.schedule_json order by cpv.finance_component_id) filter (where cpv.schedule_json is not null))->0, '[]'::jsonb) as schedule_json,
            max(cpv.target_pay_method) as target_pay_method,
            count(*)::int as open_component_count,
            count(*) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum)::int as open_taxable_count,
            count(*) filter (where cpv.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum))::int as open_fixed_count,
            bool_or(cpv.has_taxable_channel_mismatch) as has_taxable_channel_mismatch,
            bool_or(cpv.requires_component_restructure) as requires_restructure,
            bool_or(coalesce(cpv.is_reusable_saved_resolution,false)) as is_reusable_saved_resolution,
            bool_or(coalesce(cpv.is_stale_saved_resolution,false)) as is_stale_saved_resolution,
            round(coalesce(sum(cpv.remaining_source_amount),0),2) as existing_source_total_ex,
            round(coalesce(sum(cpv.remaining_source_amount) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum),0),2) as existing_taxable_source_total_ex,
            round(coalesce(sum(cpv.target_remaining_ex),0),2) as suggested_target_total_ex,
            round(coalesce(sum(cpv.target_remaining_vat),0),2) as suggested_target_total_vat,
            round(coalesce(sum(cpv.target_remaining_inc),0),2) as suggested_target_total_inc,
            round(coalesce(sum(cpv.target_remaining_ex) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum),0),2) as suggested_taxable_target_total_ex,
            bool_or(coalesce(cpv.umb_vat_chargeable,false)) as umbrella_vat_chargeable,
            coalesce(
              jsonb_agg(
                jsonb_strip_nulls(jsonb_build_object(
                  'finance_component_id', cpv.finance_component_id::text,
                  'source_family_key', cpv.source_family_key,
                  'component_key_type', cpv.component_key_type,
                  'component_key_value', cpv.component_key_value,
                  'classification', cpv.classification::text,
                  'source_pay_method', cpv.source_pay_method,
                  'target_pay_method', cpv.current_target_pay_method,
                  'source_remaining_amount_ex_vat', round(coalesce(cpv.remaining_source_amount,0),2),
                  'target_remaining_amount_ex_vat', round(coalesce(cpv.target_remaining_ex,0),2),
                  'target_remaining_amount_vat', round(coalesce(cpv.target_remaining_vat,0),2),
                  'target_remaining_amount_inc_vat', round(coalesce(cpv.target_remaining_inc,0),2),
                  'requires_component_conversion', cpv.has_taxable_channel_mismatch,
                  'requires_restructure', cpv.requires_component_restructure,
                  'source_units', cpv.source_units,
                  'source_rate', cpv.source_rate,
                  'source_charge_rate', cpv.source_charge_rate,
                  'source_charge_ex_vat', cpv.source_charge_ex_vat,
                  'saved_target_pay_method', cpv.saved_target_pay_method,
                  'saved_resolution_mode', case when cpv.saved_resolution_mode is null then null else cpv.saved_resolution_mode::text end,
                  'is_reusable_saved_resolution', cpv.is_reusable_saved_resolution,
                  'is_stale_saved_resolution', cpv.is_stale_saved_resolution,
                  'stale_reason', cpv.stale_reason
                ))
                order by cpv.classification::text, cpv.component_key_type, cpv.component_key_value, cpv.finance_component_id
              ),
              '[]'::jsonb
            ) as component_breakdown_json
          from component_projected_vat cpv
          group by cpv.finance_case_id
        ),
        case_with_schedule as (
          select
            cs.*,
            coalesce(cs.next_due_week_start, v_week_start) as restructure_start_week_start,
            coalesce(
              (
                select count(*)::integer
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched(schedule_entry)
                where jsonb_typeof(sched.schedule_entry) = 'object'
                  and coalesce(sched.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched.schedule_entry->>'amount')::numeric) > 0
              ),
              case
                when coalesce(cs.weekly_due,0) > 0 and coalesce(cs.existing_source_total_ex,0) > 0 then greatest(ceil(cs.existing_source_total_ex / cs.weekly_due)::integer, 1)
                when coalesce(cs.weeks_total,0) > 0 then cs.weeks_total
                else 1
              end
            ) as existing_weeks_remaining,
            coalesce(
              nullif(round(coalesce(cs.weekly_due,0),2),0),
              (
                select round(abs((sched2.schedule_entry->>'amount')::numeric),2)
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched2(schedule_entry)
                where jsonb_typeof(sched2.schedule_entry) = 'object'
                  and coalesce(sched2.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched2.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched2.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched2.schedule_entry->>'amount')::numeric) > 0
                order by (sched2.schedule_entry->>'week_start')::date asc
                limit 1
              ),
              round(ceil((cs.existing_source_total_ex / greatest(coalesce(cs.weeks_total,1),1)) * 100) / 100, 2)
            ) as existing_weekly_due,
            coalesce(
              (
                select round(abs((sched3.schedule_entry->>'amount')::numeric),2)
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched3(schedule_entry)
                where jsonb_typeof(sched3.schedule_entry) = 'object'
                  and coalesce(sched3.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched3.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched3.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched3.schedule_entry->>'amount')::numeric) > 0
                order by (sched3.schedule_entry->>'week_start')::date desc
                limit 1
              ),
              0::numeric
            ) as existing_final_week_amount
          from case_shape cs
        ),
        open_batch as (
          select
            cws.finance_case_id,
            exists (
              select 1
              from public.pay_batch_items pbi_open
              join public.pay_batch_candidates pbc_open
                on pbc_open.id = pbi_open.pay_batch_candidate_id
              join public.pay_batches pb_open
                on pb_open.id = pbc_open.pay_batch_id
              where coalesce(pbi_open.is_voided,false) = false
                and pb_open.cancelled_at_utc is null
                and upper(coalesce(pb_open.status::text,'')) not in ('CANCELLED','COMPLETED','SETTLED')
                and (
                  pbi_open.finance_case_id = cws.finance_case_id
                  or exists (
                    select 1
                    from public.pay_finance_case_components pfc_open
                    where pfc_open.finance_case_id = cws.finance_case_id
                      and pfc_open.closed_at_utc is null
                      and pfc_open.id = pbi_open.finance_component_id
                  )
                )
            ) as has_open_batch_item
          from case_with_schedule cws
        )
        select
          cws.finance_case_id,
          coalesce(cws.requires_restructure,false) as has_dedicated_resolution_payload,
          coalesce(cws.requires_restructure,false) as use_dedicated_blocker,
          case
            when coalesce(cws.requires_restructure,false) = true then jsonb_strip_nulls(jsonb_build_object(
              'resolution_kind', 'TAXABLE_CHANNEL_RESTRUCTURE',
              'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
              'resolution_action_label', 'Suggested Restructure',
              'modal_title', 'Finance Restructure',
              'finance_case_id', cws.finance_case_id::text,
              'case_type', cws.case_type::text,
              'source_method', (
                select coalesce(jsonb_agg(distinct cb.source_pay_method), '[]'::jsonb)
                from component_base cb
                where cb.finance_case_id = cws.finance_case_id
                  and cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              ),
              'target_method', cws.target_pay_method,
              'can_apply', coalesce(ob.has_open_batch_item,false) = false,
              'open_batch_blocked_reason', case when coalesce(ob.has_open_batch_item,false) = true then 'CASE_ALREADY_IN_OPEN_BATCH' else null end,
              'existing_arrangement', jsonb_build_object(
                'source_remaining_balance_ex_vat', cws.existing_source_total_ex,
                'taxable_source_remaining_balance_ex_vat', cws.existing_taxable_source_total_ex,
                'weekly_due', round(coalesce(cws.existing_weekly_due,0),2),
                'weeks_remaining', greatest(coalesce(cws.existing_weeks_remaining,1),1),
                'final_week_amount', case
                  when coalesce(cws.existing_final_week_amount,0) > 0 then round(cws.existing_final_week_amount,2)
                  else round(least(round(coalesce(cws.existing_weekly_due,0),2), greatest(cws.existing_source_total_ex - (round(coalesce(cws.existing_weekly_due,0),2) * greatest(coalesce(cws.existing_weeks_remaining,1) - 1,0)),0)),2)
                end,
                'start_week_start', cws.restructure_start_week_start::text,
                'schedule_json', coalesce(cws.schedule_json,'[]'::jsonb)
              ),
              'suggested_arrangement', jsonb_build_object(
                'target_remaining_balance_ex_vat', cws.suggested_target_total_ex,
                'target_remaining_balance_vat', cws.suggested_target_total_vat,
                'target_remaining_balance_inc_vat', cws.suggested_target_total_inc,
                'taxable_target_remaining_balance_ex_vat', cws.suggested_taxable_target_total_ex,
                'weekly_due', round(
                  greatest(
                    round(coalesce(cws.existing_weekly_due,0),2)
                    * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end,
                    0.01
                  ),
                  2
                ),
                'weeks_remaining', greatest(coalesce(cws.existing_weeks_remaining,1),1),
                'final_week_amount', round(
                  least(
                    greatest(round(coalesce(cws.existing_weekly_due,0),2) * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end, 0.01),
                    greatest(
                      cws.suggested_target_total_ex
                      - (round(greatest(round(coalesce(cws.existing_weekly_due,0),2) * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end, 0.01),2) * greatest(coalesce(cws.existing_weeks_remaining,1) - 1,0)),
                      0
                    )
                  ),
                  2
                ),
                'erni_rate_pct', round(v_erni_pct,6),
                'erni_component_ex_vat', round(abs(cws.existing_taxable_source_total_ex - cws.suggested_taxable_target_total_ex),2),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'vat_amount', cws.suggested_target_total_vat,
                'umbrella_vat_chargeable', coalesce(cws.umbrella_vat_chargeable,false)
              ),
              'component_breakdown', cws.component_breakdown_json,
              'suggestion_explanation_text', 'This taxable finance case must be durably restructured onto the current pay method before it can move to Ready to Pay.'
            ))
            else null::jsonb
          end as taxable_channel_restructure_resolution_json
        from case_with_schedule cws
        left join open_batch ob
          on ob.finance_case_id = cws.finance_case_id

  ;

  /*
   * Cancellation ownership is deliberately independent from the blocker that
   * an applied resolution has satisfied.  A finance line is clearable only
   * when one exact, current, server-owned resolution can be proved.  This is
   * pre-Draft live authority; frozen Draft and downstream artefacts are not
   * consulted or rewritten here (Policy X).
   */
  create temporary table finance_case_resolution_owner_state on commit drop as
  with taxable_owner_rows as (
    select
      component_row.finance_case_id,
      component_row.finance_component_id,
      component_row.classification,
      component_row.saved_target_pay_method,
      component_row.saved_resolution_mode,
      component_row.saved_resolution_payload_json,
      component_row.saved_resolution_result_json,
      component_row.resolution_fingerprint,
      component_row.is_resolution_stale,
      component_row.current_target_pay_method,
      component_row.current_component_fingerprint,
      (
        component_row.saved_target_pay_method is not null
        or component_row.saved_resolution_mode is not null
        or component_row.saved_resolution_payload_json is not null
        or component_row.saved_resolution_result_json is not null
        or nullif(btrim(coalesce(component_row.resolution_fingerprint, '')), '') is not null
        or coalesce(component_row.is_resolution_stale, false) = true
      ) as has_saved_evidence,
      (
        component_row.saved_resolution_mode is not null
        and jsonb_typeof(component_row.saved_resolution_payload_json) = 'object'
        and jsonb_typeof(component_row.saved_resolution_result_json) = 'object'
        and (
          case upper(btrim(coalesce(component_row.saved_resolution_payload_json->>'resolution_family', '')))
            when 'TAXABLE_CHANNEL' then 'TAXABLE_CHANNEL_RESTRUCTURE'
            else upper(btrim(coalesce(component_row.saved_resolution_payload_json->>'resolution_family', '')))
          end
        ) = 'TAXABLE_CHANNEL_RESTRUCTURE'
        and (
          case upper(btrim(coalesce(component_row.saved_resolution_result_json->>'resolution_family', '')))
            when 'TAXABLE_CHANNEL' then 'TAXABLE_CHANNEL_RESTRUCTURE'
            else upper(btrim(coalesce(component_row.saved_resolution_result_json->>'resolution_family', '')))
          end
        ) = 'TAXABLE_CHANNEL_RESTRUCTURE'
        and coalesce(component_row.is_resolution_stale, false) = false
        and nullif(btrim(coalesce(component_row.saved_target_pay_method, '')), '') is not null
        and upper(btrim(component_row.saved_target_pay_method)) = upper(btrim(coalesce(component_row.current_target_pay_method, '')))
        and nullif(btrim(coalesce(component_row.resolution_fingerprint, '')), '') is not null
        and component_row.resolution_fingerprint is not distinct from component_row.current_component_fingerprint
      ) as is_current_taxable_owner_component
    from finance_case_component_review_rows as component_row
    where component_row.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and round(coalesce(component_row.remaining_source_amount, 0), 2) > 0
  ), taxable_owner_state as (
    select
      taxable_row.finance_case_id,
      count(*)::integer as taxable_component_count,
      count(*) filter (where taxable_row.is_current_taxable_owner_component)::integer as current_taxable_component_count,
      count(*) filter (where taxable_row.has_saved_evidence)::integer as taxable_saved_evidence_count
    from taxable_owner_rows as taxable_row
    group by taxable_row.finance_case_id
  ), nonbucket_owner_rows as (
    select
      stored_resolution.id as resolution_id,
      case
        when stored_resolution.case_key ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then substring(stored_resolution.case_key from 9)::uuid
        else null::uuid
      end as finance_case_id,
      stored_resolution.case_key,
      stored_resolution.timesheet_id,
      stored_resolution.payload_json,
      linked_identity.linked_timesheet_id,
      (
        jsonb_typeof(stored_resolution.payload_json) = 'object'
        and stored_resolution.case_key ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        and upper(btrim(coalesce(stored_resolution.resolution_family, ''))) = 'NON_BUCKET'
        and upper(btrim(coalesce(stored_resolution.payload_json->>'resolution_mode', ''))) in ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_AMOUNT')
        and coalesce(
          stored_resolution.payload_json->>'target_amount_ex_vat',
          stored_resolution.payload_json->>'target_amount',
          stored_resolution.payload_json->>'amount_ex_vat',
          stored_resolution.payload_json->>'amount',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
        and case
          when coalesce(
            stored_resolution.payload_json->>'target_amount_ex_vat',
            stored_resolution.payload_json->>'target_amount',
            stored_resolution.payload_json->>'amount_ex_vat',
            stored_resolution.payload_json->>'amount',
            ''
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          then coalesce(
            stored_resolution.payload_json->>'target_amount_ex_vat',
            stored_resolution.payload_json->>'target_amount',
            stored_resolution.payload_json->>'amount_ex_vat',
            stored_resolution.payload_json->>'amount'
          )::numeric >= 0
          else false
        end
        and (
          nullif(btrim(coalesce(stored_resolution.payload_json->>'finance_case_id', '')), '') is null
          or btrim(stored_resolution.payload_json->>'finance_case_id') = substring(stored_resolution.case_key from 9)
        )
        and linked_identity.identity_is_valid
      ) as is_valid_nonbucket_owner
    from public.banking_pay_workbench_session_case_resolutions as stored_resolution
    left join lateral (
      select
        case
          when count(distinct identity_value) <= 1
            and count(*) filter (where identity_value is null and raw_value <> '') = 0
          then min(identity_value)::uuid
          else null::uuid
        end as linked_timesheet_id,
        (
          count(distinct identity_value) <= 1
          and count(*) filter (where identity_value is null and raw_value <> '') = 0
        ) as identity_is_valid
      from (
        select
          raw_identity.raw_value,
          case
            when raw_identity.raw_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then lower(raw_identity.raw_value)
            else null::text
          end as identity_value
        from unnest(array[
          coalesce(stored_resolution.timesheet_id::text, ''),
          btrim(coalesce(stored_resolution.payload_json->>'linked_timesheet_id', '')),
          btrim(coalesce(stored_resolution.payload_json->>'timesheet_id', ''))
        ]) as raw_identity(raw_value)
      ) as normalized_identity
    ) as linked_identity on true
    where stored_resolution.session_id = v_workbench_resolution_session_id
      and stored_resolution.candidate_id = v_candidate_id
      and upper(btrim(coalesce(stored_resolution.resolution_family, ''))) = 'NON_BUCKET'
  ), nonbucket_owner_state as (
    select
      nonbucket_row.finance_case_id,
      count(*)::integer as nonbucket_owner_row_count,
      count(*) filter (where nonbucket_row.is_valid_nonbucket_owner)::integer as valid_nonbucket_owner_row_count,
      case
        when count(*) = 1 and count(*) filter (where nonbucket_row.is_valid_nonbucket_owner) = 1
          then min(nonbucket_row.linked_timesheet_id::text)::uuid
        else null::uuid
      end as current_nonbucket_linked_timesheet_id
    from nonbucket_owner_rows as nonbucket_row
    where nonbucket_row.finance_case_id is not null
    group by nonbucket_row.finance_case_id
  )
  select
    scope_row.finance_case_id,
    coalesce(taxable_state.taxable_component_count, 0) as taxable_component_count,
    coalesce(taxable_state.current_taxable_component_count, 0) as current_taxable_component_count,
    coalesce(taxable_state.taxable_saved_evidence_count, 0) as taxable_saved_evidence_count,
    coalesce(nonbucket_state.nonbucket_owner_row_count, 0) as nonbucket_owner_row_count,
    coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) as valid_nonbucket_owner_row_count,
    case
      when coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
       and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT')
        then 'TAXABLE_CHANNEL_RESTRUCTURE'
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
       and scope_row.case_type = 'MANUAL_DEBT_ADJUSTMENT'
        then 'NON_BUCKET'
      else null::text
    end as current_saved_resolution_family,
    case
      when coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
       and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT')
        then 'FINANCE_COMPONENT_SET'
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
       and scope_row.case_type = 'MANUAL_DEBT_ADJUSTMENT'
        then 'SESSION_NON_BUCKET'
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) > 0
        or coalesce(nonbucket_state.nonbucket_owner_row_count, 0) > 0
        then 'AMBIGUOUS'
      else 'NONE'
    end as current_saved_resolution_owner_kind,
    case
      when coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
        then taxable_state.current_taxable_component_count
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
        then 1
      else 0
    end::integer as current_saved_resolution_owner_count,
    (
      (coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
       and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT'))
      or
      (coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
       and scope_row.case_type = 'MANUAL_DEBT_ADJUSTMENT')
    ) as has_current_saved_resolution,
    (
      (
        coalesce(taxable_state.taxable_saved_evidence_count, 0) > 0
        and not (
          coalesce(taxable_state.taxable_component_count, 0) > 0
          and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
          and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
          and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT')
        )
      )
      or coalesce(nonbucket_state.nonbucket_owner_row_count, 0) > 1
      or (
        coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
        and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) <> 1
      )
      or (
        coalesce(taxable_state.taxable_saved_evidence_count, 0) > 0
        and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) > 0
      )
    ) as has_ambiguous_saved_resolution,
    nonbucket_state.current_nonbucket_linked_timesheet_id as current_saved_resolution_linked_timesheet_id
  from finance_case_baseline_scope as scope_row
  left join taxable_owner_state as taxable_state
    on taxable_state.finance_case_id = scope_row.finance_case_id
  left join nonbucket_owner_state as nonbucket_state
    on nonbucket_state.finance_case_id = scope_row.finance_case_id
  where scope_row.finance_case_id is not null;

  create temporary table finance_case_resolution_rollup on commit drop as
        with grouped as (
          select
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.advance_kind,
            vfcr.reason,
            vfcr.candidate_id,
            cp.cand_tms_ref,
            cp.cand_display_name,
            cp.cand_pay_method as candidate_pay_method,
            fpr.payee_entity_kind,
            fpr.payee_entity_id,
            vfcr.client_id,
            vfcr.client_name,
            vfcr.linked_timesheet_id,
            vfcr.linked_shift_date,
            vfcr.adjustment_comment,
            vfcr.next_due_week_start,
            vfcr.active_snooze_id,
            vfcr.active_snooze_kind,
            vfcr.active_snooze_until_date,
            vfcr.active_snooze_note,
            vfcr.taxability,
            vfcr.routing_kind,
            vfcr.oneoff_bank_details_present,
            vfcr.oneoff_bank_details_required,
            vfcr.is_candidate_directed_oneoff_payout,
            vfcr.appears_on_umbrella_remittance,
            vfcr.generates_candidate_payment_advice,
            vfcr.snooze_allowed,
            vfcr.lifecycle_status_display,
            fpr.bank_details_hash as payee_bank_hash,
            fpr.beneficiary_name,
            fpr.masked_bank_account,
            case
              when vfcr.case_type in ('OVERPAYMENT','MANUAL_DEBT_ADJUSTMENT') then true
              when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then true
              else false
            end as is_recovery_case,
            case
              when vfcr.case_type in ('OVERPAYMENT','MANUAL_DEBT_ADJUSTMENT') then '[]'::jsonb
              when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then '[]'::jsonb
              else coalesce(fpr.blocked_reason_codes, '[]'::jsonb)
            end as payee_blocked_reason_codes,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then 'one-off specified bank account'
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then 'umbrella company'
              else 'normal PAYE route'
            end as destination_label,
            round(coalesce(max(fcds.due_source_amount_ex_vat),0),2) as due_source_amount_ex_vat,
            round(coalesce(sum(fcdpa.allocated_preview_due_amount_ex_vat), max(fcds.due_source_amount_ex_vat), 0),2) as due_amount_ex_vat,
            coalesce(fctcr.has_dedicated_resolution_payload,false) as has_taxable_channel_restructure_payload,
            coalesce(fctcr.use_dedicated_blocker,false) as use_taxable_channel_restructure_blocker,
            fctcr.taxable_channel_restructure_resolution_json as taxable_channel_restructure_resolution_json,
            case
              when coalesce(fctcr.use_dedicated_blocker,false) = true then 'TAXABLE_CHANNEL_RESTRUCTURE'::text
              when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'NON_BUCKET'::text
              else 'BUCKETED'::text
            end as resolution_family,
            case
              when coalesce(fctcr.use_dedicated_blocker,false) = true then 'Suggested Restructure'::text
              when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Suggested Gross Total'::text
              else 'Suggested Rate'::text
            end as resolution_action_label,
            fcros.current_saved_resolution_family,
            fcros.current_saved_resolution_owner_kind,
            coalesce(fcros.current_saved_resolution_owner_count, 0)::integer as current_saved_resolution_owner_count,
            coalesce(fcros.has_current_saved_resolution, false) as has_current_saved_resolution,
            coalesce(fcros.has_ambiguous_saved_resolution, false) as has_ambiguous_saved_resolution,
            fcros.current_saved_resolution_linked_timesheet_id,
            coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            ), 0)::int as open_taxable_count,
            coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification in (
                'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
                'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
              )
            ), 0)::int as open_reimbursement_count,
            (coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true), 0)
              + case when coalesce(fctcr.use_dedicated_blocker,false) = true then 1 else 0 end)::int as unresolved_taxable_count,
            coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.is_stale_saved_resolution,false) = true), 0)::int as stale_count,
            (coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            ), 0) > 0
             and
             coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification in (
                'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
                'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
              )
            ), 0) > 0) as is_mixed_case,
            (
              coalesce(fctcr.use_dedicated_blocker,false) = true
              or coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true),0) > 0
            ) as case_needs_resolution,
            (
              coalesce(fctcr.use_dedicated_blocker,false) = false
              and coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true),0) = 0
            ) as case_resolution_satisfied_now,
            case when coalesce(fctcr.use_dedicated_blocker,false) = true then null::jsonb else coalesce(
              (jsonb_agg(
                jsonb_build_object(
                  'resolution_kind', 'NON_BUCKET_GROSS_TOTAL',
                  'resolution_family', 'NON_BUCKET',
                  'resolution_action_label', 'Suggested Gross Total',
                  'source_amount_ex_vat', round(coalesce(fccr.remaining_source_amount,0),2),
                  'suggested_target_amount_ex_vat', round(coalesce(fccr.target_pay_ex_vat,0),2),
                  'approved_target_amount_ex_vat', case when fccr.approved_nonbucket_target_amount_ex_vat is null then null else round(fccr.approved_nonbucket_target_amount_ex_vat,2) end,
                  'suggestion_explanation_text', fccr.suggestion_explanation_text
                )
              ) filter (where vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and fccr.finance_component_id is not null))->0,
              null::jsonb
            ) end as non_bucket_resolution_json,
            coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'finance_component_id', fccr.finance_component_id::text,
                  'source_family_key', fccr.source_family_key,
                  'component_key_type', fccr.component_key_type,
                  'component_key_value', fccr.component_key_value,
                  'classification', fccr.classification::text,
                  'source_pay_method', fccr.source_pay_method,
                  'current_target_pay_method', fccr.current_target_pay_method,
                  'source_amount', round(coalesce(fccr.source_amount,0),2),
                  'remaining_source_amount', round(coalesce(fccr.remaining_source_amount,0),2),
                  'source_basis_json', jsonb_strip_nulls(fccr.source_basis_json || jsonb_build_object('source_rate', case when fccr.source_rate is null then null else round(fccr.source_rate,2) end, 'source_charge_rate', case when fccr.source_charge_rate is null then null else round(fccr.source_charge_rate,2) end)),
                  'saved_target_pay_method', fccr.saved_target_pay_method,
                  'saved_resolution_mode', case when fccr.saved_resolution_mode is null then null else fccr.saved_resolution_mode::text end,
                  'saved_resolution_payload_json', fccr.saved_resolution_payload_json,
                  'saved_resolution_result_json', fccr.saved_resolution_result_json,
                  'has_suggested_resolution', fccr.has_suggested_resolution,
                  'suggestion_provenance', fccr.suggestion_provenance,
                  'is_fresh_suggested_resolution', fccr.is_fresh_suggested_resolution,
                  'is_reusable_saved_resolution', fccr.is_reusable_saved_resolution,
                  'is_stale_saved_resolution', fccr.is_stale_saved_resolution,
                  'suggested_resolution_payload_json', fccr.suggested_resolution_payload_json,
                  'suggested_resolution_result_json', fccr.suggested_resolution_result_json,
                  'source_units', fccr.source_units,
                  'target_units', case when nullif(fccr.suggested_resolution_result_json->>'target_units','') is not null then (fccr.suggested_resolution_result_json->>'target_units')::numeric else fccr.source_units end,
                  'source_rate', case when fccr.source_rate is null then null else round(fccr.source_rate,2) end,
                  'target_rate', case when nullif(fccr.suggested_resolution_result_json->>'replacement_rate','') is not null then round((fccr.suggested_resolution_result_json->>'replacement_rate')::numeric,2) when nullif(fccr.suggested_resolution_payload_json->>'suggested_target_rate','') is not null then round((fccr.suggested_resolution_payload_json->>'suggested_target_rate')::numeric,2) else null end,
                  'source_pay_ex_vat', round(coalesce(fccr.source_pay_ex_vat,0),2),
                  'source_charge_ex_vat', fccr.source_charge_component_ex_vat,
                  'source_margin_ex_vat', fccr.source_margin_ex_vat,
                  'target_pay_ex_vat', round(coalesce(fccr.target_pay_ex_vat,0),2),
                  'target_charge_ex_vat', fccr.target_charge_ex_vat,
                  'target_margin_ex_vat', fccr.target_margin_ex_vat,
                  'margin_delta_ex_vat', fccr.margin_delta_ex_vat,
                  'suggestion_explanation_text', fccr.suggestion_explanation_text,
                  'component_fingerprint', fccr.current_component_fingerprint,
                  'is_resolution_stale', coalesce(fccr.is_stale_saved_resolution,false),
                  'stale_reason', fccr.stale_reason,
                  'requires_resolution', coalesce(fccr.requires_resolution,false),
                  'resolution_state', case
                    when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and coalesce(fccr.requires_resolution,false) = true then 'REQUIRED'
                    when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'RESOLVED'
                    else case when fccr.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum) then 'FIXED' when coalesce(fccr.requires_resolution,false) = true then 'REQUIRED' else 'RESOLVED' end
                  end,
                  'is_actionable_resolution_row', coalesce(fccr.is_actionable_resolution_row,false),
                  'is_fixed_no_action_taxable_row', coalesce(fccr.is_fixed_no_action_taxable_row,false),
                  'allocated_source_due_amount_ex_vat', round(coalesce(fcda.allocated_source_due_amount_ex_vat,0),2),
                  'preview_due_amount_ex_vat', round(coalesce(fcdpa.allocated_preview_due_amount_ex_vat, coalesce(fcda.allocated_source_due_amount_ex_vat,0)),2)
                )
                order by fccr.classification::text, fccr.component_key_type, fccr.component_key_value
              ) filter (where fccr.finance_component_id is not null),
              '[]'::jsonb
            ) as case_components_json
          from finance_case_baseline_scope vfcr
          join cand_payee cp
            on cp.candidate_id = vfcr.candidate_id
          left join finance_case_component_review_rows_effective fccr
            on fccr.finance_case_id = vfcr.finance_case_id
          left join finance_case_payee_readiness fpr
            on fpr.finance_case_id = vfcr.finance_case_id
          left join finance_case_due_source_amounts fcds
            on fcds.finance_case_id = vfcr.finance_case_id
          left join finance_case_component_due_source_allocations fcda
            on fcda.finance_case_id = fccr.finance_case_id
           and fcda.finance_component_id = fccr.finance_component_id
          left join finance_case_component_due_preview_allocations fcdpa
            on fcdpa.finance_case_id = fccr.finance_case_id
           and fcdpa.finance_component_id = fccr.finance_component_id
          left join finance_case_taxable_channel_restructure_resolution fctcr
            on fctcr.finance_case_id = vfcr.finance_case_id
          left join finance_case_resolution_owner_state fcros
            on fcros.finance_case_id = vfcr.finance_case_id
          where vfcr.finance_case_id is not null
          group by
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.advance_kind,
            vfcr.reason,
            vfcr.candidate_id,
            cp.cand_tms_ref,
            cp.cand_display_name,
            cp.cand_pay_method,
            fpr.payee_entity_kind,
            fpr.payee_entity_id,
            fpr.bank_details_hash,
            fpr.beneficiary_name,
            fpr.masked_bank_account,
            fpr.blocked_reason_codes,
            vfcr.client_id,
            vfcr.client_name,
            vfcr.linked_timesheet_id,
            vfcr.linked_shift_date,
            vfcr.adjustment_comment,
            vfcr.next_due_week_start,
            vfcr.active_snooze_id,
            vfcr.active_snooze_kind,
            vfcr.active_snooze_until_date,
            vfcr.active_snooze_note,
            vfcr.taxability,
            vfcr.routing_kind,
            vfcr.oneoff_bank_details_present,
            vfcr.oneoff_bank_details_required,
            vfcr.is_candidate_directed_oneoff_payout,
            vfcr.appears_on_umbrella_remittance,
            vfcr.generates_candidate_payment_advice,
            vfcr.snooze_allowed,
            vfcr.lifecycle_status_display,
            vfcr.payout_status,
            fctcr.has_dedicated_resolution_payload,
            fctcr.use_dedicated_blocker,
            fctcr.taxable_channel_restructure_resolution_json,
            fcros.current_saved_resolution_family,
            fcros.current_saved_resolution_owner_kind,
            fcros.current_saved_resolution_owner_count,
            fcros.has_current_saved_resolution,
            fcros.has_ambiguous_saved_resolution,
            fcros.current_saved_resolution_linked_timesheet_id
        )
        select
          g.finance_case_id,
          g.case_type,
          g.advance_kind,
          g.reason,
          g.candidate_id,
          g.cand_tms_ref,
          g.cand_display_name,
          g.candidate_pay_method,
          g.payee_entity_kind,
          g.payee_entity_id,
          (jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) = 0) as candidate_ready_for_draft,
          g.client_id,
          g.client_name,
          g.linked_timesheet_id,
          g.linked_shift_date,
          g.adjustment_comment,
          g.next_due_week_start,
          g.active_snooze_id,
          g.active_snooze_kind,
          g.active_snooze_until_date,
          g.active_snooze_note,
          g.taxability,
          g.routing_kind,
          g.oneoff_bank_details_present,
          g.oneoff_bank_details_required,
          g.is_candidate_directed_oneoff_payout,
          g.appears_on_umbrella_remittance,
          g.generates_candidate_payment_advice,
          g.snooze_allowed,
          g.lifecycle_status_display,
          g.payee_bank_hash,
          g.beneficiary_name,
          g.masked_bank_account,
          g.destination_label,
          g.due_amount_ex_vat,
          g.open_taxable_count,
          g.open_reimbursement_count,
          g.unresolved_taxable_count,
          g.stale_count,
          g.is_mixed_case,
          g.resolution_family,
          case when g.case_needs_resolution then g.resolution_family else null::text end as required_resolution_family,
          g.current_saved_resolution_family,
          g.current_saved_resolution_owner_kind,
          g.current_saved_resolution_owner_count,
          g.has_current_saved_resolution,
          g.has_ambiguous_saved_resolution,
          g.current_saved_resolution_linked_timesheet_id,
          case
            when g.has_ambiguous_saved_resolution then 'STALE_OR_AMBIGUOUS'
            when g.has_current_saved_resolution then 'RESOLVED_AND_CLEARABLE'
            when g.case_needs_resolution then 'REQUIRES_RESOLUTION'
            else 'NOT_REQUIRED'
          end as finance_resolution_clearability_state,
          case
            when g.has_ambiguous_saved_resolution then 'SAVED_RESOLUTION_OWNER_STALE_OR_AMBIGUOUS'
            else null::text
          end as finance_resolution_clear_block_reason,
          g.case_needs_resolution,
          g.case_resolution_satisfied_now,
          g.resolution_action_label,
          g.taxable_channel_restructure_resolution_json,
          null::jsonb as linked_resolution_scope_json,
          (
            g.case_needs_resolution = true
            or jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) > 0
          ) as is_blocked,
          (
            coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)
            ||
            (case
              when g.resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_CHANNEL_RESTRUCTURE')
              when g.resolution_family = 'NON_BUCKET' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_NON_BUCKET_RESOLUTION')
              when g.resolution_family = 'BUCKETED' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_RESOLUTION')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes,
          jsonb_strip_nulls(
            jsonb_build_object(
              'case_key', ('finance:' || g.finance_case_id::text),
              'case_type', g.case_type::text,
              'resolution_family', g.resolution_family,
              'required_resolution_family', case when g.case_needs_resolution then g.resolution_family else null end,
              'current_saved_resolution_family', g.current_saved_resolution_family,
              'current_saved_resolution_owner_kind', g.current_saved_resolution_owner_kind,
              'current_saved_resolution_owner_count', g.current_saved_resolution_owner_count,
              'has_current_saved_resolution', g.has_current_saved_resolution,
              'has_ambiguous_saved_resolution', g.has_ambiguous_saved_resolution,
              'current_saved_resolution_linked_timesheet_id', case
                when g.current_saved_resolution_linked_timesheet_id is null then null
                else g.current_saved_resolution_linked_timesheet_id::text
              end,
              'finance_resolution_clearability_state', case
                when g.has_ambiguous_saved_resolution then 'STALE_OR_AMBIGUOUS'
                when g.has_current_saved_resolution then 'RESOLVED_AND_CLEARABLE'
                when g.case_needs_resolution then 'REQUIRES_RESOLUTION'
                else 'NOT_REQUIRED'
              end,
              'finance_resolution_clear_block_reason', case
                when g.has_ambiguous_saved_resolution then 'SAVED_RESOLUTION_OWNER_STALE_OR_AMBIGUOUS'
                else null
              end,
              'case_needs_resolution', g.case_needs_resolution,
              'case_resolution_satisfied_now', g.case_resolution_satisfied_now,
              'resolution_action_label', g.resolution_action_label,
              'linked_resolution_scope_json', null,
              'taxability', case when g.taxability is null then null else g.taxability::text end,
              'routing_kind', case when g.routing_kind is null then null else g.routing_kind::text end,
              'destination_label', g.destination_label,
              'is_mixed_case', g.is_mixed_case,
              'open_taxable_count', g.open_taxable_count,
              'open_reimbursement_count', g.open_reimbursement_count,
              'unresolved_taxable_count', g.unresolved_taxable_count,
              'stale_count', g.stale_count,
              'is_blocked', (
                g.case_needs_resolution = true
                or jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) > 0
              ),
              'due_amount_ex_vat', g.due_amount_ex_vat,
              'blocked_reason_codes', (
                coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)
                ||
                (case
                  when g.resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_CHANNEL_RESTRUCTURE')
                  when g.resolution_family = 'NON_BUCKET' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_NON_BUCKET_RESOLUTION')
                  when g.resolution_family = 'BUCKETED' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_RESOLUTION')
                  else '[]'::jsonb
                end)
              ),
              'non_bucket_resolution', g.non_bucket_resolution_json,
              'taxable_channel_restructure', g.taxable_channel_restructure_resolution_json,
              'taxable_channel_restructure_resolution', g.taxable_channel_restructure_resolution_json
            )
          ) as case_resolution_summary_json,
          case
            when g.resolution_family = 'NON_BUCKET'
              and jsonb_typeof(g.non_bucket_resolution_json) = 'object'
            then g.non_bucket_resolution_json
            else null::jsonb
          end as taxable_manual_debt_resolution_json,
          g.case_components_json
        from grouped g

  ;

  PERFORM public._imp_debug_audit(
    v_actor_user_id,
    'PAY_PREVIEW_FINANCE_CASE_BASELINE_RESULT',
    jsonb_build_object(
      'candidate_id', v_candidate_id,
      'finance_case_component_count', (select count(*)::int from finance_case_component_review_rows_effective),
      'finance_case_resolution_count', (select count(*)::int from finance_case_resolution_rollup),
      'finance_case_repaid_wtd_count', (select count(*)::int from finance_case_repaid_wtd)
    ),
    'pay_preview_finance',
    COALESCE(v_candidate_id::text, 'NO_CANDIDATE_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'finance_case_component_count', (select count(*)::int from finance_case_component_review_rows_effective),
    'finance_case_resolution_count', (select count(*)::int from finance_case_resolution_rollup)
  );

exception
  when others then
    PERFORM public._imp_debug_audit(
      v_actor_user_id,
      'PAY_PREVIEW_FINANCE_CASE_BASELINE_ERROR',
      jsonb_build_object(
        'candidate_id', p_candidate_id,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_preview_finance',
      COALESCE(p_candidate_id::text, 'NO_CANDIDATE_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$;

-- ---------------------------------------------------------------------------------------------------
-- 2d. Settings-OFF legacy branch, overload (uuid,uuid): same order key
-- ---------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(p_session_id uuid, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_nonterminal_line_count integer := 0;
  v_retained_positive_headroom numeric(12,2) := 0;
  v_recovery_group_count integer := 0;
  v_promoted_count integer := 0;
  v_promoted_selected_count integer := 0;
  v_repaired_authority_scope_count integer := 0;
  v_ready_recovery_capped_count integer := 0;
  v_ready_recovery_blocked_count integer := 0;
  v_demoted_count integer := 0;
  v_superseded_count integer := 0;
  v_line_work_revalidated_count integer := 0;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_row_count integer := 0;
  v_selection_intent_mode text := '';
  v_progress_json jsonb := '{}'::jsonb;
  v_scope_attestation jsonb := '{}'::jsonb;
  v_v3_overlay_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  SELECT COALESCE(scope_row.certified_preview_publication_attestation_json, '{}'::jsonb)
  INTO v_scope_attestation
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_NOT_IN_SCOPE',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  v_selection_intent_mode := UPPER(BTRIM(COALESCE(
    v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
    CASE
      WHEN COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
        THEN 'EXPLICIT_INCLUDE'
      ELSE 'IMPLICIT_ALL'
    END
  )));
  IF v_selection_intent_mode NOT IN ('IMPLICIT_ALL', 'EXPLICIT_INCLUDE') THEN
    v_selection_intent_mode := CASE
      WHEN COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
        THEN 'EXPLICIT_INCLUDE'
      ELSE 'IMPLICIT_ALL'
    END;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_nonterminal_line_count
  FROM public.banking_pay_workbench_candidate_line_work AS line_work
  WHERE line_work.session_id = p_session_id
    AND line_work.candidate_id = p_candidate_id
    AND UPPER(BTRIM(COALESCE(line_work.status, ''))) NOT IN (
      'MATERIALISED',
      'SKIPPED',
      'ERROR',
      'FAILED',
      'CANCELLED',
      'CANCELED',
      'SUPERSEDED',
      'RETIRED'
    );

  IF COALESCE(v_nonterminal_line_count, 0) > 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'DEFERRED_UNTIL_FINAL_MATERIALISATION',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'nonterminal_line_count', v_nonterminal_line_count,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    );
  END IF;

  -- V3 keeps the certified source/preview identity immutable.  Recovery
  -- readiness is a pre-Draft selection projection: it is recalculated from
  -- positive rows the candidate has actually selected, while the physical
  -- source-backed preview section remains unchanged for exact parity.
  IF v_scope_attestation->>'attestation_version' = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
     AND v_scope_attestation->>'contract_version' = '3'
     AND v_scope_attestation->>'semantic_contract_version' = 'READY_TO_PAY_SEMANTIC_V2' THEN
    v_v3_overlay_result := private.pay_workbench_recovery_selection_overlay_apply_v1(
      p_session_id,
      p_candidate_id,
      jsonb_build_object('reason', 'SELECTION_REVALIDATION')
    );

    RETURN COALESCE(v_v3_overlay_result, '{}'::jsonb)
      || jsonb_build_object(
        'legacy_physical_section_revalidation_skipped', true,
        'certified_source_preview_identity_preserved', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
  END IF;

  SELECT ROUND(COALESCE(SUM(
           CASE
             WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
               THEN GREATEST((preview_row.row_json->>'amount_ex_vat')::numeric, 0)
             ELSE 0::numeric
           END
         ), 0), 2)::numeric(12,2)
  INTO v_retained_positive_headroom
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.session_version = COALESCE(v_session_row.version, 1)
    AND preview_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(preview_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    AND (
      v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
      OR (
        COALESCE(preview_row.selected, false) IS TRUE
        AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
      )
      OR (
        LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
      )
    )
    AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', ''))) NOT IN (
      'MANUAL_DEBT_RECOVERY',
      'OVERPAYMENT_RECOVERY',
      'LOAN_REPAYMENT',
      'PAYMENT_ADVANCE_REPAYMENT'
    );

  IF COALESCE(v_retained_positive_headroom, 0) > 0 THEN
    /*
     * A recovery line may have been materialised before the candidate's final
     * positive correction carrier. In that order it is correctly emitted as
     * NO_PAY_HEADROOM, but the terminal candidate view is then stale once the
     * positive carrier exists. Reconcile the other direction here as well:
     * promote only rows whose sole blocker is NO_PAY_HEADROOM, allocate against
     * retained positive pay in the same pay channel, and leave every financial
     * amount sourced from the already-materialised pre-draft authority.
     */
    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_ready_recovery_allocation;
    CREATE TEMP TABLE _tmp_pay_wb_ready_recovery_allocation ON COMMIT DROP AS
    WITH positive_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          positive_row.row_json->>'pay_channel',
          positive_row.row_json->>'current_pay_method',
          positive_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN GREATEST((positive_row.row_json->>'amount_ex_vat')::numeric, 0)
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS positive_row
      WHERE positive_row.session_id = p_session_id
        AND positive_row.session_version = COALESCE(v_session_row.version, 1)
        AND positive_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(positive_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(positive_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
          OR (
            COALESCE(positive_row.selected, false) IS TRUE
            AND UPPER(BTRIM(COALESCE(positive_row.selection_state, ''))) = 'SELECTED'
          )
          OR (
            LOWER(BTRIM(COALESCE(positive_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND UPPER(BTRIM(COALESCE(positive_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
          )
        )
        AND UPPER(BTRIM(COALESCE(positive_row.row_json->>'line_type', positive_row.row_json->>'item_type', ''))) NOT IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
      GROUP BY UPPER(BTRIM(COALESCE(
        positive_row.row_json->>'pay_channel',
        positive_row.row_json->>'current_pay_method',
        positive_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), ready_recovery AS (
      SELECT
        ready_row.id AS ready_preview_row_id,
        ready_row.row_key,
        ready_row.row_ordinal,
        ready_row.timesheet_id,
        ready_row.key_type,
        ready_row.key_value,
        ready_row.selected,
        ready_row.selection_state,
        COALESCE(ready_row.row_json, '{}'::jsonb) AS base_row_json,
        UPPER(BTRIM(COALESCE(
          ready_row.row_json->>'pay_channel',
          ready_row.row_json->>'current_pay_method',
          ready_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(
          CASE
            -- A33 (critic finding 2): the nominal due is the row's own uncapped nominal_due_amount_ex_vat when it
            -- carries one, the same basis private.pay_workbench_recovery_selection_overlay_apply_v1 uses. The
            -- per-component preview due below is the figure ALREADY capped by the earlier running total, so an
            -- exclusion could never release headroom to it (GBP80 due stayed GBP20). Rows without the field keep
            -- the previous derivation unchanged.
            WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric) > 0
              THEN ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            WHEN COALESCE((
              SELECT SUM(
                CASE
                  WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                    THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                  ELSE 0::numeric
                END
              )
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(ready_row.row_json->'case_components') = 'array'
                    THEN ready_row.row_json->'case_components'
                  ELSE '[]'::jsonb
                END
              ) AS component_row(value)
            ), 0) > 0
              THEN (
                SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
                FROM jsonb_array_elements(ready_row.row_json->'case_components') AS component_row(value)
                WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              )
            WHEN COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((ready_row.row_json->>'amount_ex_vat')::numeric) > 0
              THEN ABS((ready_row.row_json->>'amount_ex_vat')::numeric)
            WHEN COALESCE(ready_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((ready_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}')::numeric)
            WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            ELSE 0::numeric
          END,
          2
        )::numeric(12,2) AS nominal_due_amount_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS ready_row
      WHERE ready_row.session_id = p_session_id
        AND ready_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(ready_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
        AND ROUND((ready_row.row_json->>'amount_ex_vat')::numeric, 2) < 0
    ), ranked_recovery AS (
      SELECT
        ready_recovery.*,
        COALESCE(positive_by_channel.positive_headroom_ex_vat, 0)::numeric(12,2) AS positive_headroom_ex_vat,
        COALESCE(SUM(
          CASE
            -- A33 (critic finding 2; APPROVED rule, roadmap "Product behaviour that remains fixed"): on this non-V3
            -- branch too, a repayment the Office explicitly excluded consumes no headroom, exactly as A30 M1 does in
            -- private.pay_workbench_recovery_selection_overlay_apply_v1 (GBP100 headroom, first GBP80 excluded, second
            -- GBP80 included -> the second receives GBP80, not GBP20). Every A33 edit in this function is marked A33.
            WHEN UPPER(BTRIM(COALESCE(ready_recovery.base_row_json->>'selection_user_override', ''))) = 'UNSELECTED'
              THEN 0::numeric
            ELSE ready_recovery.nominal_due_amount_ex_vat
          END
        ) OVER (
          PARTITION BY ready_recovery.pay_channel
          -- A34 (user rulings 25 Q6-A and 31; Worker BT): oldest debt first -- the SAME key and tie-break as the V3
          -- overlay and the canonical builder (Stage 3 WP3): creation date and time, a loan by its payout; ties by
          -- finance case id.  Was: row_ordinal, id (effectively reference order).
          ORDER BY private.s3p_recovery_order_key_v1(CASE WHEN ready_recovery.base_row_json->>'finance_case_id'
                     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                     THEN (ready_recovery.base_row_json->>'finance_case_id')::uuid END) NULLS LAST,
                   ready_recovery.base_row_json->>'finance_case_id', ready_recovery.row_ordinal, ready_recovery.ready_preview_row_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::numeric(12,2) AS prior_nominal_due_amount_ex_vat
      FROM ready_recovery
      LEFT JOIN positive_by_channel
        ON positive_by_channel.pay_channel = ready_recovery.pay_channel
      WHERE ready_recovery.pay_channel IN ('PAYE', 'UMBRELLA')
        AND ready_recovery.nominal_due_amount_ex_vat > 0
    ), allocated_recovery AS (
      SELECT
        ranked_recovery.*,
        ROUND(LEAST(
          ranked_recovery.nominal_due_amount_ex_vat,
          GREATEST(
            ranked_recovery.positive_headroom_ex_vat - ranked_recovery.prior_nominal_due_amount_ex_vat,
            0
          )
        ), 2)::numeric(12,2) AS recoverable_amount_ex_vat
      FROM ranked_recovery
    )
    SELECT
      allocated_recovery.*,
      ROUND(SUM(allocated_recovery.recoverable_amount_ex_vat) OVER (
        PARTITION BY allocated_recovery.pay_channel
      ), 2)::numeric(12,2) AS channel_recoverable_amount_ex_vat
    FROM allocated_recovery;

    WITH capped_source AS (
      SELECT
        allocation.ready_preview_row_id,
        allocation.base_row_json
          || jsonb_build_object(
            'amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'preview_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'amount_display', -allocation.recoverable_amount_ex_vat,
            'section_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'section_amount_display', -allocation.recoverable_amount_ex_vat,
            'target_pay_ex_vat', -allocation.recoverable_amount_ex_vat,
            'ready_preview_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'preview_component_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'nominal_due_amount_ex_vat', allocation.nominal_due_amount_ex_vat,
            'recoverable_this_pay_run_ex_vat', allocation.recoverable_amount_ex_vat,
            'recovery_group_recoverable_this_pay_run_ex_vat', allocation.channel_recoverable_amount_ex_vat,
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
            'retained_positive_headroom_ex_vat', allocation.positive_headroom_ex_vat,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'case_resolution_summary', CASE
              WHEN jsonb_typeof(COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
                THEN COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)
                  || jsonb_build_object('due_amount_ex_vat', allocation.recoverable_amount_ex_vat)
              ELSE jsonb_build_object('due_amount_ex_vat', allocation.recoverable_amount_ex_vat)
            END
          ) AS capped_row_json
      FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
      WHERE allocation.recoverable_amount_ex_vat > 0
    ), contracted_source AS (
      SELECT
        capped_source.ready_preview_row_id,
        capped_source.capped_row_json,
        public.pay_workbench_preview_line_contract_ok(
          p_line_json => capped_source.capped_row_json,
          p_economic_key_json => COALESCE(capped_source.capped_row_json->'economic_key', '{}'::jsonb),
          p_target_section => 'canonical_preview_lines'
        ) AS capped_contract_json
      FROM capped_source
    )
    UPDATE public.banking_pay_workbench_preview_rows AS ready_row
    SET row_json = contracted_source.capped_row_json
          || jsonb_build_object(
            'preview_contract', contracted_source.capped_contract_json,
            'selection_allowed', true
          ),
        updated_at_utc = v_now
    FROM contracted_source
    WHERE ready_row.id = contracted_source.ready_preview_row_id
      AND LOWER(BTRIM(COALESCE(contracted_source.capped_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(contracted_source.capped_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    GET DIAGNOSTICS v_ready_recovery_capped_count = ROW_COUNT;

    INSERT INTO public.banking_pay_workbench_preview_rows (
      session_id,
      candidate_id,
      section,
      row_key,
      row_ordinal,
      row_json,
      timesheet_id,
      key_type,
      key_value,
      selected,
      selection_state,
      status,
      session_version,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_session_id,
      p_candidate_id,
      'blocked_for_pay',
      allocation.row_key,
      allocation.row_ordinal,
      (
        allocation.base_row_json
        - 'source_basis_json'
        - 'frozen_source_basis_json'
        - 'frozen_component_snapshot_json'
        - 'finance_component_id'
        - 'materialised_from_line_work_id'
      )
      || jsonb_build_object(
        'line_key', allocation.row_key,
        'row_key', allocation.row_key,
        'presentation_line_id', allocation.row_key,
        'section', 'blocked_for_pay',
        'target_section', 'blocked_for_pay',
        'readiness_state', 'BLOCKED_FOR_PAY',
        'presentation_section', 'BLOCKED_FOR_PAY',
        'presentation_reason', 'NO_PAY_HEADROOM',
        'amount_ex_vat', 0,
        'preview_amount_ex_vat', 0,
        'amount_display', 0,
        'section_amount_ex_vat', 0,
        'section_amount_display', 0,
        'target_pay_ex_vat', 0,
        'ready_preview_amount_ex_vat', 0,
        'preview_component_amount_ex_vat', 0,
        'recoverable_this_pay_run_ex_vat', 0,
        'nominal_due_amount_ex_vat', allocation.nominal_due_amount_ex_vat,
        'draftable', false,
        'is_ready_for_draft', false,
        'selection_allowed', false,
        'is_excluded_from_allocation', true,
        'selected', false,
        'selection_state', 'NOT_SELECTABLE',
        'blocked_reason_codes', jsonb_build_array('NO_PAY_HEADROOM'),
        'materialisation_recovery_headroom_revalidated', true,
        'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
        'retained_positive_headroom_ex_vat', allocation.positive_headroom_ex_vat,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
        'case_resolution_summary', CASE
          WHEN jsonb_typeof(COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
            THEN COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)
              || jsonb_build_object('due_amount_ex_vat', 0)
          ELSE jsonb_build_object('due_amount_ex_vat', 0)
        END
      )
      || jsonb_build_object(
        'preview_contract', COALESCE(allocation.base_row_json->'preview_contract', '{}'::jsonb)
          || jsonb_build_object(
            'line_key', allocation.row_key,
            'amount_ex_vat', 0,
            'draftable', false,
            'is_ready_for_draft', false,
            'selection_allowed', false,
            'is_excluded_from_allocation', true,
            'target_section', 'blocked_for_pay',
            'presentation_section', 'BLOCKED_FOR_PAY'
          )
      ),
      allocation.timesheet_id,
      allocation.key_type,
      allocation.key_value,
      false,
      'NOT_SELECTABLE',
      'READY',
      COALESCE(v_session_row.version, 1),
      v_now,
      v_now
    FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
    WHERE allocation.recoverable_amount_ex_vat <= 0
    ON CONFLICT (session_id, section, candidate_id, row_key)
    DO UPDATE
    SET row_ordinal = EXCLUDED.row_ordinal,
        row_json = EXCLUDED.row_json,
        timesheet_id = EXCLUDED.timesheet_id,
        key_type = EXCLUDED.key_type,
        key_value = EXCLUDED.key_value,
        selected = false,
        selection_state = 'NOT_SELECTABLE',
        status = 'READY',
        session_version = EXCLUDED.session_version,
        updated_at_utc = v_now;

    GET DIAGNOSTICS v_ready_recovery_blocked_count = ROW_COUNT;

    UPDATE public.banking_pay_workbench_preview_rows AS ready_row
    SET status = 'SUPERSEDED',
        selected = false,
        selection_state = 'SUPERSEDED',
        row_json = COALESCE(ready_row.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'selected', false,
            'selection_state', 'SUPERSEDED',
            'superseded_reason', 'RECOVERY_EXCEEDS_SELECTED_POSITIVE_HEADROOM',
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
          ),
        updated_at_utc = v_now
    WHERE ready_row.id IN (
      SELECT allocation.ready_preview_row_id
      FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
      WHERE allocation.recoverable_amount_ex_vat <= 0
    );

    IF COALESCE(v_ready_recovery_capped_count, 0) > 0
       OR COALESCE(v_ready_recovery_blocked_count, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = active_row.row_json,
          updated_at_utc = v_now
      FROM (
        SELECT ready_row.row_key, ready_row.row_json
        FROM public.banking_pay_workbench_preview_rows AS ready_row
        WHERE ready_row.session_id = p_session_id
          AND ready_row.session_version = COALESCE(v_session_row.version, 1)
          AND ready_row.candidate_id = p_candidate_id
          AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
          AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        UNION ALL
        SELECT blocked_row.row_key, blocked_row.row_json
        FROM public.banking_pay_workbench_preview_rows AS blocked_row
        WHERE blocked_row.session_id = p_session_id
          AND blocked_row.session_version = COALESCE(v_session_row.version, 1)
          AND blocked_row.candidate_id = p_candidate_id
          AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
          AND UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY'
      ) AS active_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND line_work.line_key = active_row.row_key
        AND EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
          WHERE allocation.row_key = line_work.line_key
        );
    END IF;

    WITH repair_source AS (
      SELECT
        ready_recovery_row.id,
        ready_recovery_row.row_json
          || jsonb_build_object(
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text
          ) AS repaired_row_json
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'materialisation_recovery_headroom_revalidated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'line_type', ready_recovery_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    ), contracted_repair AS (
      SELECT
        repair_source.id,
        repair_source.repaired_row_json,
        public.pay_workbench_preview_line_contract_ok(
          p_line_json => repair_source.repaired_row_json,
          p_economic_key_json => COALESCE(repair_source.repaired_row_json->'economic_key', '{}'::jsonb),
          p_target_section => 'canonical_preview_lines'
        ) AS repaired_contract_json
      FROM repair_source
    )
    UPDATE public.banking_pay_workbench_preview_rows AS ready_recovery_row
    SET row_json = contracted_repair.repaired_row_json
          || jsonb_build_object(
            'preview_contract', contracted_repair.repaired_contract_json,
            'selection_allowed', true
          ),
        updated_at_utc = v_now
    FROM contracted_repair
    WHERE ready_recovery_row.id = contracted_repair.id
      AND LOWER(BTRIM(COALESCE(contracted_repair.repaired_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(contracted_repair.repaired_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    GET DIAGNOSTICS v_repaired_authority_scope_count = ROW_COUNT;

    IF COALESCE(v_repaired_authority_scope_count, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = ready_recovery_row.row_json,
          updated_at_utc = v_now
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND ready_recovery_row.updated_at_utc = v_now
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
        AND line_work.line_key = ready_recovery_row.row_key;
    END IF;

    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_positive_headroom_recovery;
    CREATE TEMP TABLE _tmp_pay_wb_positive_headroom_recovery ON COMMIT DROP AS
    WITH gross_positive_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          preview_row.row_json->>'pay_channel',
          preview_row.row_json->>'current_pay_method',
          preview_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN GREATEST((preview_row.row_json->>'amount_ex_vat')::numeric, 0)
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = p_session_id
        AND preview_row.session_version = COALESCE(v_session_row.version, 1)
        AND preview_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(preview_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
          OR (
            COALESCE(preview_row.selected, false) IS TRUE
            AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
          )
          OR (
            LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
          )
        )
        AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', ''))) NOT IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
      GROUP BY UPPER(BTRIM(COALESCE(
        preview_row.row_json->>'pay_channel',
        preview_row.row_json->>'current_pay_method',
        preview_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), ready_recovery_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          ready_recovery_row.row_json->>'pay_channel',
          ready_recovery_row.row_json->>'current_pay_method',
          ready_recovery_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(ready_recovery_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS(LEAST((ready_recovery_row.row_json->>'amount_ex_vat')::numeric, 0))
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS allocated_recovery_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'line_type', ready_recovery_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        -- A33 (critic finding 2): an explicitly excluded READY repayment consumes no headroom here either, so the
        -- NO_PAY_HEADROOM promotion pass below can give the released headroom to a later included repayment.
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'selection_user_override', ''))) <> 'UNSELECTED'
      GROUP BY UPPER(BTRIM(COALESCE(
        ready_recovery_row.row_json->>'pay_channel',
        ready_recovery_row.row_json->>'current_pay_method',
        ready_recovery_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), positive_by_channel AS (
      SELECT
        gross_positive.pay_channel,
        ROUND(GREATEST(
          gross_positive.positive_headroom_ex_vat
            - COALESCE(ready_recovery.allocated_recovery_ex_vat, 0),
          0
        ), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM gross_positive_by_channel AS gross_positive
      LEFT JOIN ready_recovery_by_channel AS ready_recovery
        ON ready_recovery.pay_channel = gross_positive.pay_channel
    ), blocked_recovery AS (
      SELECT
        blocked_row.id AS blocked_preview_row_id,
        blocked_row.candidate_id,
        blocked_row.row_key,
        blocked_row.row_ordinal,
        blocked_row.timesheet_id,
        blocked_row.key_type,
        blocked_row.key_value,
        blocked_row.row_json AS base_row_json,
        UPPER(BTRIM(COALESCE(
          blocked_row.row_json->>'pay_channel',
          blocked_row.row_json->>'current_pay_method',
          blocked_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(
          CASE
            -- A33 (critic finding 2): the nominal due is the row's own uncapped nominal_due_amount_ex_vat when it
            -- carries one, the same basis private.pay_workbench_recovery_selection_overlay_apply_v1 uses. The
            -- per-component preview due below is the figure ALREADY capped by the earlier running total, so an
            -- exclusion could never release headroom to it (GBP80 due stayed GBP20). Rows without the field keep
            -- the previous derivation unchanged.
            WHEN COALESCE(blocked_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((blocked_row.row_json->>'nominal_due_amount_ex_vat')::numeric) > 0
              THEN ABS((blocked_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            WHEN COALESCE((
              SELECT SUM(
                CASE
                  WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                    THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                  ELSE 0::numeric
                END
              )
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(blocked_row.row_json->'case_components') = 'array'
                    THEN blocked_row.row_json->'case_components'
                  ELSE '[]'::jsonb
                END
              ) AS component_row(value)
            ), 0) > 0
              THEN (
                SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
                FROM jsonb_array_elements(blocked_row.row_json->'case_components') AS component_row(value)
                WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              )
            WHEN COALESCE(blocked_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((blocked_row.row_json->>'amount_ex_vat')::numeric) > 0
              THEN ABS((blocked_row.row_json->>'amount_ex_vat')::numeric)
            WHEN COALESCE(blocked_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((blocked_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}')::numeric)
            WHEN COALESCE(blocked_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((blocked_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            ELSE 0::numeric
          END,
          2
        )::numeric(12,2) AS nominal_due_amount_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS blocked_row
      WHERE blocked_row.session_id = p_session_id
        AND blocked_row.session_version = COALESCE(v_session_row.version, 1)
        AND blocked_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
        AND UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(blocked_row.row_json->>'line_type', blocked_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND (
          UPPER(BTRIM(COALESCE(blocked_row.row_json->>'presentation_reason', ''))) = 'NO_PAY_HEADROOM'
          OR COALESCE(blocked_row.row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
        )
        AND LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_is_blocked', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_needs_resolution_now', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_resolution_satisfied_now', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR UPPER(BTRIM(COALESCE(blocked_row.row_json->>'resolution_state', ''))) = 'RESOLVED'
          OR LOWER(BTRIM(COALESCE(blocked_row.row_json->>'is_case_resolution_satisfied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        )
        AND NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(blocked_row.row_json->'blocked_reason_codes') = 'array'
                THEN blocked_row.row_json->'blocked_reason_codes'
              ELSE '[]'::jsonb
            END
          ) AS blocked_code(value)
          WHERE UPPER(BTRIM(blocked_code.value)) <> 'NO_PAY_HEADROOM'
        )
    ), ranked_recovery AS (
      SELECT
        blocked_recovery.*,
        COALESCE(positive_by_channel.positive_headroom_ex_vat, 0)::numeric(12,2) AS positive_headroom_ex_vat,
        COALESCE(SUM(
          CASE
            -- A33 (critic finding 2; APPROVED rule, roadmap "Product behaviour that remains fixed"): on this non-V3
            -- branch too, a repayment the Office explicitly excluded consumes no headroom, exactly as A30 M1 does in
            -- private.pay_workbench_recovery_selection_overlay_apply_v1 (GBP100 headroom, first GBP80 excluded, second
            -- GBP80 included -> the second receives GBP80, not GBP20). Every A33 edit in this function is marked A33.
            WHEN UPPER(BTRIM(COALESCE(blocked_recovery.base_row_json->>'selection_user_override', ''))) = 'UNSELECTED'
              THEN 0::numeric
            ELSE blocked_recovery.nominal_due_amount_ex_vat
          END
        ) OVER (
          PARTITION BY blocked_recovery.pay_channel
          -- A34 (user rulings 25 Q6-A and 31; Worker BT): oldest debt first -- the SAME key and tie-break as the V3
          -- overlay and the canonical builder (Stage 3 WP3): creation date and time, a loan by its payout; ties by
          -- finance case id.  Was: row_ordinal, id (effectively reference order).
          ORDER BY private.s3p_recovery_order_key_v1(CASE WHEN blocked_recovery.base_row_json->>'finance_case_id'
                     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                     THEN (blocked_recovery.base_row_json->>'finance_case_id')::uuid END) NULLS LAST,
                   blocked_recovery.base_row_json->>'finance_case_id', blocked_recovery.row_ordinal, blocked_recovery.blocked_preview_row_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::numeric(12,2) AS prior_nominal_due_amount_ex_vat
      FROM blocked_recovery
      LEFT JOIN positive_by_channel
        ON positive_by_channel.pay_channel = blocked_recovery.pay_channel
      WHERE blocked_recovery.pay_channel IN ('PAYE', 'UMBRELLA')
        AND ROUND(COALESCE(blocked_recovery.nominal_due_amount_ex_vat, 0), 2) > 0
    ), allocated_recovery AS (
      SELECT
        ranked_recovery.*,
        ROUND(LEAST(
          ranked_recovery.nominal_due_amount_ex_vat,
          GREATEST(
            ranked_recovery.positive_headroom_ex_vat - ranked_recovery.prior_nominal_due_amount_ex_vat,
            0
          )
        ), 2)::numeric(12,2) AS recoverable_amount_ex_vat
      FROM ranked_recovery
    )
    SELECT
      allocated_recovery.*,
      COALESCE(existing_ready.id, gen_random_uuid()) AS promoted_preview_row_id,
      CASE
        WHEN UPPER(BTRIM(COALESCE(
          allocated_recovery.base_row_json->>'selection_user_override',
          existing_ready.row_json->>'selection_user_override',
          ''
        ))) = 'UNSELECTED'
          THEN false
        ELSE true
      END AS promoted_selected
    FROM allocated_recovery
    LEFT JOIN public.banking_pay_workbench_preview_rows AS existing_ready
      ON existing_ready.session_id = p_session_id
     AND existing_ready.session_version = COALESCE(v_session_row.version, 1)
     AND existing_ready.candidate_id = p_candidate_id
     AND LOWER(BTRIM(COALESCE(existing_ready.section, ''))) = 'canonical_preview_lines'
     AND existing_ready.row_key = allocated_recovery.row_key
    WHERE allocated_recovery.recoverable_amount_ex_vat > 0;

    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE promoted_selected)::integer
    INTO v_promoted_count,
         v_promoted_selected_count
    FROM pg_temp._tmp_pay_wb_positive_headroom_recovery;

    IF COALESCE(v_promoted_count, 0) > 0 THEN
      WITH promoted_payload AS (
        SELECT
          promotion.*,
          jsonb_strip_nulls(
            (
              promotion.base_row_json
              - 'blocked_reason_codes'
              - 'superseded_reason'
              - 'materialisation_recovery_headroom_revalidated'
              - 'materialisation_recovery_headroom_revalidated_at_utc'
            )
            || jsonb_build_object(
              'preview_row_id', promotion.promoted_preview_row_id::text,
              'line_id', promotion.promoted_preview_row_id::text,
              'section', 'canonical_preview_lines',
              'target_section', 'canonical_preview_lines',
              'readiness_state', 'READY',
              'presentation_section', 'READY_TO_PAY',
              'presentation_reason', NULL,
              'amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'preview_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'amount_display', -promotion.recoverable_amount_ex_vat,
              'section_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'section_amount_display', -promotion.recoverable_amount_ex_vat,
              'target_pay_ex_vat', -promotion.recoverable_amount_ex_vat,
              'ready_preview_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'preview_component_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'nominal_due_amount_ex_vat', promotion.nominal_due_amount_ex_vat,
              'recoverable_this_pay_run_ex_vat', promotion.recoverable_amount_ex_vat,
              'draftable', true,
              'is_ready_for_draft', true,
              'selection_allowed', true,
              'is_excluded_from_allocation', false,
              'selected', promotion.promoted_selected,
              'selection_state', CASE WHEN promotion.promoted_selected THEN 'SELECTED' ELSE 'UNSELECTED' END,
              'selection_origin', CASE
                WHEN UPPER(BTRIM(COALESCE(promotion.base_row_json->>'selection_user_override', ''))) = 'UNSELECTED'
                  THEN 'USER_EXPLICIT_DESELECT'
                ELSE 'SERVER_DEFAULT_NEWLY_ELIGIBLE'
              END,
              'materialisation_recovery_headroom_revalidated', true,
              'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
              'retained_positive_headroom_ex_vat', promotion.positive_headroom_ex_vat,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
            || jsonb_build_object(
              'case_resolution_summary', CASE
                WHEN jsonb_typeof(COALESCE(promotion.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
                  THEN COALESCE(promotion.base_row_json->'case_resolution_summary', '{}'::jsonb)
                    || jsonb_build_object('due_amount_ex_vat', promotion.recoverable_amount_ex_vat)
                ELSE jsonb_build_object('due_amount_ex_vat', promotion.recoverable_amount_ex_vat)
              END
            )
          ) AS promoted_row_json
        FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
      ), contracted_payload AS (
        SELECT
          promoted_payload.*,
          public.pay_workbench_preview_line_contract_ok(
            p_line_json => promoted_payload.promoted_row_json,
            p_economic_key_json => COALESCE(promoted_payload.promoted_row_json->'economic_key', '{}'::jsonb),
            p_target_section => 'canonical_preview_lines'
          ) AS promoted_contract_json
        FROM promoted_payload
      )
      INSERT INTO public.banking_pay_workbench_preview_rows (
        id,
        session_id,
        candidate_id,
        section,
        row_key,
        row_ordinal,
        row_json,
        timesheet_id,
        key_type,
        key_value,
        selected,
        selection_state,
        status,
        session_version,
        created_at_utc,
        updated_at_utc
      )
      SELECT
        contracted_payload.promoted_preview_row_id,
        p_session_id,
        p_candidate_id,
        'canonical_preview_lines',
        contracted_payload.row_key,
        contracted_payload.row_ordinal,
        contracted_payload.promoted_row_json
          || jsonb_build_object(
            'preview_contract', contracted_payload.promoted_contract_json,
            'selection_allowed', true
          ),
        contracted_payload.timesheet_id,
        contracted_payload.key_type,
        contracted_payload.key_value,
        contracted_payload.promoted_selected,
        CASE WHEN contracted_payload.promoted_selected THEN 'SELECTED' ELSE 'UNSELECTED' END,
        'READY',
        COALESCE(v_session_row.version, 1),
        v_now,
        v_now
      FROM contracted_payload
      WHERE LOWER(BTRIM(COALESCE(contracted_payload.promoted_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(contracted_payload.promoted_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      ON CONFLICT (session_id, section, candidate_id, row_key)
      DO UPDATE
      SET row_ordinal = EXCLUDED.row_ordinal,
          row_json = EXCLUDED.row_json,
          timesheet_id = EXCLUDED.timesheet_id,
          key_type = EXCLUDED.key_type,
          key_value = EXCLUDED.key_value,
          selected = EXCLUDED.selected,
          selection_state = EXCLUDED.selection_state,
          status = 'READY',
          session_version = EXCLUDED.session_version,
          updated_at_utc = v_now;

      UPDATE public.banking_pay_workbench_preview_rows AS blocked_row
      SET status = 'SUPERSEDED',
          selected = false,
          selection_state = 'SUPERSEDED',
          row_json = COALESCE(blocked_row.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'selected', false,
              'selection_state', 'SUPERSEDED',
              'superseded_reason', 'POSITIVE_PAY_HEADROOM_AVAILABLE_AFTER_FINAL_MATERIALISATION',
              'materialisation_recovery_headroom_revalidated', true,
              'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE blocked_row.id IN (
        SELECT promotion.blocked_preview_row_id
        FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
      );

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = ready_row.row_json,
          updated_at_utc = v_now
      FROM public.banking_pay_workbench_preview_rows AS ready_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND ready_row.session_id = p_session_id
        AND ready_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        AND ready_row.row_key = line_work.line_key
        AND EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
          WHERE promotion.row_key = line_work.line_key
        );

      v_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id,
        true,
        'POST_MATERIALISATION_RECOVERY_HEADROOM_PROMOTION',
        false
      );

      SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
             COUNT(*)::integer
      INTO v_selected_preview_row_ids,
           v_selected_row_count
      FROM public.banking_pay_workbench_preview_rows AS selected_row
      WHERE selected_row.session_id = p_session_id
        AND selected_row.session_version = COALESCE(v_session_row.version, 1)
        AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
        AND COALESCE(selected_row.selected, false) = true
        AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

      v_selection_intent_mode := UPPER(BTRIM(COALESCE(
        v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
        ''
      )));

      UPDATE public.banking_pay_workbench_sessions AS session_row
      SET selected_row_count = COALESCE(v_selected_row_count, 0),
          server_selected_preview_row_ids = CASE
            WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
              OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
              THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
            ELSE session_row.server_selected_preview_row_ids
          END,
          progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_recovery_headroom_revalidation_at_utc', v_now::text,
              'last_recovery_headroom_revalidation_action', 'PROMOTED_RECOVERY_WITH_RETAINED_POSITIVE_PAY',
              'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
              'last_recovery_headroom_revalidation_promoted_count', COALESCE(v_promoted_count, 0),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE session_row.id = p_session_id;

      RETURN jsonb_build_object(
        'ok', true,
        'action', 'PROMOTED_RECOVERY_WITH_RETAINED_POSITIVE_PAY',
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
        'promoted_recovery_count', COALESCE(v_promoted_count, 0),
        'promoted_selected_count', COALESCE(v_promoted_selected_count, 0),
        'repaired_authority_scope_count', COALESCE(v_repaired_authority_scope_count, 0),
        'capped_ready_recovery_count', COALESCE(v_ready_recovery_capped_count, 0),
        'blocked_excess_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
        'selected_row_count', COALESCE(v_selected_row_count, 0),
        'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
        'demoted_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
        'post_draft_artifacts_touched', false,
        'payment_execution_started', false
      );
    END IF;

    IF COALESCE(v_ready_recovery_capped_count, 0) > 0
       OR COALESCE(v_ready_recovery_blocked_count, 0) > 0 THEN
      v_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id,
        true,
        'POST_MATERIALISATION_RECOVERY_HEADROOM_CAP',
        false
      );

      SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
             COUNT(*)::integer
      INTO v_selected_preview_row_ids,
           v_selected_row_count
      FROM public.banking_pay_workbench_preview_rows AS selected_row
      WHERE selected_row.session_id = p_session_id
        AND selected_row.session_version = COALESCE(v_session_row.version, 1)
        AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
        AND COALESCE(selected_row.selected, false) IS TRUE
        AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

      UPDATE public.banking_pay_workbench_sessions AS session_row
      SET selected_row_count = COALESCE(v_selected_row_count, 0),
          server_selected_preview_row_ids = CASE
            WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
              OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
              THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
            ELSE session_row.server_selected_preview_row_ids
          END,
          progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_recovery_headroom_revalidation_at_utc', v_now::text,
              'last_recovery_headroom_revalidation_action', 'CAPPED_READY_RECOVERY_TO_POSITIVE_HEADROOM',
              'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
              'last_recovery_headroom_revalidation_capped_count', COALESCE(v_ready_recovery_capped_count, 0),
              'last_recovery_headroom_revalidation_blocked_excess_count', COALESCE(v_ready_recovery_blocked_count, 0),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE session_row.id = p_session_id;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'action', CASE
        WHEN COALESCE(v_repaired_authority_scope_count, 0) > 0
          THEN 'REPAIRED_EXISTING_RECOVERY_AUTHORITY_SCOPE'
        ELSE 'RETAINED_POSITIVE_PAY_PRESENT'
      END,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
      'promoted_recovery_count', 0,
      'repaired_authority_scope_count', COALESCE(v_repaired_authority_scope_count, 0),
      'capped_ready_recovery_count', COALESCE(v_ready_recovery_capped_count, 0),
      'blocked_excess_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
      'selected_row_count', COALESCE(v_selected_row_count, 0),
      'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
      'demoted_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
      'post_draft_artifacts_touched', false,
      'payment_execution_started', false
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_zero_headroom_recovery;
  CREATE TEMP TABLE _tmp_pay_wb_zero_headroom_recovery ON COMMIT DROP AS
  SELECT ready_row.id AS ready_preview_row_id,
         ready_row.row_key AS ready_row_key,
         ready_row.row_json->>'finance_case_id' AS finance_case_id_text,
         UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) AS line_type,
         ready_row.row_ordinal,
         ready_row.timesheet_id,
         ready_row.key_type,
         ready_row.key_value,
         ready_row.row_key AS blocked_row_key,
         COALESCE(blocked_template.row_json, ready_row.row_json, '{}'::jsonb) AS base_row_json,
         CASE
           WHEN COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            AND ABS((ready_row.row_json->>'amount_ex_vat')::numeric) > 0
             THEN ROUND(ABS((ready_row.row_json->>'amount_ex_vat')::numeric), 2)
           WHEN COALESCE((
             SELECT SUM(
               CASE
                 WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                   THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                 ELSE 0::numeric
               END
             )
             FROM jsonb_array_elements(
               CASE
                 WHEN jsonb_typeof(ready_row.row_json->'case_components') = 'array'
                   THEN ready_row.row_json->'case_components'
                 ELSE '[]'::jsonb
               END
             ) AS component_row(value)
           ), 0) > 0
             THEN ROUND((
               SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
               FROM jsonb_array_elements(ready_row.row_json->'case_components') AS component_row(value)
               WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             ), 2)
           WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             THEN ROUND(ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric), 2)
           ELSE 0::numeric
         END::numeric(12,2) AS nominal_due_amount_ex_vat
  FROM public.banking_pay_workbench_preview_rows AS ready_row
  LEFT JOIN LATERAL (
    SELECT blocked_row.row_key,
           blocked_row.row_json
    FROM public.banking_pay_workbench_preview_rows AS blocked_row
    WHERE blocked_row.session_id = ready_row.session_id
      AND blocked_row.session_version = ready_row.session_version
      AND blocked_row.candidate_id = ready_row.candidate_id
      AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
      AND blocked_row.row_key = ready_row.row_key
    ORDER BY CASE WHEN UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY' THEN 0 ELSE 1 END,
             blocked_row.updated_at_utc DESC,
             blocked_row.id
    LIMIT 1
  ) AS blocked_template ON true
  WHERE ready_row.session_id = p_session_id
    AND ready_row.session_version = COALESCE(v_session_row.version, 1)
    AND ready_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
    AND ready_row.row_json->>'finance_case_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    AND UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) IN (
      'MANUAL_DEBT_RECOVERY',
      'OVERPAYMENT_RECOVERY',
      'LOAN_REPAYMENT',
      'PAYMENT_ADVANCE_REPAYMENT'
    )
    AND COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
    AND ROUND((ready_row.row_json->>'amount_ex_vat')::numeric, 2) < 0
  ORDER BY ready_row.row_ordinal,
           ready_row.id;

  SELECT COUNT(*)::integer
  INTO v_recovery_group_count
  FROM pg_temp._tmp_pay_wb_zero_headroom_recovery;

  IF COALESCE(v_recovery_group_count, 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'NO_READY_RECOVERY_TO_REVALIDATE',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
      'demoted_recovery_count', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    );
  END IF;

  INSERT INTO public.banking_pay_workbench_preview_rows (
    session_id,
    candidate_id,
    section,
    row_key,
    row_ordinal,
    row_json,
    timesheet_id,
    key_type,
    key_value,
    selected,
    selection_state,
    status,
    session_version,
    created_at_utc,
    updated_at_utc
  )
  SELECT
    p_session_id,
    p_candidate_id,
    'blocked_for_pay',
    recovery_row.blocked_row_key,
    recovery_row.row_ordinal,
    (
      recovery_row.base_row_json
      - 'source_basis_json'
      - 'frozen_source_basis_json'
      - 'frozen_component_snapshot_json'
      - 'finance_component_id'
      - 'materialised_from_line_work_id'
    )
    || jsonb_build_object(
      'line_key', recovery_row.blocked_row_key,
      'row_key', recovery_row.blocked_row_key,
      'presentation_line_id', recovery_row.blocked_row_key,
      'presentation_parent_line_id', NULL,
      'section', 'blocked_for_pay',
      'target_section', 'blocked_for_pay',
      'readiness_state', 'BLOCKED_FOR_PAY',
      'presentation_section', 'BLOCKED_FOR_PAY',
      'presentation_reason', 'NO_PAY_HEADROOM',
      'amount_ex_vat', 0,
      'preview_amount_ex_vat', 0,
      'amount_display', 0,
      'section_amount_ex_vat', 0,
      'section_amount_display', 0,
      'target_pay_ex_vat', 0,
      'ready_preview_amount_ex_vat', 0,
      'preview_component_amount_ex_vat', 0,
      'source_amount_ex_vat', 0,
      'source_reservation_amount_ex_vat', 0,
      'frozen_source_amount', 0,
      'frozen_target_amount_ex_vat', 0,
      'nominal_due_amount_ex_vat', recovery_row.nominal_due_amount_ex_vat,
      'recoverable_this_pay_run_ex_vat', 0,
      'draftable', false,
      'is_ready_for_draft', false,
      'selection_allowed', false,
      'is_excluded_from_allocation', true,
      'selected', false,
      'selection_state', 'NOT_SELECTABLE',
      'blocked_reason_codes', CASE
        WHEN jsonb_typeof(COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb)) <> 'array'
          THEN jsonb_build_array('NO_PAY_HEADROOM')
        WHEN COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
          THEN COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb)
        ELSE COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb) || jsonb_build_array('NO_PAY_HEADROOM')
      END,
      'materialisation_recovery_headroom_revalidated', true,
      'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
      'retained_positive_headroom_ex_vat', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    )
    || jsonb_build_object(
      'preview_contract', COALESCE(recovery_row.base_row_json->'preview_contract', '{}'::jsonb)
        || jsonb_build_object(
          'line_key', recovery_row.blocked_row_key,
          'amount_ex_vat', 0,
          'draftable', false,
          'is_ready_for_draft', false,
          'selection_allowed', false,
          'is_excluded_from_allocation', true,
          'target_section', 'blocked_for_pay',
          'presentation_section', 'BLOCKED_FOR_PAY'
        ),
      'case_resolution_summary', CASE
        WHEN jsonb_typeof(COALESCE(recovery_row.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
          THEN COALESCE(recovery_row.base_row_json->'case_resolution_summary', '{}'::jsonb)
            || jsonb_build_object('due_amount_ex_vat', 0)
        ELSE jsonb_build_object('due_amount_ex_vat', 0)
      END
    ),
    recovery_row.timesheet_id,
    recovery_row.key_type,
    recovery_row.key_value,
    false,
    'NOT_SELECTABLE',
    'READY',
    COALESCE(v_session_row.version, 1),
    v_now,
    v_now
  FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
  ON CONFLICT (session_id, section, candidate_id, row_key)
  DO UPDATE
  SET row_ordinal = EXCLUDED.row_ordinal,
      row_json = EXCLUDED.row_json,
      timesheet_id = EXCLUDED.timesheet_id,
      key_type = EXCLUDED.key_type,
      key_value = EXCLUDED.key_value,
      selected = false,
      selection_state = 'NOT_SELECTABLE',
      status = 'READY',
      session_version = EXCLUDED.session_version,
      updated_at_utc = v_now;

  GET DIAGNOSTICS v_demoted_count = ROW_COUNT;

  UPDATE public.banking_pay_workbench_preview_rows AS ready_recovery_row
  SET status = 'SUPERSEDED',
      selected = false,
      selection_state = 'SUPERSEDED',
      row_json = COALESCE(ready_recovery_row.row_json, '{}'::jsonb)
        || jsonb_build_object(
          'selected', false,
          'selection_state', 'SUPERSEDED',
          'materialisation_recovery_headroom_revalidated', true,
          'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
          'retained_positive_headroom_ex_vat', 0,
          'superseded_reason', 'NO_PAY_HEADROOM_AFTER_FINAL_MATERIALISATION',
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE ready_recovery_row.session_id = p_session_id
    AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
    AND ready_recovery_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
      WHERE recovery_row.ready_preview_row_id = ready_recovery_row.id
    );

  GET DIAGNOSTICS v_superseded_count = ROW_COUNT;

  UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
  SET result_row_json = COALESCE(line_work.result_row_json, '{}'::jsonb)
        || jsonb_build_object(
          'section', 'blocked_for_pay',
          'target_section', 'blocked_for_pay',
          'readiness_state', 'BLOCKED_FOR_PAY',
          'presentation_section', 'BLOCKED_FOR_PAY',
          'presentation_reason', 'NO_PAY_HEADROOM',
          'amount_ex_vat', 0,
          'preview_amount_ex_vat', 0,
          'amount_display', 0,
          'target_pay_ex_vat', 0,
          'recoverable_this_pay_run_ex_vat', 0,
          'draftable', false,
          'is_ready_for_draft', false,
          'selection_allowed', false,
          'is_excluded_from_allocation', true,
          'selected', false,
          'selection_state', 'NOT_SELECTABLE',
          'blocked_reason_codes', CASE
            WHEN jsonb_typeof(COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb)) <> 'array'
              THEN jsonb_build_array('NO_PAY_HEADROOM')
            WHEN COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
              THEN COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb)
            ELSE COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb) || jsonb_build_array('NO_PAY_HEADROOM')
          END,
          'materialisation_recovery_headroom_revalidated', true,
          'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
          'retained_positive_headroom_ex_vat', 0,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE line_work.session_id = p_session_id
    AND line_work.candidate_id = p_candidate_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
      WHERE recovery_row.ready_row_key = line_work.line_key
    );

  GET DIAGNOSTICS v_line_work_revalidated_count = ROW_COUNT;

  v_progress_json := public.pay_workbench_session_recompute_progress_counters(
    p_session_id,
    true,
    'POST_MATERIALISATION_RECOVERY_HEADROOM_REVALIDATION',
    false
  );

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_selected_preview_row_ids,
       v_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS selected_row
  WHERE selected_row.session_id = p_session_id
    AND selected_row.session_version = COALESCE(v_session_row.version, 1)
    AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
    AND COALESCE(selected_row.selected, false) = true
    AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

  v_selection_intent_mode := UPPER(BTRIM(COALESCE(
    v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
    ''
  )));

  UPDATE public.banking_pay_workbench_sessions AS session_row
  SET selected_row_count = COALESCE(v_selected_row_count, 0),
      server_selected_preview_row_ids = CASE
        WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
          OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
          THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
        ELSE session_row.server_selected_preview_row_ids
      END,
      progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_recovery_headroom_revalidation_at_utc', v_now::text,
          'last_recovery_headroom_revalidation_action', 'DEMOTED_ZERO_RETAINED_HEADROOM',
          'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
          'last_recovery_headroom_revalidation_demoted_count', COALESCE(v_demoted_count, 0),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE session_row.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'action', 'DEMOTED_ZERO_RETAINED_HEADROOM',
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
    'recovery_group_count', COALESCE(v_recovery_group_count, 0),
    'demoted_recovery_count', COALESCE(v_demoted_count, 0),
    'superseded_ready_recovery_count', COALESCE(v_superseded_count, 0),
    'line_work_revalidated_count', COALESCE(v_line_work_revalidated_count, 0),
    'selected_row_count', COALESCE(v_selected_row_count, 0),
    'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
    'post_draft_artifacts_touched', false,
    'payment_execution_started', false
  );
END;
$function$;

-- ---------------------------------------------------------------------------------------------------
-- 2d. Settings-OFF legacy branch, overload (uuid,uuid,jsonb): same order key
-- ---------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(p_session_id uuid, p_candidate_id uuid, p_options_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_nonterminal_line_count integer := 0;
  v_retained_positive_headroom numeric(12,2) := 0;
  v_recovery_group_count integer := 0;
  v_promoted_count integer := 0;
  v_promoted_selected_count integer := 0;
  v_repaired_authority_scope_count integer := 0;
  v_ready_recovery_capped_count integer := 0;
  v_ready_recovery_blocked_count integer := 0;
  v_demoted_count integer := 0;
  v_superseded_count integer := 0;
  v_line_work_revalidated_count integer := 0;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_row_count integer := 0;
  v_selection_intent_mode text := '';
  v_progress_json jsonb := '{}'::jsonb;
  v_scope_attestation jsonb := '{}'::jsonb;
  v_v3_overlay_result jsonb := '{}'::jsonb;
BEGIN
  -- BEGIN BANKING_PAY_MODAL_RECOVERY_SCOPE_VALIDATION_V2
  IF jsonb_typeof(p_options_json) IS DISTINCT FROM 'object'
     OR COALESCE(p_options_json->>'pay_channel_scope','ALL') NOT IN ('ALL','PAYE','UMBRELLA')
     OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_options_json) k(value) WHERE k.value<>'pay_channel_scope') THEN
    RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';
  END IF;
  -- END BANKING_PAY_MODAL_RECOVERY_SCOPE_VALIDATION_V2
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  SELECT COALESCE(scope_row.certified_preview_publication_attestation_json, '{}'::jsonb)
  INTO v_scope_attestation
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_NOT_IN_SCOPE',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  v_selection_intent_mode := UPPER(BTRIM(COALESCE(
    v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
    CASE
      WHEN COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
        THEN 'EXPLICIT_INCLUDE'
      ELSE 'IMPLICIT_ALL'
    END
  )));
  IF v_selection_intent_mode NOT IN ('IMPLICIT_ALL', 'EXPLICIT_INCLUDE') THEN
    v_selection_intent_mode := CASE
      WHEN COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
        THEN 'EXPLICIT_INCLUDE'
      ELSE 'IMPLICIT_ALL'
    END;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_nonterminal_line_count
  FROM public.banking_pay_workbench_candidate_line_work AS line_work
  WHERE line_work.session_id = p_session_id
    AND line_work.candidate_id = p_candidate_id
    AND UPPER(BTRIM(COALESCE(line_work.status, ''))) NOT IN (
      'MATERIALISED',
      'SKIPPED',
      'ERROR',
      'FAILED',
      'CANCELLED',
      'CANCELED',
      'SUPERSEDED',
      'RETIRED'
    );

  IF COALESCE(v_nonterminal_line_count, 0) > 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'DEFERRED_UNTIL_FINAL_MATERIALISATION',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'nonterminal_line_count', v_nonterminal_line_count,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    );
  END IF;

  -- BEGIN BANKING_PAY_MODAL_NON_V3_SCOPE_FENCE_V2
  IF COALESCE(p_options_json->>'pay_channel_scope','ALL')<>'ALL' AND NOT (
    COALESCE(v_scope_attestation->>'attestation_version','')='CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
    AND COALESCE(v_scope_attestation->>'contract_version','')='3'
    AND COALESCE(v_scope_attestation->>'semantic_contract_version','')='READY_TO_PAY_SEMANTIC_V2') THEN
    RAISE EXCEPTION 'BANKING_PAY_V2_DEPENDENCY_UNAVAILABLE' USING ERRCODE='P0001';
  END IF;
  -- END BANKING_PAY_MODAL_NON_V3_SCOPE_FENCE_V2
  -- V3 keeps the certified source/preview identity immutable.  Recovery
  -- readiness is a pre-Draft selection projection: it is recalculated from
  -- positive rows the candidate has actually selected, while the physical
  -- source-backed preview section remains unchanged for exact parity.
  IF v_scope_attestation->>'attestation_version' = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
     AND v_scope_attestation->>'contract_version' = '3'
     AND v_scope_attestation->>'semantic_contract_version' = 'READY_TO_PAY_SEMANTIC_V2' THEN
    v_v3_overlay_result := private.pay_workbench_recovery_selection_overlay_apply_v1(
      p_session_id,
      p_candidate_id,
      jsonb_build_object('reason', 'SELECTION_REVALIDATION') || p_options_json
    );

    RETURN COALESCE(v_v3_overlay_result, '{}'::jsonb)
      || jsonb_build_object(
        'legacy_physical_section_revalidation_skipped', true,
        'certified_source_preview_identity_preserved', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
  END IF;

  SELECT ROUND(COALESCE(SUM(
           CASE
             WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
               THEN GREATEST((preview_row.row_json->>'amount_ex_vat')::numeric, 0)
             ELSE 0::numeric
           END
         ), 0), 2)::numeric(12,2)
  INTO v_retained_positive_headroom
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.session_version = COALESCE(v_session_row.version, 1)
    AND preview_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(preview_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    AND (
      v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
      OR (
        COALESCE(preview_row.selected, false) IS TRUE
        AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
      )
      OR (
        LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
      )
    )
    AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', ''))) NOT IN (
      'MANUAL_DEBT_RECOVERY',
      'OVERPAYMENT_RECOVERY',
      'LOAN_REPAYMENT',
      'PAYMENT_ADVANCE_REPAYMENT'
    );

  IF COALESCE(v_retained_positive_headroom, 0) > 0 THEN
    /*
     * A recovery line may have been materialised before the candidate's final
     * positive correction carrier. In that order it is correctly emitted as
     * NO_PAY_HEADROOM, but the terminal candidate view is then stale once the
     * positive carrier exists. Reconcile the other direction here as well:
     * promote only rows whose sole blocker is NO_PAY_HEADROOM, allocate against
     * retained positive pay in the same pay channel, and leave every financial
     * amount sourced from the already-materialised pre-draft authority.
     */
    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_ready_recovery_allocation;
    CREATE TEMP TABLE _tmp_pay_wb_ready_recovery_allocation ON COMMIT DROP AS
    WITH positive_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          positive_row.row_json->>'pay_channel',
          positive_row.row_json->>'current_pay_method',
          positive_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN GREATEST((positive_row.row_json->>'amount_ex_vat')::numeric, 0)
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS positive_row
      WHERE positive_row.session_id = p_session_id
        AND positive_row.session_version = COALESCE(v_session_row.version, 1)
        AND positive_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(positive_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(positive_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
          OR (
            COALESCE(positive_row.selected, false) IS TRUE
            AND UPPER(BTRIM(COALESCE(positive_row.selection_state, ''))) = 'SELECTED'
          )
          OR (
            LOWER(BTRIM(COALESCE(positive_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND UPPER(BTRIM(COALESCE(positive_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
          )
        )
        AND UPPER(BTRIM(COALESCE(positive_row.row_json->>'line_type', positive_row.row_json->>'item_type', ''))) NOT IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
      GROUP BY UPPER(BTRIM(COALESCE(
        positive_row.row_json->>'pay_channel',
        positive_row.row_json->>'current_pay_method',
        positive_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), ready_recovery AS (
      SELECT
        ready_row.id AS ready_preview_row_id,
        ready_row.row_key,
        ready_row.row_ordinal,
        ready_row.timesheet_id,
        ready_row.key_type,
        ready_row.key_value,
        ready_row.selected,
        ready_row.selection_state,
        COALESCE(ready_row.row_json, '{}'::jsonb) AS base_row_json,
        UPPER(BTRIM(COALESCE(
          ready_row.row_json->>'pay_channel',
          ready_row.row_json->>'current_pay_method',
          ready_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(
          CASE
            -- A33 (critic finding 2): the nominal due is the row's own uncapped nominal_due_amount_ex_vat when it
            -- carries one, the same basis private.pay_workbench_recovery_selection_overlay_apply_v1 uses. The
            -- per-component preview due below is the figure ALREADY capped by the earlier running total, so an
            -- exclusion could never release headroom to it (GBP80 due stayed GBP20). Rows without the field keep
            -- the previous derivation unchanged.
            WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric) > 0
              THEN ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            WHEN COALESCE((
              SELECT SUM(
                CASE
                  WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                    THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                  ELSE 0::numeric
                END
              )
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(ready_row.row_json->'case_components') = 'array'
                    THEN ready_row.row_json->'case_components'
                  ELSE '[]'::jsonb
                END
              ) AS component_row(value)
            ), 0) > 0
              THEN (
                SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
                FROM jsonb_array_elements(ready_row.row_json->'case_components') AS component_row(value)
                WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              )
            WHEN COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((ready_row.row_json->>'amount_ex_vat')::numeric) > 0
              THEN ABS((ready_row.row_json->>'amount_ex_vat')::numeric)
            WHEN COALESCE(ready_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((ready_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}')::numeric)
            WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            ELSE 0::numeric
          END,
          2
        )::numeric(12,2) AS nominal_due_amount_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS ready_row
      WHERE ready_row.session_id = p_session_id
        AND ready_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(ready_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
        AND ROUND((ready_row.row_json->>'amount_ex_vat')::numeric, 2) < 0
    ), ranked_recovery AS (
      SELECT
        ready_recovery.*,
        COALESCE(positive_by_channel.positive_headroom_ex_vat, 0)::numeric(12,2) AS positive_headroom_ex_vat,
        COALESCE(SUM(
          CASE
            -- A33 (critic finding 2; APPROVED rule, roadmap "Product behaviour that remains fixed"): on this non-V3
            -- branch too, a repayment the Office explicitly excluded consumes no headroom, exactly as A30 M1 does in
            -- private.pay_workbench_recovery_selection_overlay_apply_v1 (GBP100 headroom, first GBP80 excluded, second
            -- GBP80 included -> the second receives GBP80, not GBP20). Every A33 edit in this function is marked A33.
            WHEN UPPER(BTRIM(COALESCE(ready_recovery.base_row_json->>'selection_user_override', ''))) = 'UNSELECTED'
              THEN 0::numeric
            ELSE ready_recovery.nominal_due_amount_ex_vat
          END
        ) OVER (
          PARTITION BY ready_recovery.pay_channel
          -- A34 (user rulings 25 Q6-A and 31; Worker BT): oldest debt first -- the SAME key and tie-break as the V3
          -- overlay and the canonical builder (Stage 3 WP3): creation date and time, a loan by its payout; ties by
          -- finance case id.  Was: row_ordinal, id (effectively reference order).
          ORDER BY private.s3p_recovery_order_key_v1(CASE WHEN ready_recovery.base_row_json->>'finance_case_id'
                     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                     THEN (ready_recovery.base_row_json->>'finance_case_id')::uuid END) NULLS LAST,
                   ready_recovery.base_row_json->>'finance_case_id', ready_recovery.row_ordinal, ready_recovery.ready_preview_row_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::numeric(12,2) AS prior_nominal_due_amount_ex_vat
      FROM ready_recovery
      LEFT JOIN positive_by_channel
        ON positive_by_channel.pay_channel = ready_recovery.pay_channel
      WHERE ready_recovery.pay_channel IN ('PAYE', 'UMBRELLA')
        AND ready_recovery.nominal_due_amount_ex_vat > 0
    ), allocated_recovery AS (
      SELECT
        ranked_recovery.*,
        ROUND(LEAST(
          ranked_recovery.nominal_due_amount_ex_vat,
          GREATEST(
            ranked_recovery.positive_headroom_ex_vat - ranked_recovery.prior_nominal_due_amount_ex_vat,
            0
          )
        ), 2)::numeric(12,2) AS recoverable_amount_ex_vat
      FROM ranked_recovery
    )
    SELECT
      allocated_recovery.*,
      ROUND(SUM(allocated_recovery.recoverable_amount_ex_vat) OVER (
        PARTITION BY allocated_recovery.pay_channel
      ), 2)::numeric(12,2) AS channel_recoverable_amount_ex_vat
    FROM allocated_recovery;

    WITH capped_source AS (
      SELECT
        allocation.ready_preview_row_id,
        allocation.base_row_json
          || jsonb_build_object(
            'amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'preview_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'amount_display', -allocation.recoverable_amount_ex_vat,
            'section_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'section_amount_display', -allocation.recoverable_amount_ex_vat,
            'target_pay_ex_vat', -allocation.recoverable_amount_ex_vat,
            'ready_preview_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'preview_component_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'nominal_due_amount_ex_vat', allocation.nominal_due_amount_ex_vat,
            'recoverable_this_pay_run_ex_vat', allocation.recoverable_amount_ex_vat,
            'recovery_group_recoverable_this_pay_run_ex_vat', allocation.channel_recoverable_amount_ex_vat,
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
            'retained_positive_headroom_ex_vat', allocation.positive_headroom_ex_vat,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'case_resolution_summary', CASE
              WHEN jsonb_typeof(COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
                THEN COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)
                  || jsonb_build_object('due_amount_ex_vat', allocation.recoverable_amount_ex_vat)
              ELSE jsonb_build_object('due_amount_ex_vat', allocation.recoverable_amount_ex_vat)
            END
          ) AS capped_row_json
      FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
      WHERE allocation.recoverable_amount_ex_vat > 0
    ), contracted_source AS (
      SELECT
        capped_source.ready_preview_row_id,
        capped_source.capped_row_json,
        public.pay_workbench_preview_line_contract_ok(
          p_line_json => capped_source.capped_row_json,
          p_economic_key_json => COALESCE(capped_source.capped_row_json->'economic_key', '{}'::jsonb),
          p_target_section => 'canonical_preview_lines'
        ) AS capped_contract_json
      FROM capped_source
    )
    UPDATE public.banking_pay_workbench_preview_rows AS ready_row
    SET row_json = contracted_source.capped_row_json
          || jsonb_build_object(
            'preview_contract', contracted_source.capped_contract_json,
            'selection_allowed', true
          ),
        updated_at_utc = v_now
    FROM contracted_source
    WHERE ready_row.id = contracted_source.ready_preview_row_id
      AND LOWER(BTRIM(COALESCE(contracted_source.capped_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(contracted_source.capped_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    GET DIAGNOSTICS v_ready_recovery_capped_count = ROW_COUNT;

    INSERT INTO public.banking_pay_workbench_preview_rows (
      session_id,
      candidate_id,
      section,
      row_key,
      row_ordinal,
      row_json,
      timesheet_id,
      key_type,
      key_value,
      selected,
      selection_state,
      status,
      session_version,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_session_id,
      p_candidate_id,
      'blocked_for_pay',
      allocation.row_key,
      allocation.row_ordinal,
      (
        allocation.base_row_json
        - 'source_basis_json'
        - 'frozen_source_basis_json'
        - 'frozen_component_snapshot_json'
        - 'finance_component_id'
        - 'materialised_from_line_work_id'
      )
      || jsonb_build_object(
        'line_key', allocation.row_key,
        'row_key', allocation.row_key,
        'presentation_line_id', allocation.row_key,
        'section', 'blocked_for_pay',
        'target_section', 'blocked_for_pay',
        'readiness_state', 'BLOCKED_FOR_PAY',
        'presentation_section', 'BLOCKED_FOR_PAY',
        'presentation_reason', 'NO_PAY_HEADROOM',
        'amount_ex_vat', 0,
        'preview_amount_ex_vat', 0,
        'amount_display', 0,
        'section_amount_ex_vat', 0,
        'section_amount_display', 0,
        'target_pay_ex_vat', 0,
        'ready_preview_amount_ex_vat', 0,
        'preview_component_amount_ex_vat', 0,
        'recoverable_this_pay_run_ex_vat', 0,
        'nominal_due_amount_ex_vat', allocation.nominal_due_amount_ex_vat,
        'draftable', false,
        'is_ready_for_draft', false,
        'selection_allowed', false,
        'is_excluded_from_allocation', true,
        'selected', false,
        'selection_state', 'NOT_SELECTABLE',
        'blocked_reason_codes', jsonb_build_array('NO_PAY_HEADROOM'),
        'materialisation_recovery_headroom_revalidated', true,
        'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
        'retained_positive_headroom_ex_vat', allocation.positive_headroom_ex_vat,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
        'case_resolution_summary', CASE
          WHEN jsonb_typeof(COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
            THEN COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)
              || jsonb_build_object('due_amount_ex_vat', 0)
          ELSE jsonb_build_object('due_amount_ex_vat', 0)
        END
      )
      || jsonb_build_object(
        'preview_contract', COALESCE(allocation.base_row_json->'preview_contract', '{}'::jsonb)
          || jsonb_build_object(
            'line_key', allocation.row_key,
            'amount_ex_vat', 0,
            'draftable', false,
            'is_ready_for_draft', false,
            'selection_allowed', false,
            'is_excluded_from_allocation', true,
            'target_section', 'blocked_for_pay',
            'presentation_section', 'BLOCKED_FOR_PAY'
          )
      ),
      allocation.timesheet_id,
      allocation.key_type,
      allocation.key_value,
      false,
      'NOT_SELECTABLE',
      'READY',
      COALESCE(v_session_row.version, 1),
      v_now,
      v_now
    FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
    WHERE allocation.recoverable_amount_ex_vat <= 0
    ON CONFLICT (session_id, section, candidate_id, row_key)
    DO UPDATE
    SET row_ordinal = EXCLUDED.row_ordinal,
        row_json = EXCLUDED.row_json,
        timesheet_id = EXCLUDED.timesheet_id,
        key_type = EXCLUDED.key_type,
        key_value = EXCLUDED.key_value,
        selected = false,
        selection_state = 'NOT_SELECTABLE',
        status = 'READY',
        session_version = EXCLUDED.session_version,
        updated_at_utc = v_now;

    GET DIAGNOSTICS v_ready_recovery_blocked_count = ROW_COUNT;

    UPDATE public.banking_pay_workbench_preview_rows AS ready_row
    SET status = 'SUPERSEDED',
        selected = false,
        selection_state = 'SUPERSEDED',
        row_json = COALESCE(ready_row.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'selected', false,
            'selection_state', 'SUPERSEDED',
            'superseded_reason', 'RECOVERY_EXCEEDS_SELECTED_POSITIVE_HEADROOM',
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
          ),
        updated_at_utc = v_now
    WHERE ready_row.id IN (
      SELECT allocation.ready_preview_row_id
      FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
      WHERE allocation.recoverable_amount_ex_vat <= 0
    );

    IF COALESCE(v_ready_recovery_capped_count, 0) > 0
       OR COALESCE(v_ready_recovery_blocked_count, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = active_row.row_json,
          updated_at_utc = v_now
      FROM (
        SELECT ready_row.row_key, ready_row.row_json
        FROM public.banking_pay_workbench_preview_rows AS ready_row
        WHERE ready_row.session_id = p_session_id
          AND ready_row.session_version = COALESCE(v_session_row.version, 1)
          AND ready_row.candidate_id = p_candidate_id
          AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
          AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        UNION ALL
        SELECT blocked_row.row_key, blocked_row.row_json
        FROM public.banking_pay_workbench_preview_rows AS blocked_row
        WHERE blocked_row.session_id = p_session_id
          AND blocked_row.session_version = COALESCE(v_session_row.version, 1)
          AND blocked_row.candidate_id = p_candidate_id
          AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
          AND UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY'
      ) AS active_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND line_work.line_key = active_row.row_key
        AND EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
          WHERE allocation.row_key = line_work.line_key
        );
    END IF;

    WITH repair_source AS (
      SELECT
        ready_recovery_row.id,
        ready_recovery_row.row_json
          || jsonb_build_object(
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text
          ) AS repaired_row_json
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'materialisation_recovery_headroom_revalidated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'line_type', ready_recovery_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    ), contracted_repair AS (
      SELECT
        repair_source.id,
        repair_source.repaired_row_json,
        public.pay_workbench_preview_line_contract_ok(
          p_line_json => repair_source.repaired_row_json,
          p_economic_key_json => COALESCE(repair_source.repaired_row_json->'economic_key', '{}'::jsonb),
          p_target_section => 'canonical_preview_lines'
        ) AS repaired_contract_json
      FROM repair_source
    )
    UPDATE public.banking_pay_workbench_preview_rows AS ready_recovery_row
    SET row_json = contracted_repair.repaired_row_json
          || jsonb_build_object(
            'preview_contract', contracted_repair.repaired_contract_json,
            'selection_allowed', true
          ),
        updated_at_utc = v_now
    FROM contracted_repair
    WHERE ready_recovery_row.id = contracted_repair.id
      AND LOWER(BTRIM(COALESCE(contracted_repair.repaired_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(contracted_repair.repaired_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    GET DIAGNOSTICS v_repaired_authority_scope_count = ROW_COUNT;

    IF COALESCE(v_repaired_authority_scope_count, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = ready_recovery_row.row_json,
          updated_at_utc = v_now
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND ready_recovery_row.updated_at_utc = v_now
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
        AND line_work.line_key = ready_recovery_row.row_key;
    END IF;

    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_positive_headroom_recovery;
    CREATE TEMP TABLE _tmp_pay_wb_positive_headroom_recovery ON COMMIT DROP AS
    WITH gross_positive_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          preview_row.row_json->>'pay_channel',
          preview_row.row_json->>'current_pay_method',
          preview_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN GREATEST((preview_row.row_json->>'amount_ex_vat')::numeric, 0)
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = p_session_id
        AND preview_row.session_version = COALESCE(v_session_row.version, 1)
        AND preview_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(preview_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
          OR (
            COALESCE(preview_row.selected, false) IS TRUE
            AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
          )
          OR (
            LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
          )
        )
        AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', ''))) NOT IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
      GROUP BY UPPER(BTRIM(COALESCE(
        preview_row.row_json->>'pay_channel',
        preview_row.row_json->>'current_pay_method',
        preview_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), ready_recovery_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          ready_recovery_row.row_json->>'pay_channel',
          ready_recovery_row.row_json->>'current_pay_method',
          ready_recovery_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(ready_recovery_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS(LEAST((ready_recovery_row.row_json->>'amount_ex_vat')::numeric, 0))
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS allocated_recovery_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'line_type', ready_recovery_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        -- A33 (critic finding 2): an explicitly excluded READY repayment consumes no headroom here either, so the
        -- NO_PAY_HEADROOM promotion pass below can give the released headroom to a later included repayment.
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'selection_user_override', ''))) <> 'UNSELECTED'
      GROUP BY UPPER(BTRIM(COALESCE(
        ready_recovery_row.row_json->>'pay_channel',
        ready_recovery_row.row_json->>'current_pay_method',
        ready_recovery_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), positive_by_channel AS (
      SELECT
        gross_positive.pay_channel,
        ROUND(GREATEST(
          gross_positive.positive_headroom_ex_vat
            - COALESCE(ready_recovery.allocated_recovery_ex_vat, 0),
          0
        ), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM gross_positive_by_channel AS gross_positive
      LEFT JOIN ready_recovery_by_channel AS ready_recovery
        ON ready_recovery.pay_channel = gross_positive.pay_channel
    ), blocked_recovery AS (
      SELECT
        blocked_row.id AS blocked_preview_row_id,
        blocked_row.candidate_id,
        blocked_row.row_key,
        blocked_row.row_ordinal,
        blocked_row.timesheet_id,
        blocked_row.key_type,
        blocked_row.key_value,
        blocked_row.row_json AS base_row_json,
        UPPER(BTRIM(COALESCE(
          blocked_row.row_json->>'pay_channel',
          blocked_row.row_json->>'current_pay_method',
          blocked_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(
          CASE
            -- A33 (critic finding 2): the nominal due is the row's own uncapped nominal_due_amount_ex_vat when it
            -- carries one, the same basis private.pay_workbench_recovery_selection_overlay_apply_v1 uses. The
            -- per-component preview due below is the figure ALREADY capped by the earlier running total, so an
            -- exclusion could never release headroom to it (GBP80 due stayed GBP20). Rows without the field keep
            -- the previous derivation unchanged.
            WHEN COALESCE(blocked_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((blocked_row.row_json->>'nominal_due_amount_ex_vat')::numeric) > 0
              THEN ABS((blocked_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            WHEN COALESCE((
              SELECT SUM(
                CASE
                  WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                    THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                  ELSE 0::numeric
                END
              )
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(blocked_row.row_json->'case_components') = 'array'
                    THEN blocked_row.row_json->'case_components'
                  ELSE '[]'::jsonb
                END
              ) AS component_row(value)
            ), 0) > 0
              THEN (
                SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
                FROM jsonb_array_elements(blocked_row.row_json->'case_components') AS component_row(value)
                WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              )
            WHEN COALESCE(blocked_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((blocked_row.row_json->>'amount_ex_vat')::numeric) > 0
              THEN ABS((blocked_row.row_json->>'amount_ex_vat')::numeric)
            WHEN COALESCE(blocked_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((blocked_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}')::numeric)
            WHEN COALESCE(blocked_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((blocked_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            ELSE 0::numeric
          END,
          2
        )::numeric(12,2) AS nominal_due_amount_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS blocked_row
      WHERE blocked_row.session_id = p_session_id
        AND blocked_row.session_version = COALESCE(v_session_row.version, 1)
        AND blocked_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
        AND UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(blocked_row.row_json->>'line_type', blocked_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND (
          UPPER(BTRIM(COALESCE(blocked_row.row_json->>'presentation_reason', ''))) = 'NO_PAY_HEADROOM'
          OR COALESCE(blocked_row.row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
        )
        AND LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_is_blocked', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_needs_resolution_now', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_resolution_satisfied_now', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR UPPER(BTRIM(COALESCE(blocked_row.row_json->>'resolution_state', ''))) = 'RESOLVED'
          OR LOWER(BTRIM(COALESCE(blocked_row.row_json->>'is_case_resolution_satisfied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        )
        AND NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(blocked_row.row_json->'blocked_reason_codes') = 'array'
                THEN blocked_row.row_json->'blocked_reason_codes'
              ELSE '[]'::jsonb
            END
          ) AS blocked_code(value)
          WHERE UPPER(BTRIM(blocked_code.value)) <> 'NO_PAY_HEADROOM'
        )
    ), ranked_recovery AS (
      SELECT
        blocked_recovery.*,
        COALESCE(positive_by_channel.positive_headroom_ex_vat, 0)::numeric(12,2) AS positive_headroom_ex_vat,
        COALESCE(SUM(
          CASE
            -- A33 (critic finding 2; APPROVED rule, roadmap "Product behaviour that remains fixed"): on this non-V3
            -- branch too, a repayment the Office explicitly excluded consumes no headroom, exactly as A30 M1 does in
            -- private.pay_workbench_recovery_selection_overlay_apply_v1 (GBP100 headroom, first GBP80 excluded, second
            -- GBP80 included -> the second receives GBP80, not GBP20). Every A33 edit in this function is marked A33.
            WHEN UPPER(BTRIM(COALESCE(blocked_recovery.base_row_json->>'selection_user_override', ''))) = 'UNSELECTED'
              THEN 0::numeric
            ELSE blocked_recovery.nominal_due_amount_ex_vat
          END
        ) OVER (
          PARTITION BY blocked_recovery.pay_channel
          -- A34 (user rulings 25 Q6-A and 31; Worker BT): oldest debt first -- the SAME key and tie-break as the V3
          -- overlay and the canonical builder (Stage 3 WP3): creation date and time, a loan by its payout; ties by
          -- finance case id.  Was: row_ordinal, id (effectively reference order).
          ORDER BY private.s3p_recovery_order_key_v1(CASE WHEN blocked_recovery.base_row_json->>'finance_case_id'
                     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                     THEN (blocked_recovery.base_row_json->>'finance_case_id')::uuid END) NULLS LAST,
                   blocked_recovery.base_row_json->>'finance_case_id', blocked_recovery.row_ordinal, blocked_recovery.blocked_preview_row_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::numeric(12,2) AS prior_nominal_due_amount_ex_vat
      FROM blocked_recovery
      LEFT JOIN positive_by_channel
        ON positive_by_channel.pay_channel = blocked_recovery.pay_channel
      WHERE blocked_recovery.pay_channel IN ('PAYE', 'UMBRELLA')
        AND ROUND(COALESCE(blocked_recovery.nominal_due_amount_ex_vat, 0), 2) > 0
    ), allocated_recovery AS (
      SELECT
        ranked_recovery.*,
        ROUND(LEAST(
          ranked_recovery.nominal_due_amount_ex_vat,
          GREATEST(
            ranked_recovery.positive_headroom_ex_vat - ranked_recovery.prior_nominal_due_amount_ex_vat,
            0
          )
        ), 2)::numeric(12,2) AS recoverable_amount_ex_vat
      FROM ranked_recovery
    )
    SELECT
      allocated_recovery.*,
      COALESCE(existing_ready.id, gen_random_uuid()) AS promoted_preview_row_id,
      CASE
        WHEN UPPER(BTRIM(COALESCE(
          allocated_recovery.base_row_json->>'selection_user_override',
          existing_ready.row_json->>'selection_user_override',
          ''
        ))) = 'UNSELECTED'
          THEN false
        ELSE true
      END AS promoted_selected
    FROM allocated_recovery
    LEFT JOIN public.banking_pay_workbench_preview_rows AS existing_ready
      ON existing_ready.session_id = p_session_id
     AND existing_ready.session_version = COALESCE(v_session_row.version, 1)
     AND existing_ready.candidate_id = p_candidate_id
     AND LOWER(BTRIM(COALESCE(existing_ready.section, ''))) = 'canonical_preview_lines'
     AND existing_ready.row_key = allocated_recovery.row_key
    WHERE allocated_recovery.recoverable_amount_ex_vat > 0;

    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE promoted_selected)::integer
    INTO v_promoted_count,
         v_promoted_selected_count
    FROM pg_temp._tmp_pay_wb_positive_headroom_recovery;

    IF COALESCE(v_promoted_count, 0) > 0 THEN
      WITH promoted_payload AS (
        SELECT
          promotion.*,
          jsonb_strip_nulls(
            (
              promotion.base_row_json
              - 'blocked_reason_codes'
              - 'superseded_reason'
              - 'materialisation_recovery_headroom_revalidated'
              - 'materialisation_recovery_headroom_revalidated_at_utc'
            )
            || jsonb_build_object(
              'preview_row_id', promotion.promoted_preview_row_id::text,
              'line_id', promotion.promoted_preview_row_id::text,
              'section', 'canonical_preview_lines',
              'target_section', 'canonical_preview_lines',
              'readiness_state', 'READY',
              'presentation_section', 'READY_TO_PAY',
              'presentation_reason', NULL,
              'amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'preview_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'amount_display', -promotion.recoverable_amount_ex_vat,
              'section_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'section_amount_display', -promotion.recoverable_amount_ex_vat,
              'target_pay_ex_vat', -promotion.recoverable_amount_ex_vat,
              'ready_preview_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'preview_component_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'nominal_due_amount_ex_vat', promotion.nominal_due_amount_ex_vat,
              'recoverable_this_pay_run_ex_vat', promotion.recoverable_amount_ex_vat,
              'draftable', true,
              'is_ready_for_draft', true,
              'selection_allowed', true,
              'is_excluded_from_allocation', false,
              'selected', promotion.promoted_selected,
              'selection_state', CASE WHEN promotion.promoted_selected THEN 'SELECTED' ELSE 'UNSELECTED' END,
              'selection_origin', CASE
                WHEN UPPER(BTRIM(COALESCE(promotion.base_row_json->>'selection_user_override', ''))) = 'UNSELECTED'
                  THEN 'USER_EXPLICIT_DESELECT'
                ELSE 'SERVER_DEFAULT_NEWLY_ELIGIBLE'
              END,
              'materialisation_recovery_headroom_revalidated', true,
              'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
              'retained_positive_headroom_ex_vat', promotion.positive_headroom_ex_vat,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
            || jsonb_build_object(
              'case_resolution_summary', CASE
                WHEN jsonb_typeof(COALESCE(promotion.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
                  THEN COALESCE(promotion.base_row_json->'case_resolution_summary', '{}'::jsonb)
                    || jsonb_build_object('due_amount_ex_vat', promotion.recoverable_amount_ex_vat)
                ELSE jsonb_build_object('due_amount_ex_vat', promotion.recoverable_amount_ex_vat)
              END
            )
          ) AS promoted_row_json
        FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
      ), contracted_payload AS (
        SELECT
          promoted_payload.*,
          public.pay_workbench_preview_line_contract_ok(
            p_line_json => promoted_payload.promoted_row_json,
            p_economic_key_json => COALESCE(promoted_payload.promoted_row_json->'economic_key', '{}'::jsonb),
            p_target_section => 'canonical_preview_lines'
          ) AS promoted_contract_json
        FROM promoted_payload
      )
      INSERT INTO public.banking_pay_workbench_preview_rows (
        id,
        session_id,
        candidate_id,
        section,
        row_key,
        row_ordinal,
        row_json,
        timesheet_id,
        key_type,
        key_value,
        selected,
        selection_state,
        status,
        session_version,
        created_at_utc,
        updated_at_utc
      )
      SELECT
        contracted_payload.promoted_preview_row_id,
        p_session_id,
        p_candidate_id,
        'canonical_preview_lines',
        contracted_payload.row_key,
        contracted_payload.row_ordinal,
        contracted_payload.promoted_row_json
          || jsonb_build_object(
            'preview_contract', contracted_payload.promoted_contract_json,
            'selection_allowed', true
          ),
        contracted_payload.timesheet_id,
        contracted_payload.key_type,
        contracted_payload.key_value,
        contracted_payload.promoted_selected,
        CASE WHEN contracted_payload.promoted_selected THEN 'SELECTED' ELSE 'UNSELECTED' END,
        'READY',
        COALESCE(v_session_row.version, 1),
        v_now,
        v_now
      FROM contracted_payload
      WHERE LOWER(BTRIM(COALESCE(contracted_payload.promoted_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(contracted_payload.promoted_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      ON CONFLICT (session_id, section, candidate_id, row_key)
      DO UPDATE
      SET row_ordinal = EXCLUDED.row_ordinal,
          row_json = EXCLUDED.row_json,
          timesheet_id = EXCLUDED.timesheet_id,
          key_type = EXCLUDED.key_type,
          key_value = EXCLUDED.key_value,
          selected = EXCLUDED.selected,
          selection_state = EXCLUDED.selection_state,
          status = 'READY',
          session_version = EXCLUDED.session_version,
          updated_at_utc = v_now;

      UPDATE public.banking_pay_workbench_preview_rows AS blocked_row
      SET status = 'SUPERSEDED',
          selected = false,
          selection_state = 'SUPERSEDED',
          row_json = COALESCE(blocked_row.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'selected', false,
              'selection_state', 'SUPERSEDED',
              'superseded_reason', 'POSITIVE_PAY_HEADROOM_AVAILABLE_AFTER_FINAL_MATERIALISATION',
              'materialisation_recovery_headroom_revalidated', true,
              'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE blocked_row.id IN (
        SELECT promotion.blocked_preview_row_id
        FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
      );

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = ready_row.row_json,
          updated_at_utc = v_now
      FROM public.banking_pay_workbench_preview_rows AS ready_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND ready_row.session_id = p_session_id
        AND ready_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        AND ready_row.row_key = line_work.line_key
        AND EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
          WHERE promotion.row_key = line_work.line_key
        );

      v_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id,
        true,
        'POST_MATERIALISATION_RECOVERY_HEADROOM_PROMOTION',
        false
      );

      SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
             COUNT(*)::integer
      INTO v_selected_preview_row_ids,
           v_selected_row_count
      FROM public.banking_pay_workbench_preview_rows AS selected_row
      WHERE selected_row.session_id = p_session_id
        AND selected_row.session_version = COALESCE(v_session_row.version, 1)
        AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
        AND COALESCE(selected_row.selected, false) = true
        AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

      v_selection_intent_mode := UPPER(BTRIM(COALESCE(
        v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
        ''
      )));

      UPDATE public.banking_pay_workbench_sessions AS session_row
      SET selected_row_count = COALESCE(v_selected_row_count, 0),
          server_selected_preview_row_ids = CASE
            WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
              OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
              THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
            ELSE session_row.server_selected_preview_row_ids
          END,
          progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_recovery_headroom_revalidation_at_utc', v_now::text,
              'last_recovery_headroom_revalidation_action', 'PROMOTED_RECOVERY_WITH_RETAINED_POSITIVE_PAY',
              'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
              'last_recovery_headroom_revalidation_promoted_count', COALESCE(v_promoted_count, 0),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE session_row.id = p_session_id;

      RETURN jsonb_build_object(
        'ok', true,
        'action', 'PROMOTED_RECOVERY_WITH_RETAINED_POSITIVE_PAY',
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
        'promoted_recovery_count', COALESCE(v_promoted_count, 0),
        'promoted_selected_count', COALESCE(v_promoted_selected_count, 0),
        'repaired_authority_scope_count', COALESCE(v_repaired_authority_scope_count, 0),
        'capped_ready_recovery_count', COALESCE(v_ready_recovery_capped_count, 0),
        'blocked_excess_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
        'selected_row_count', COALESCE(v_selected_row_count, 0),
        'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
        'demoted_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
        'post_draft_artifacts_touched', false,
        'payment_execution_started', false
      );
    END IF;

    IF COALESCE(v_ready_recovery_capped_count, 0) > 0
       OR COALESCE(v_ready_recovery_blocked_count, 0) > 0 THEN
      v_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id,
        true,
        'POST_MATERIALISATION_RECOVERY_HEADROOM_CAP',
        false
      );

      SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
             COUNT(*)::integer
      INTO v_selected_preview_row_ids,
           v_selected_row_count
      FROM public.banking_pay_workbench_preview_rows AS selected_row
      WHERE selected_row.session_id = p_session_id
        AND selected_row.session_version = COALESCE(v_session_row.version, 1)
        AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
        AND COALESCE(selected_row.selected, false) IS TRUE
        AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

      UPDATE public.banking_pay_workbench_sessions AS session_row
      SET selected_row_count = COALESCE(v_selected_row_count, 0),
          server_selected_preview_row_ids = CASE
            WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
              OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
              THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
            ELSE session_row.server_selected_preview_row_ids
          END,
          progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_recovery_headroom_revalidation_at_utc', v_now::text,
              'last_recovery_headroom_revalidation_action', 'CAPPED_READY_RECOVERY_TO_POSITIVE_HEADROOM',
              'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
              'last_recovery_headroom_revalidation_capped_count', COALESCE(v_ready_recovery_capped_count, 0),
              'last_recovery_headroom_revalidation_blocked_excess_count', COALESCE(v_ready_recovery_blocked_count, 0),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE session_row.id = p_session_id;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'action', CASE
        WHEN COALESCE(v_repaired_authority_scope_count, 0) > 0
          THEN 'REPAIRED_EXISTING_RECOVERY_AUTHORITY_SCOPE'
        ELSE 'RETAINED_POSITIVE_PAY_PRESENT'
      END,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
      'promoted_recovery_count', 0,
      'repaired_authority_scope_count', COALESCE(v_repaired_authority_scope_count, 0),
      'capped_ready_recovery_count', COALESCE(v_ready_recovery_capped_count, 0),
      'blocked_excess_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
      'selected_row_count', COALESCE(v_selected_row_count, 0),
      'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
      'demoted_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
      'post_draft_artifacts_touched', false,
      'payment_execution_started', false
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_zero_headroom_recovery;
  CREATE TEMP TABLE _tmp_pay_wb_zero_headroom_recovery ON COMMIT DROP AS
  SELECT ready_row.id AS ready_preview_row_id,
         ready_row.row_key AS ready_row_key,
         ready_row.row_json->>'finance_case_id' AS finance_case_id_text,
         UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) AS line_type,
         ready_row.row_ordinal,
         ready_row.timesheet_id,
         ready_row.key_type,
         ready_row.key_value,
         ready_row.row_key AS blocked_row_key,
         COALESCE(blocked_template.row_json, ready_row.row_json, '{}'::jsonb) AS base_row_json,
         CASE
           WHEN COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            AND ABS((ready_row.row_json->>'amount_ex_vat')::numeric) > 0
             THEN ROUND(ABS((ready_row.row_json->>'amount_ex_vat')::numeric), 2)
           WHEN COALESCE((
             SELECT SUM(
               CASE
                 WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                   THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                 ELSE 0::numeric
               END
             )
             FROM jsonb_array_elements(
               CASE
                 WHEN jsonb_typeof(ready_row.row_json->'case_components') = 'array'
                   THEN ready_row.row_json->'case_components'
                 ELSE '[]'::jsonb
               END
             ) AS component_row(value)
           ), 0) > 0
             THEN ROUND((
               SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
               FROM jsonb_array_elements(ready_row.row_json->'case_components') AS component_row(value)
               WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             ), 2)
           WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             THEN ROUND(ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric), 2)
           ELSE 0::numeric
         END::numeric(12,2) AS nominal_due_amount_ex_vat
  FROM public.banking_pay_workbench_preview_rows AS ready_row
  LEFT JOIN LATERAL (
    SELECT blocked_row.row_key,
           blocked_row.row_json
    FROM public.banking_pay_workbench_preview_rows AS blocked_row
    WHERE blocked_row.session_id = ready_row.session_id
      AND blocked_row.session_version = ready_row.session_version
      AND blocked_row.candidate_id = ready_row.candidate_id
      AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
      AND blocked_row.row_key = ready_row.row_key
    ORDER BY CASE WHEN UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY' THEN 0 ELSE 1 END,
             blocked_row.updated_at_utc DESC,
             blocked_row.id
    LIMIT 1
  ) AS blocked_template ON true
  WHERE ready_row.session_id = p_session_id
    AND ready_row.session_version = COALESCE(v_session_row.version, 1)
    AND ready_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
    AND ready_row.row_json->>'finance_case_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    AND UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) IN (
      'MANUAL_DEBT_RECOVERY',
      'OVERPAYMENT_RECOVERY',
      'LOAN_REPAYMENT',
      'PAYMENT_ADVANCE_REPAYMENT'
    )
    AND COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
    AND ROUND((ready_row.row_json->>'amount_ex_vat')::numeric, 2) < 0
  ORDER BY ready_row.row_ordinal,
           ready_row.id;

  SELECT COUNT(*)::integer
  INTO v_recovery_group_count
  FROM pg_temp._tmp_pay_wb_zero_headroom_recovery;

  IF COALESCE(v_recovery_group_count, 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'NO_READY_RECOVERY_TO_REVALIDATE',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
      'demoted_recovery_count', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    );
  END IF;

  INSERT INTO public.banking_pay_workbench_preview_rows (
    session_id,
    candidate_id,
    section,
    row_key,
    row_ordinal,
    row_json,
    timesheet_id,
    key_type,
    key_value,
    selected,
    selection_state,
    status,
    session_version,
    created_at_utc,
    updated_at_utc
  )
  SELECT
    p_session_id,
    p_candidate_id,
    'blocked_for_pay',
    recovery_row.blocked_row_key,
    recovery_row.row_ordinal,
    (
      recovery_row.base_row_json
      - 'source_basis_json'
      - 'frozen_source_basis_json'
      - 'frozen_component_snapshot_json'
      - 'finance_component_id'
      - 'materialised_from_line_work_id'
    )
    || jsonb_build_object(
      'line_key', recovery_row.blocked_row_key,
      'row_key', recovery_row.blocked_row_key,
      'presentation_line_id', recovery_row.blocked_row_key,
      'presentation_parent_line_id', NULL,
      'section', 'blocked_for_pay',
      'target_section', 'blocked_for_pay',
      'readiness_state', 'BLOCKED_FOR_PAY',
      'presentation_section', 'BLOCKED_FOR_PAY',
      'presentation_reason', 'NO_PAY_HEADROOM',
      'amount_ex_vat', 0,
      'preview_amount_ex_vat', 0,
      'amount_display', 0,
      'section_amount_ex_vat', 0,
      'section_amount_display', 0,
      'target_pay_ex_vat', 0,
      'ready_preview_amount_ex_vat', 0,
      'preview_component_amount_ex_vat', 0,
      'source_amount_ex_vat', 0,
      'source_reservation_amount_ex_vat', 0,
      'frozen_source_amount', 0,
      'frozen_target_amount_ex_vat', 0,
      'nominal_due_amount_ex_vat', recovery_row.nominal_due_amount_ex_vat,
      'recoverable_this_pay_run_ex_vat', 0,
      'draftable', false,
      'is_ready_for_draft', false,
      'selection_allowed', false,
      'is_excluded_from_allocation', true,
      'selected', false,
      'selection_state', 'NOT_SELECTABLE',
      'blocked_reason_codes', CASE
        WHEN jsonb_typeof(COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb)) <> 'array'
          THEN jsonb_build_array('NO_PAY_HEADROOM')
        WHEN COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
          THEN COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb)
        ELSE COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb) || jsonb_build_array('NO_PAY_HEADROOM')
      END,
      'materialisation_recovery_headroom_revalidated', true,
      'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
      'retained_positive_headroom_ex_vat', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    )
    || jsonb_build_object(
      'preview_contract', COALESCE(recovery_row.base_row_json->'preview_contract', '{}'::jsonb)
        || jsonb_build_object(
          'line_key', recovery_row.blocked_row_key,
          'amount_ex_vat', 0,
          'draftable', false,
          'is_ready_for_draft', false,
          'selection_allowed', false,
          'is_excluded_from_allocation', true,
          'target_section', 'blocked_for_pay',
          'presentation_section', 'BLOCKED_FOR_PAY'
        ),
      'case_resolution_summary', CASE
        WHEN jsonb_typeof(COALESCE(recovery_row.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
          THEN COALESCE(recovery_row.base_row_json->'case_resolution_summary', '{}'::jsonb)
            || jsonb_build_object('due_amount_ex_vat', 0)
        ELSE jsonb_build_object('due_amount_ex_vat', 0)
      END
    ),
    recovery_row.timesheet_id,
    recovery_row.key_type,
    recovery_row.key_value,
    false,
    'NOT_SELECTABLE',
    'READY',
    COALESCE(v_session_row.version, 1),
    v_now,
    v_now
  FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
  ON CONFLICT (session_id, section, candidate_id, row_key)
  DO UPDATE
  SET row_ordinal = EXCLUDED.row_ordinal,
      row_json = EXCLUDED.row_json,
      timesheet_id = EXCLUDED.timesheet_id,
      key_type = EXCLUDED.key_type,
      key_value = EXCLUDED.key_value,
      selected = false,
      selection_state = 'NOT_SELECTABLE',
      status = 'READY',
      session_version = EXCLUDED.session_version,
      updated_at_utc = v_now;

  GET DIAGNOSTICS v_demoted_count = ROW_COUNT;

  UPDATE public.banking_pay_workbench_preview_rows AS ready_recovery_row
  SET status = 'SUPERSEDED',
      selected = false,
      selection_state = 'SUPERSEDED',
      row_json = COALESCE(ready_recovery_row.row_json, '{}'::jsonb)
        || jsonb_build_object(
          'selected', false,
          'selection_state', 'SUPERSEDED',
          'materialisation_recovery_headroom_revalidated', true,
          'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
          'retained_positive_headroom_ex_vat', 0,
          'superseded_reason', 'NO_PAY_HEADROOM_AFTER_FINAL_MATERIALISATION',
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE ready_recovery_row.session_id = p_session_id
    AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
    AND ready_recovery_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
      WHERE recovery_row.ready_preview_row_id = ready_recovery_row.id
    );

  GET DIAGNOSTICS v_superseded_count = ROW_COUNT;

  UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
  SET result_row_json = COALESCE(line_work.result_row_json, '{}'::jsonb)
        || jsonb_build_object(
          'section', 'blocked_for_pay',
          'target_section', 'blocked_for_pay',
          'readiness_state', 'BLOCKED_FOR_PAY',
          'presentation_section', 'BLOCKED_FOR_PAY',
          'presentation_reason', 'NO_PAY_HEADROOM',
          'amount_ex_vat', 0,
          'preview_amount_ex_vat', 0,
          'amount_display', 0,
          'target_pay_ex_vat', 0,
          'recoverable_this_pay_run_ex_vat', 0,
          'draftable', false,
          'is_ready_for_draft', false,
          'selection_allowed', false,
          'is_excluded_from_allocation', true,
          'selected', false,
          'selection_state', 'NOT_SELECTABLE',
          'blocked_reason_codes', CASE
            WHEN jsonb_typeof(COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb)) <> 'array'
              THEN jsonb_build_array('NO_PAY_HEADROOM')
            WHEN COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
              THEN COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb)
            ELSE COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb) || jsonb_build_array('NO_PAY_HEADROOM')
          END,
          'materialisation_recovery_headroom_revalidated', true,
          'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
          'retained_positive_headroom_ex_vat', 0,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE line_work.session_id = p_session_id
    AND line_work.candidate_id = p_candidate_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
      WHERE recovery_row.ready_row_key = line_work.line_key
    );

  GET DIAGNOSTICS v_line_work_revalidated_count = ROW_COUNT;

  v_progress_json := public.pay_workbench_session_recompute_progress_counters(
    p_session_id,
    true,
    'POST_MATERIALISATION_RECOVERY_HEADROOM_REVALIDATION',
    false
  );

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_selected_preview_row_ids,
       v_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS selected_row
  WHERE selected_row.session_id = p_session_id
    AND selected_row.session_version = COALESCE(v_session_row.version, 1)
    AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
    AND COALESCE(selected_row.selected, false) = true
    AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

  v_selection_intent_mode := UPPER(BTRIM(COALESCE(
    v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
    ''
  )));

  UPDATE public.banking_pay_workbench_sessions AS session_row
  SET selected_row_count = COALESCE(v_selected_row_count, 0),
      server_selected_preview_row_ids = CASE
        WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
          OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
          THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
        ELSE session_row.server_selected_preview_row_ids
      END,
      progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_recovery_headroom_revalidation_at_utc', v_now::text,
          'last_recovery_headroom_revalidation_action', 'DEMOTED_ZERO_RETAINED_HEADROOM',
          'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
          'last_recovery_headroom_revalidation_demoted_count', COALESCE(v_demoted_count, 0),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE session_row.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'action', 'DEMOTED_ZERO_RETAINED_HEADROOM',
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
    'recovery_group_count', COALESCE(v_recovery_group_count, 0),
    'demoted_recovery_count', COALESCE(v_demoted_count, 0),
    'superseded_ready_recovery_count', COALESCE(v_superseded_count, 0),
    'line_work_revalidated_count', COALESCE(v_line_work_revalidated_count, 0),
    'selected_row_count', COALESCE(v_selected_row_count, 0),
    'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
    'post_draft_artifacts_touched', false,
    'payment_execution_started', false
  );
END;
$function$;

-- ---------------------------------------------------------------------------------------------------
-- 1b. Office reason text for the legacy blocker
-- ---------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION private.pay_workbench_modal_blocked_presentation_v2(p_row jsonb, p_task jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
 n jsonb;summary jsonb;headroom jsonb;component jsonb;components jsonb;ss jsonb;
 line_type text;codes text[];state text;until_date text;reason text;message_id text;condition_text text;
 amount numeric;nominal numeric;outstanding numeric;original numeric;component_outstanding numeric;
 outstanding_total numeric:=0;component_count integer:=0;recoverable numeric;row_amount numeric;section_amount numeric;
 has_amount boolean;code text;
BEGIN
 IF jsonb_typeof(p_row) IS DISTINCT FROM 'object' OR jsonb_typeof(p_task) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';END IF;
 IF private.pay_workbench_modal_hidden_v2(p_row) THEN RETURN NULL;END IF;
 n:=CASE WHEN jsonb_typeof(p_row->'row_json')='object' THEN p_row->'row_json'
   WHEN jsonb_typeof(p_row->'rowJson')='object' THEN p_row->'rowJson' ELSE '{}'::jsonb END;
 summary:=CASE WHEN jsonb_typeof(p_row->'case_resolution_summary')='object' THEN p_row->'case_resolution_summary'
   WHEN jsonb_typeof(n->'case_resolution_summary')='object' THEN n->'case_resolution_summary' ELSE '{}'::jsonb END;
 headroom:=CASE WHEN jsonb_typeof(p_row->'selection_recovery_headroom_v1')='object' THEN p_row->'selection_recovery_headroom_v1'
   WHEN jsonb_typeof(n->'selection_recovery_headroom_v1')='object' THEN n->'selection_recovery_headroom_v1' ELSE '{}'::jsonb END;
 line_type:=UPPER(BTRIM(COALESCE(NULLIF(p_row->>'line_type',''),NULLIF(p_row->>'lineType',''),
   NULLIF(n->>'line_type',''),n->>'lineType','')));
 SELECT COALESCE(array_agg(DISTINCT upper(btrim(value))) FILTER(WHERE NULLIF(btrim(value),'') IS NOT NULL),ARRAY[]::text[])
 INTO codes FROM (
  SELECT unnest(private.pay_workbench_modal_bank_blockers_v2(p_row)||private.pay_workbench_modal_bank_blockers_v2(n)
    ||private.pay_workbench_modal_bank_blockers_v2(summary)) AS value
  UNION ALL SELECT unnest(ARRAY[p_row->>'presentation_reason',p_row->>'presentationReason',n->>'presentation_reason',n->>'presentationReason'])
 ) reasons;
 row_amount:=private.pay_workbench_modal_first_display_number_v2(private.pay_workbench_modal_display_fields_v2(p_row,ARRAY[
  'amount_display','amountDisplay','amount_ex_vat','amountExVat','preview_amount_ex_vat','previewAmountExVat',
  'ready_preview_amount_ex_vat','readyPreviewAmountExVat','component_amount_ex_vat','componentAmountExVat']));
 section_amount:=COALESCE(private.pay_workbench_modal_first_display_number_v2(
  private.pay_workbench_modal_display_fields_v2(p_row,ARRAY['section_amount_display','sectionAmountDisplay',
    'section_amount_ex_vat','sectionAmountExVat','section_non_segment_amount_ex_vat','sectionNonSegmentAmountExVat'])),row_amount);
 has_amount:=section_amount IS NOT NULL;
 nominal:=private.pay_workbench_modal_first_display_number_v2(ARRAY[p_row->'nominal_due_amount_ex_vat',p_row->'nominalDueAmountExVat',
  n->'nominal_due_amount_ex_vat',n->'nominalDueAmountExVat',summary->'nominal_due_amount_ex_vat',summary->'nominalDueAmountExVat'],true);
 IF has_amount THEN amount:=private.pay_workbench_modal_line_display_amount_v2(p_row);END IF;
 IF line_type='OVERPAYMENT_RECOVERY' THEN
  -- Same outstanding components, precedence and two-decimal display as
  -- getOverpaymentRecoveryPresentation. No allocation/write is performed.
  SELECT COALESCE(jsonb_agg(item.value ORDER BY src.ord,item.ord),'[]'::jsonb) INTO components
  FROM unnest(ARRAY[p_row->'case_components',p_row->'caseComponents',n->'case_components',n->'caseComponents'])
   WITH ORDINALITY src(value,ord)
  CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(src.value)='array' THEN src.value ELSE '[]'::jsonb END)
   WITH ORDINALITY item(value,ord) WHERE jsonb_typeof(item.value)='object';
  FOR component IN SELECT value FROM jsonb_array_elements(components) LOOP
   original:=ABS(ROUND(private.pay_workbench_modal_first_display_number_v2(ARRAY[
    component->'resolved_target_amount_ex_vat',component->'resolvedTargetAmountExVat',component->'target_pay_ex_vat',
    component->'targetPayExVat',component->'source_amount',component->'sourceAmount',component->'source_pay_ex_vat',
    component->'sourcePayExVat',component->'remaining_source_amount',component->'remainingSourceAmount'],true),2));
   component_outstanding:=ABS(ROUND(private.pay_workbench_modal_first_display_number_v2(ARRAY[
    component->'target_outstanding_ex_vat',component->'targetOutstandingExVat',component->'remaining_source_amount',
    component->'remainingSourceAmount',to_jsonb(original)],true),2));
   IF original IS NOT NULL OR component_outstanding IS NOT NULL THEN
    component_count:=component_count+1;outstanding_total:=outstanding_total+COALESCE(component_outstanding,0);
   END IF;
  END LOOP;
  recoverable:=ABS(ROUND(COALESCE(private.pay_workbench_modal_first_display_number_v2(ARRAY[
   p_row->'recoverable_this_pay_run_ex_vat',p_row->'recoverableThisPayRunExVat',n->'recoverable_this_pay_run_ex_vat',
   n->'recoverableThisPayRunExVat',headroom->'recoverable_amount_ex_vat',headroom->'recoverableAmountExVat',
   to_jsonb(row_amount),to_jsonb(section_amount),'0'::jsonb],true),0),2));
  outstanding:=CASE WHEN component_count>0 THEN outstanding_total ELSE ABS(ROUND(COALESCE(
   private.pay_workbench_modal_first_display_number_v2(ARRAY[p_row->'nominal_due_amount_ex_vat',p_row->'nominalDueAmountExVat',
    n->'nominal_due_amount_ex_vat',n->'nominalDueAmountExVat',p_row->'case_outstanding_amount',p_row->'caseOutstandingAmount',
    n->'case_outstanding_amount',n->'caseOutstandingAmount',p_row->'outstanding_amount',p_row->'outstandingAmount',
    n->'outstanding_amount',n->'outstandingAmount',summary->'nominal_due_amount_ex_vat',summary->'nominalDueAmountExVat',
    to_jsonb(recoverable)],true),0),2)) END;
  IF outstanding>0 AND recoverable=0 AND ('NO_PAY_HEADROOM'=ANY(codes) OR 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING'=ANY(codes)) THEN amount:=outstanding;END IF;
 END IF;
 ss:=CASE WHEN jsonb_typeof(p_row->'snooze_state')='object' THEN p_row->'snooze_state' ELSE '{}'::jsonb END;
 state:=UPPER(BTRIM(COALESCE(NULLIF(ss->>'state',''),CASE WHEN jsonb_typeof(p_row->'snooze_state')='string'
   THEN NULLIF(p_row->>'snooze_state','') END,p_row->>'blocked_snooze_state','')));
 until_date:=BTRIM(COALESCE(NULLIF(ss->>'snooze_until_date',''),p_row->>'snooze_until_date',''));
 IF state NOT IN ('','NONE','NOT_SNOOZED','CLEARED') AND until_date<>'' THEN
  IF until_date !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR to_char(until_date::date,'YYYY-MM-DD')<>until_date THEN
   RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';END IF;
  reason:='Snoozed until '||to_char(until_date::date,'DD/MM/YYYY')||'.';condition_text:=reason;
 ELSIF p_task->>'task_family'='SOURCE_PROGRESS' THEN
  IF p_task->>'state' IS DISTINCT FROM 'BLOCKED' OR p_task->>'title' IS NULL
   OR p_task->>'title' NOT IN ('Refresh failed','Payment preview needs refreshing.',
     'Too many Timesheets to prepare in one pass') THEN
   RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';END IF;
  -- A26 (AC-F1): the over-envelope Candidate is shown as a Blocked row with its reason, never silently removed.
  reason:=p_task->>'title';condition_text:=CASE WHEN p_task->>'title'='Too many Timesheets to prepare in one pass'
   THEN 'Banking Pay cannot yet prepare this many Timesheets for one Candidate at once. None of this Candidate''s payments are shown or can be included in a Draft until it is prepared.'
   ELSE 'Payment preview needs refreshing.' END;amount:=NULL;
 ELSIF p_task->>'task_family'='BANK_ACCOUNT' THEN
  IF p_task->>'state' IS DISTINCT FROM 'BLOCKED' THEN
   RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';END IF;
  message_id:=p_task->>'title_message_id';reason:=private.pay_workbench_modal_task_title_v2(message_id);
  IF reason IS NULL THEN
   code:=p_task->>'code';
   IF code IN ('BANK_TARGET_CHANGED','BANK_RESULT_CHANGED') THEN
    message_id:='MSG-096';reason:='The bank details changed or could not be confirmed. Refresh Banking Pay and try again.';
   ELSE message_id:='MSG-090';reason:='Payment issue not identified';END IF;
  END IF;
  condition_text:=reason;
 ELSIF 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING'=ANY(codes) THEN
  -- A34 (Worker BT): a legacy finance case without component records is shown, not dropped and not a failure.
  reason:='Legacy finance case needs component records - Office review';
  condition_text:='This older finance case has no component records, so CloudTMS cannot tell which pay it belongs to. '
   ||'Nothing is deducted for it in this pay run; the Candidate''s other payments are not affected. '
   ||'Office must review the case (record its components or close it); it will then be offered again.';
  IF COALESCE(amount,0)=0 AND nominal IS NOT NULL THEN amount:=nominal;END IF;
 ELSIF 'NO_PAY_HEADROOM'=ANY(codes) THEN
  message_id:='MSG-031';reason:='Insufficient funds to deduct';
  condition_text:='There is not enough pay available in this run to make this deduction.';
 ELSIF line_type='DO_NOT_PAY' THEN
  reason:='This line is currently marked do not pay.';condition_text:=reason;
 ELSIF line_type='BLOCKED_TIMESHEET' THEN
  message_id:='MSG-093';
  reason:='This Timesheet payment cannot be included because CloudTMS could not confirm its current status. Open the Timesheet or refresh Banking Pay.';
  condition_text:=reason;
 ELSE message_id:='MSG-090';reason:='Payment issue not identified';END IF;
 IF message_id='MSG-090' THEN
  condition_text:='CloudTMS could not identify why this payment is blocked. It will not be included. Refresh Banking Pay; if it remains blocked, contact support.';
 END IF;
 RETURN jsonb_build_object('reason_message_id',message_id,'reason',reason,'clear_condition',condition_text,
  'clear_condition_message_id',CASE message_id WHEN 'MSG-031' THEN 'MSG-032' WHEN 'MSG-090' THEN 'MSG-091' ELSE message_id END,
  'affected_display_amount',CASE WHEN amount IS NOT NULL THEN (ROUND(amount,2)::numeric(20,2))::text END,
  'nominal_due_amount',CASE WHEN nominal IS NOT NULL THEN (ROUND(nominal,2)::numeric(20,2))::text END,
  'diagnostic_codes',to_jsonb(codes));
END;
$function$;

-- ---------------------------------------------------------------------------------------------------
-- 4. V8 constituent freeze: the certificate section and key rule (ruling 29)
-- ---------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pay_workbench_draft_certificate_constituent_ref_page_v8(p_operation_id uuid, p_after_ordinal integer DEFAULT NULL::integer, p_limit integer DEFAULT 256, p_expected_previous_receipt_sha256 text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_scope private.banking_pay_draft_frozen_certificate_scopes_v8%ROWTYPE;
  v_link private.banking_pay_workbench_settled_certificate_operation_links_v8%ROWTYPE;
  v_reference_result jsonb;
  v_existing private.banking_pay_draft_frozen_stage_receipts_v8%ROWTYPE;
  v_previous private.banking_pay_draft_frozen_stage_receipts_v8%ROWTYPE;
  v_stage_kind constant text := 'CERTIFICATE_CONSTITUENT_REFS';
  v_limit integer := COALESCE(p_limit, 256);
  v_page_sequence integer;
  v_candidate_count integer;
  v_row_count integer;
  v_next_after integer;
  v_has_more boolean;
  v_page_preimage text;
  v_page_digest text;
  v_request_preimage text;
  v_request_digest text;
  v_receipt_preimage text;
  v_receipt_digest text;
  v_canonical_bytes integer;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_OPERATION_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = '{"code":"WORKBENCH_CERTIFICATE_OPERATION_REQUIRED"}';
  END IF;
  IF v_limit < 1 OR v_limit > 256 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PAGE_LIMIT_INVALID'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'WORKBENCH_CERTIFICATE_PAGE_LIMIT_INVALID', 'limit', v_limit)::text;
  END IF;
  IF p_after_ordinal IS NOT NULL AND p_after_ordinal < 0 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PAGE_CURSOR_INVALID'
      USING ERRCODE = 'P0001', DETAIL = '{"code":"WORKBENCH_CERTIFICATE_PAGE_CURSOR_INVALID"}';
  END IF;
  IF p_expected_previous_receipt_sha256 IS NOT NULL
     AND p_expected_previous_receipt_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PAGE_RECEIPT_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = '{"code":"WORKBENCH_CERTIFICATE_PAGE_RECEIPT_MISMATCH"}';
  END IF;

  SELECT scope_row.*
  INTO v_scope
  FROM private.banking_pay_draft_frozen_certificate_scopes_v8 AS scope_row
  WHERE scope_row.operation_id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_NOT_FOUND'
      USING ERRCODE = 'P0001', DETAIL = '{"code":"WORKBENCH_CERTIFICATE_NOT_FOUND"}';
  END IF;
  IF v_scope.freeze_state <> 'STAGING' THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_STAGE_ALREADY_FROZEN'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'WORKBENCH_CERTIFICATE_STAGE_ALREADY_FROZEN', 'freeze_state', v_scope.freeze_state)::text;
  END IF;

  SELECT link_row.*
  INTO v_link
  FROM private.banking_pay_workbench_settled_certificate_operation_links_v8 AS link_row
  WHERE link_row.operation_id = p_operation_id;
  IF NOT FOUND OR v_link.certificate_uuid IS DISTINCT FROM v_scope.certificate_uuid THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_IDENTITY_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = '{"code":"WORKBENCH_CERTIFICATE_IDENTITY_MISMATCH"}';
  END IF;
  v_reference_result := public.pay_workbench_settled_certificate_reference_validate_v8(
    p_operation_id, v_link.certification_id, v_link.overall_digest_sha256, 'PAGE');
  IF COALESCE((v_reference_result->>'ok')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SESSION_SUPERSEDED'
      USING ERRCODE = 'P0001', DETAIL = '{"code":"WORKBENCH_CERTIFICATE_SESSION_SUPERSEDED"}';
  END IF;

  v_request_preimage := '{"after_ordinal":' || COALESCE(pg_catalog.to_jsonb(p_after_ordinal)::text, 'null')
    || ',"expected_previous_receipt_sha256":' || COALESCE(pg_catalog.to_jsonb(p_expected_previous_receipt_sha256)::text, 'null')
    || ',"operation_id":' || pg_catalog.to_jsonb(p_operation_id::text)::text
    || ',"pay_channel_scope":' || pg_catalog.to_jsonb(v_scope.pay_channel_scope)::text
    || ',"requested_limit":' || v_limit::text
    || ',"stage_kind":' || pg_catalog.to_jsonb(v_stage_kind)::text || '}';
  v_request_digest := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(v_request_preimage, 'UTF8'), 'sha256'), 'hex');

  SELECT receipt_row.*
  INTO v_existing
  FROM private.banking_pay_draft_frozen_stage_receipts_v8 AS receipt_row
  WHERE receipt_row.operation_id = p_operation_id
    AND receipt_row.stage_kind = v_stage_kind
    AND receipt_row.after_ordinal IS NOT DISTINCT FROM p_after_ordinal;

  IF FOUND THEN
    IF v_existing.requested_limit IS DISTINCT FROM v_limit
       OR v_existing.expected_previous_receipt_sha256 IS DISTINCT FROM p_expected_previous_receipt_sha256
       OR v_existing.request_preimage_digest_sha256 IS DISTINCT FROM v_request_digest THEN
      RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PAGE_REQUEST_CONFLICT'
        USING ERRCODE = 'P0001', DETAIL = '{"code":"WORKBENCH_CERTIFICATE_PAGE_REQUEST_CONFLICT"}';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'operation_id', p_operation_id,
      'stage_kind', v_stage_kind,
      'page_sequence', v_existing.page_sequence,
      'after_ordinal', v_existing.after_ordinal,
      'row_count', v_existing.row_count,
      'canonical_byte_count', v_existing.canonical_byte_count,
      'page_receipt_digest_sha256', v_existing.receipt_digest_sha256,
      'next_after_ordinal', v_existing.next_after_ordinal,
      'has_more', v_existing.has_more,
      'terminal_sentinel_present', v_existing.terminal_sentinel_present,
      'stage_total_count', v_scope.constituent_count,
      'stage_total_digest_sha256', v_scope.selected_constituents_digest_sha256,
      'replayed', true
    );
  END IF;

  SELECT COALESCE(pg_catalog.max(receipt_row.page_sequence), -1) + 1
  INTO v_page_sequence
  FROM private.banking_pay_draft_frozen_stage_receipts_v8 AS receipt_row
  WHERE receipt_row.operation_id = p_operation_id
    AND receipt_row.stage_kind = v_stage_kind;

  IF v_page_sequence = 0 THEN
    IF p_after_ordinal IS NOT NULL OR p_expected_previous_receipt_sha256 IS NOT NULL THEN
      RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PAGE_CURSOR_INVALID'
        USING ERRCODE = 'P0001', DETAIL = '{"code":"WORKBENCH_CERTIFICATE_PAGE_CURSOR_INVALID"}';
    END IF;
  ELSE
    SELECT receipt_row.*
    INTO v_previous
    FROM private.banking_pay_draft_frozen_stage_receipts_v8 AS receipt_row
    WHERE receipt_row.operation_id = p_operation_id
      AND receipt_row.stage_kind = v_stage_kind
      AND receipt_row.page_sequence = v_page_sequence - 1;
    IF NOT FOUND
       OR NOT v_previous.has_more
       OR v_previous.next_after_ordinal IS DISTINCT FROM p_after_ordinal
       OR v_previous.receipt_digest_sha256 IS DISTINCT FROM p_expected_previous_receipt_sha256 THEN
      RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PAGE_RECEIPT_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = '{"code":"WORKBENCH_CERTIFICATE_PAGE_RECEIPT_MISMATCH"}';
    END IF;
  END IF;

  WITH page_with_sentinel AS (
    SELECT entry.constituent_ordinal
    FROM private.banking_pay_workbench_settled_certificate_entries_v8 AS entry
    WHERE entry.certificate_uuid = v_scope.certificate_uuid
      AND (v_scope.pay_channel_scope = 'ALL' OR entry.resolved_pay_channel = v_scope.pay_channel_scope)
      AND entry.constituent_ordinal > COALESCE(p_after_ordinal, -1)
    ORDER BY entry.constituent_ordinal
    LIMIT (v_limit + 1)
  )
  SELECT pg_catalog.count(*)::integer
  INTO v_candidate_count
  FROM page_with_sentinel;

  v_row_count := LEAST(v_candidate_count, v_limit);
  v_has_more := v_candidate_count > v_limit;

  WITH page_rows AS (
    SELECT entry.constituent_ordinal
    FROM private.banking_pay_workbench_settled_certificate_entries_v8 AS entry
    WHERE entry.certificate_uuid = v_scope.certificate_uuid
      AND (v_scope.pay_channel_scope = 'ALL' OR entry.resolved_pay_channel = v_scope.pay_channel_scope)
      AND entry.constituent_ordinal > COALESCE(p_after_ordinal, -1)
    ORDER BY entry.constituent_ordinal
    LIMIT v_limit
  )
  SELECT pg_catalog.max(page_row.constituent_ordinal),
         '[' || COALESCE(pg_catalog.string_agg(
           '{"constituent_ordinal":' || page_row.constituent_ordinal::text || '}',
           ',' ORDER BY page_row.constituent_ordinal), '') || ']'
  INTO v_next_after, v_page_preimage
  FROM page_rows AS page_row;

  v_canonical_bytes := pg_catalog.octet_length(v_page_preimage);
  IF v_canonical_bytes > 524288 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PAGE_BYTES_EXCEEDED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object('code', 'WORKBENCH_CERTIFICATE_PAGE_BYTES_EXCEEDED', 'canonical_byte_count', v_canonical_bytes)::text;
  END IF;
  v_page_digest := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(v_page_preimage, 'UTF8'), 'sha256'), 'hex');

  INSERT INTO private.banking_pay_draft_frozen_constituent_refs_v8(
    operation_id, certificate_uuid, constituent_ordinal, staged_page_sequence
  )
  SELECT p_operation_id, v_scope.certificate_uuid, entry.constituent_ordinal, v_page_sequence
  FROM private.banking_pay_workbench_settled_certificate_entries_v8 AS entry
  WHERE entry.certificate_uuid = v_scope.certificate_uuid
    AND (v_scope.pay_channel_scope = 'ALL' OR entry.resolved_pay_channel = v_scope.pay_channel_scope)
    AND entry.constituent_ordinal > COALESCE(p_after_ordinal, -1)
  ORDER BY entry.constituent_ordinal
  LIMIT v_limit;

  WITH selected_entries AS (
    SELECT entry.*
    FROM private.banking_pay_workbench_settled_certificate_entries_v8 AS entry
    WHERE entry.certificate_uuid = v_scope.certificate_uuid
      AND (v_scope.pay_channel_scope = 'ALL' OR entry.resolved_pay_channel = v_scope.pay_channel_scope)
      AND entry.constituent_ordinal > COALESCE(p_after_ordinal, -1)
    ORDER BY entry.constituent_ordinal
    LIMIT v_limit
  ), frozen_payloads AS (
    SELECT entry.constituent_ordinal,
      entry.certificate_uuid,
      entry.materialised_preview_row_id AS preview_row_id,
      entry.candidate_id,
      entry.resolved_pay_channel,
      entry.timesheet_id,
      NULLIF(pg_catalog.btrim(COALESCE(preview_row.row_json->>'finance_case_id', '')), '')::uuid AS finance_case_id,
      entry.row_key,
      preview_row.row_ordinal,
      pg_catalog.jsonb_strip_nulls(
        preview_row.row_json
        || pg_catalog.jsonb_build_object(
          'source', 'banking_pay_workbench_preview_rows',
          'preview_row_id', entry.materialised_preview_row_id::text,
          'preview_row_pk', entry.materialised_preview_row_id::text,
          'row_key', entry.row_key,
          'row_ordinal', preview_row.row_ordinal,
          'candidate_id', entry.candidate_id::text,
          'timesheet_id', CASE WHEN entry.timesheet_id IS NULL THEN NULL ELSE entry.timesheet_id::text END,
          'finance_case_id', preview_row.row_json->>'finance_case_id',
          'finance_component_id', preview_row.row_json->>'finance_component_id',
          'line_type', preview_row.row_json->>'line_type',
          'case_type', preview_row.row_json->>'case_type',
          'item_direction', preview_row.row_json->>'item_direction',
          'pay_channel', entry.resolved_pay_channel,
          'section', 'canonical_preview_lines',
          'selection_state', 'SELECTED',
          'status', 'READY',
          'amount_ex_vat', entry.canonical_amount_ex_vat::numeric,
          'key_type', entry.economic_key_type,
          'key_value', entry.economic_key_value,
          'economic_key', pg_catalog.jsonb_build_object(
            'timesheet_id', CASE WHEN entry.economic_key_timesheet_id IS NULL THEN NULL ELSE entry.economic_key_timesheet_id::text END,
            'key_type', entry.economic_key_type,
            'key_value', entry.economic_key_value
          ),
          'preview_contract', COALESCE(preview_row.row_json->'preview_contract', '{}'::jsonb),
          'workbench_settled_certificate_binding_v8', pg_catalog.jsonb_build_object(
            'binding_contract_version', 'WORKBENCH_SETTLED_CERTIFICATE_BINDING_V8',
            'certificate_uuid', entry.certificate_uuid::text,
            'constituent_digest_sha256', entry.constituent_digest_sha256,
            'constituent_ordinal', entry.constituent_ordinal,
            'source_identity_digest_sha256', entry.source_identity_digest_sha256
          ),
          'draftable', true,
          'row_backed_draft_scope', true,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'effective', true
        )
      ) AS payload_json
    FROM selected_entries AS entry
    JOIN private.banking_pay_workbench_settled_certificates_v8 AS certificate_row
      ON certificate_row.certificate_uuid = entry.certificate_uuid
    JOIN public.banking_pay_workbench_preview_rows AS preview_row
      ON preview_row.id = entry.materialised_preview_row_id
     AND preview_row.session_id = certificate_row.workbench_session_id
     AND preview_row.candidate_id = entry.candidate_id
     AND preview_row.row_key = entry.row_key
     -- A34 (Worker BT, ruling 29): the SAME section rule the certificate used to admit this constituent
     -- (private.pay_workbench_settled_certificate_preview_contract_v8 certifies a repayment the V3 overlay promoted
     -- from blocked_for_pay to canonical_preview_lines). Was the physical section only, so every such repayment (the
     -- approved exclusion/reallocation rule, or oldest-first across debt types) ended WORKBENCH_CERTIFICATE_TAMPERED.
     AND private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json) = 'canonical_preview_lines'
     AND preview_row.selected IS TRUE
     AND preview_row.selection_state = 'SELECTED'
     AND preview_row.status = 'READY'
     AND preview_row.session_version = certificate_row.session_version
     AND preview_row.timesheet_id IS NOT DISTINCT FROM entry.timesheet_id
     -- A34: a repayment row published into blocked_for_pay carries NULL physical key columns; the certificate took its
     -- key from the row's own economic key with its existing ladder (economic_key, key_type, component_key_type) --
     -- the SAME ladder, not a new one (Policy X). Rows with physical key columns are matched exactly as before.
     AND (
       preview_row.key_type = entry.economic_key_type
       OR (
         preview_row.key_type IS NULL
         AND pg_catalog.upper(NULLIF(pg_catalog.btrim(COALESCE(preview_row.row_json#>>'{economic_key,key_type}',
               preview_row.row_json->>'key_type', preview_row.row_json->>'component_key_type', '')), '')) = entry.economic_key_type
       )
     )
     AND (
       preview_row.key_value = entry.economic_key_value
       OR (
         preview_row.key_value IS NULL
         AND NULLIF(pg_catalog.btrim(COALESCE(preview_row.row_json#>>'{economic_key,key_value}',
               preview_row.row_json->>'key_value', preview_row.row_json->>'component_key_value', '')), '') = entry.economic_key_value
       )
     )
  )
  INSERT INTO private.banking_pay_draft_frozen_constituent_payloads_v8(
    operation_id, constituent_ordinal, certificate_uuid, preview_row_id,
    candidate_id, resolved_pay_channel, timesheet_id, finance_case_id,
    row_key, row_ordinal, payload_json, payload_digest_sha256
  )
  SELECT p_operation_id, payload.constituent_ordinal, payload.certificate_uuid,
    payload.preview_row_id, payload.candidate_id, payload.resolved_pay_channel,
    payload.timesheet_id, payload.finance_case_id, payload.row_key, payload.row_ordinal,
    payload.payload_json,
    pg_catalog.encode(extensions.digest(pg_catalog.convert_to(payload.payload_json::text, 'UTF8'), 'sha256'), 'hex')
  FROM frozen_payloads AS payload
  ON CONFLICT (operation_id, constituent_ordinal) DO NOTHING;

  IF (
    SELECT pg_catalog.count(*)
    FROM private.banking_pay_draft_frozen_constituent_payloads_v8 AS payload
    JOIN private.banking_pay_draft_frozen_constituent_refs_v8 AS ref
      ON ref.operation_id = payload.operation_id
     AND ref.constituent_ordinal = payload.constituent_ordinal
    WHERE payload.operation_id = p_operation_id
      AND ref.staged_page_sequence = v_page_sequence
  ) <> v_row_count THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_TAMPERED'
      USING ERRCODE = 'P0001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'WORKBENCH_CERTIFICATE_TAMPERED',
        'operation_id', p_operation_id,
        'stage_kind', v_stage_kind,
        'reason', 'FROZEN_CONSTITUENT_PAYLOAD_COUNT_MISMATCH'
      )::text;
  END IF;

  v_receipt_preimage := '{"after_ordinal":' || COALESCE(pg_catalog.to_jsonb(p_after_ordinal)::text, 'null')
    || ',"has_more":' || pg_catalog.to_jsonb(v_has_more)::text
    || ',"next_after_ordinal":' || COALESCE(pg_catalog.to_jsonb(v_next_after)::text, 'null')
    || ',"operation_id":' || pg_catalog.to_jsonb(p_operation_id::text)::text
    || ',"page_digest_sha256":' || pg_catalog.to_jsonb(v_page_digest)::text
    || ',"page_sequence":' || v_page_sequence::text
    || ',"request_preimage_digest_sha256":' || pg_catalog.to_jsonb(v_request_digest)::text
    || ',"requested_limit":' || v_limit::text
    || ',"row_count":' || v_row_count::text
    || ',"stage_kind":' || pg_catalog.to_jsonb(v_stage_kind)::text || '}';
  v_receipt_digest := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(v_receipt_preimage, 'UTF8'), 'sha256'), 'hex');

  INSERT INTO private.banking_pay_draft_frozen_stage_receipts_v8(
    operation_id, stage_kind, page_sequence, after_ordinal, requested_limit,
    expected_previous_receipt_sha256, request_preimage_digest_sha256, row_count,
    canonical_byte_count, next_after_ordinal, has_more, terminal_sentinel_present,
    receipt_digest_sha256, stage_status
  ) VALUES (
    p_operation_id, v_stage_kind, v_page_sequence, p_after_ordinal, v_limit,
    p_expected_previous_receipt_sha256, v_request_digest, v_row_count,
    v_canonical_bytes, v_next_after, v_has_more, true,
    v_receipt_digest, CASE WHEN v_has_more THEN 'COMMITTED' ELSE 'TERMINAL' END
  );

  RETURN pg_catalog.jsonb_build_object(
    'operation_id', p_operation_id,
    'stage_kind', v_stage_kind,
    'page_sequence', v_page_sequence,
    'after_ordinal', p_after_ordinal,
    'row_count', v_row_count,
    'canonical_byte_count', v_canonical_bytes,
    'page_receipt_digest_sha256', v_receipt_digest,
    'next_after_ordinal', v_next_after,
    'has_more', v_has_more,
    'terminal_sentinel_present', true,
    'stage_total_count', v_scope.constituent_count,
    'stage_total_digest_sha256', v_scope.selected_constituents_digest_sha256,
    'replayed', false
  );
END;
$function$;

-- ---------------------------------------------------------------------------------------------------
-- 5. jit = off and the A25 ACL convention for every new and changed routine
-- ---------------------------------------------------------------------------------------------------
ALTER FUNCTION public.pay_preview_candidate_build_finance_case_baseline(jsonb,uuid) SET jit = off;
ALTER FUNCTION private.pay_workbench_recovery_selection_overlay_apply_v1(uuid,uuid,jsonb) SET jit = off;
ALTER FUNCTION public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid) SET jit = off;
ALTER FUNCTION public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid,jsonb) SET jit = off;
ALTER FUNCTION private.pay_workbench_modal_blocked_presentation_v2(jsonb,jsonb) SET jit = off;
ALTER FUNCTION public.pay_workbench_draft_certificate_constituent_ref_page_v8(uuid,integer,integer,text) SET jit = off;
REVOKE ALL ON FUNCTION private.s3p_recovery_age_key_v1(text,timestamp with time zone,timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION private.s3p_recovery_order_key_v1(uuid) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION private.pay_workbench_recovery_type_capped_allocate_v1(uuid,date,jsonb) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION private.pay_workbench_recovery_selection_overlay_apply_v1(uuid,uuid,jsonb) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION private.pay_workbench_modal_blocked_presentation_v2(jsonb,jsonb) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.pay_preview_candidate_build_finance_case_baseline(jsonb,uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.pay_preview_candidate_build_finance_case_baseline(jsonb,uuid) TO service_role;
REVOKE ALL ON FUNCTION public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid) TO service_role;
REVOKE ALL ON FUNCTION public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid,jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid,jsonb) TO service_role;
REVOKE ALL ON FUNCTION public.pay_workbench_draft_certificate_constituent_ref_page_v8(uuid,integer,integer,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.pay_workbench_draft_certificate_constituent_ref_page_v8(uuid,integer,integer,text) TO service_role;

-- ---------------------------------------------------------------------------------------------------
-- 6. Fail-closed verification (catalogue and a pure first-use call only; reads no application rows)
-- ---------------------------------------------------------------------------------------------------
DO $a34_verify$
DECLARE
  v_bad text;
  v_modal jsonb;
BEGIN
  WITH expected(sig, svc) AS (
    SELECT sig, false FROM (VALUES
    ('private.s3p_recovery_age_key_v1(text,timestamp with time zone,timestamp with time zone)'),
    ('private.s3p_recovery_order_key_v1(uuid)'),
    ('private.pay_workbench_recovery_type_capped_allocate_v1(uuid,date,jsonb)'),
    ('private.pay_workbench_recovery_selection_overlay_apply_v1(uuid,uuid,jsonb)'),
    ('private.pay_workbench_modal_blocked_presentation_v2(jsonb,jsonb)')) o(sig)
    UNION ALL
    SELECT sig, true FROM (VALUES
    ('public.pay_preview_candidate_build_finance_case_baseline(jsonb,uuid)'),
    ('public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid)'),
    ('public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid,jsonb)'),
    ('public.pay_workbench_draft_certificate_constituent_ref_page_v8(uuid,integer,integer,text)')) s(sig)
  ), checked AS (
    SELECT e.sig, pg_catalog.to_regprocedure(e.sig) AS oid, e.svc FROM expected e
  )
  SELECT pg_catalog.string_agg(c.sig, ', ' ORDER BY c.sig) INTO v_bad
  FROM checked c
  LEFT JOIN pg_catalog.pg_proc p ON p.oid = c.oid
  WHERE c.oid IS NULL
     OR pg_catalog.has_function_privilege('anon', p.oid, 'EXECUTE')
     OR pg_catalog.has_function_privilege('authenticated', p.oid, 'EXECUTE')
     OR pg_catalog.has_function_privilege('service_role', p.oid, 'EXECUTE') <> c.svc
     OR EXISTS (SELECT 1 FROM pg_catalog.aclexplode(COALESCE(p.proacl, pg_catalog.acldefault('f', p.proowner))) a
                WHERE a.grantee <> p.proowner
                  AND NOT (c.svc AND a.grantee = 'service_role'::pg_catalog.regrole AND a.privilege_type = 'EXECUTE'))
     OR NOT ('jit=off' = ANY(COALESCE(p.proconfig, '{}'::text[])))
     OR NOT EXISTS (SELECT 1 FROM pg_catalog.unnest(COALESCE(p.proconfig, '{}'::text[])) s WHERE s LIKE 'search\_path=%');
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'ZX999', MESSAGE = 'A34_CLOSURE_FAILED', DETAIL = v_bad;
  END IF;

  -- source guards: the order key is used by all four ordering routines (the overlay through the allocator); the
  -- legacy blocker and the allocator call are in the overlay; the freeze uses the certificate's section rule
  IF (SELECT pg_catalog.count(*) FROM pg_catalog.pg_proc p
      WHERE p.oid IN ('public.pay_preview_candidate_build_finance_case_baseline(jsonb,uuid)'::pg_catalog.regprocedure, 'private.pay_workbench_recovery_type_capped_allocate_v1(uuid,date,jsonb)'::pg_catalog.regprocedure,
                      'public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid)'::pg_catalog.regprocedure, 'public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid,jsonb)'::pg_catalog.regprocedure)
        AND p.prosrc LIKE '%private.s3p_recovery_order_key_v1(%') <> 4
     OR (SELECT p.prosrc FROM pg_catalog.pg_proc p WHERE p.oid = 'private.pay_workbench_recovery_selection_overlay_apply_v1(uuid,uuid,jsonb)'::pg_catalog.regprocedure)
        NOT LIKE '%legacy.components_missing%private.pay_workbench_recovery_type_capped_allocate_v1(%'
     OR (SELECT p.prosrc FROM pg_catalog.pg_proc p WHERE p.oid = 'public.pay_workbench_draft_certificate_constituent_ref_page_v8(uuid,integer,integer,text)'::pg_catalog.regprocedure)
        NOT LIKE '%private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json)%'
     OR EXISTS (SELECT 1 FROM pg_catalog.pg_proc p
                WHERE p.oid IN ('public.pay_preview_candidate_build_finance_case_baseline(jsonb,uuid)'::pg_catalog.regprocedure, 'private.pay_workbench_recovery_selection_overlay_apply_v1(uuid,uuid,jsonb)'::pg_catalog.regprocedure,
                                'public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid)'::pg_catalog.regprocedure, 'public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid,jsonb)'::pg_catalog.regprocedure,
                                'private.pay_workbench_modal_blocked_presentation_v2(jsonb,jsonb)'::pg_catalog.regprocedure, 'private.s3p_recovery_age_key_v1(text,timestamp with time zone,timestamp with time zone)'::pg_catalog.regprocedure,
                                'private.s3p_recovery_order_key_v1(uuid)'::pg_catalog.regprocedure, 'private.pay_workbench_recovery_type_capped_allocate_v1(uuid,date,jsonb)'::pg_catalog.regprocedure,
                                'public.pay_workbench_draft_certificate_constituent_ref_page_v8(uuid,integer,integer,text)'::pg_catalog.regprocedure)
                  AND pg_catalog.lower(p.prosrc) ~ 'pg_catalog\.(coalesce|nullif|least|greatest)\(') THEN
    RAISE EXCEPTION USING ERRCODE = 'ZX999', MESSAGE = 'A34_SOURCE_GUARD_FAILED';
  END IF;

  -- first use of the two pure routines (no table read): the age key and the Office reason text
  IF private.s3p_recovery_age_key_v1('OVERPAYMENT', '2026-09-20 09:00:00+00', NULL)
       >= private.s3p_recovery_age_key_v1('OVERPAYMENT', '2026-09-20 15:00:00+00', NULL)
     OR private.s3p_recovery_age_key_v1('PAYMENT_ADVANCE', '2026-09-20 12:00:00+00', '2026-09-10 12:00:00+00')
       >= private.s3p_recovery_age_key_v1('MANUAL_DEBT_ADJUSTMENT', '2026-09-15 12:00:00+00', NULL) THEN
    RAISE EXCEPTION USING ERRCODE = 'ZX999', MESSAGE = 'A34_AGE_KEY_FIRST_USE_FAILED';
  END IF;
  -- first use of the type-capped allocator (a Candidate id that does not exist: no floor, nothing paid this week)
  IF (SELECT pg_catalog.string_agg(a.recoverable_amount_ex_vat::text || ':' || COALESCE(a.cap_reason, '-'), ',' ORDER BY a.recoverable_amount_ex_vat DESC)
      FROM private.pay_workbench_recovery_type_capped_allocate_v1(
        '00000000-0000-4000-8000-00000000a034'::uuid, '2026-10-02'::date,
        '[{"id":"00000000-0000-4000-8000-000000000001","pay_channel":"UMBRELLA","line_type":"MANUAL_DEBT_RECOVERY","row_ordinal":1,"nominal_due_amount_ex_vat":80,"headroom_ex_vat":100,"eligible":true,"excluded":false},
          {"id":"00000000-0000-4000-8000-000000000002","pay_channel":"UMBRELLA","line_type":"OVERPAYMENT_RECOVERY","row_ordinal":2,"nominal_due_amount_ex_vat":80,"headroom_ex_vat":100,"eligible":true,"excluded":false}]'::jsonb) AS a)
     IS DISTINCT FROM '80.00:-,20.00:PAY_HEADROOM' THEN
    RAISE EXCEPTION USING ERRCODE = 'ZX999', MESSAGE = 'A34_ALLOCATOR_FIRST_USE_FAILED';
  END IF;
  v_modal := private.pay_workbench_modal_blocked_presentation_v2(
    pg_catalog.jsonb_build_object('line_type', 'OVERPAYMENT_RECOVERY', 'amount_ex_vat', 0, 'nominal_due_amount_ex_vat', 40,
      'blocked_reason_codes', pg_catalog.jsonb_build_array('LEGACY_FINANCE_CASE_COMPONENTS_MISSING'),
      'presentation_reason', 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING', 'case_components', '[]'::jsonb),
    '{}'::jsonb);
  IF v_modal->>'reason' IS DISTINCT FROM 'Legacy finance case needs component records - Office review'
     OR v_modal->>'affected_display_amount' IS DISTINCT FROM '40.00' THEN
    RAISE EXCEPTION USING ERRCODE = 'ZX999', MESSAGE = 'A34_MODAL_FIRST_USE_FAILED', DETAIL = v_modal::text;
  END IF;
END
$a34_verify$;

COMMIT;
